import type { LernEinheit, LernKapitel } from "@/lib/curriculum";
import type { Aktivitaet } from "@/lib/aktivitaeten";
import { findeBegriffe } from "@/lib/glossar";

// Eigenständig redigierte Lernschritte. Die IDs verweisen ausdrücklich auf
// vorhandene Lektionen und Aufgaben; fachübergreifende Bezüge sind beabsichtigt.
function zuordnen(titel: string, paare: [string, string][], erklaerung: string): Aktivitaet {
  return { id: "", version: 1, typ: "zuordnen", titel,
    auftrag: "Ordne jedem Eintrag die passende Aussage zu.",
    paare: paare.map(([links, rechts], i) => ({ id: `p${i + 1}`, links, rechts })), erklaerung };
}
function ordnen(titel: string, schritte: string[], erklaerung: string): Aktivitaet {
  return { id: "", version: 1, typ: "reihenfolge", titel,
    auftrag: "Ordne die Arbeitsschritte mit den Pfeil-Schaltflächen.",
    schritte: schritte.map((text, i) => ({ id: `s${i + 1}`, text })), erklaerung };
}
function fall(titel: string, situation: string, optionen: [string, boolean][], erklaerung: string, skizze?: string): Aktivitaet {
  return { id: "", version: 1, typ: skizze ? "skizzenfehler" : "baustellenfall", titel,
    auftrag: "Wähle alle fachlich passenden Aussagen. Mehrere Antworten können stimmen.",
    situation, optionen: optionen.map(([text, korrekt], i) => ({ id: `o${i + 1}`, text, korrekt })), erklaerung,
    ...(skizze ? { svg: skizze, bildbeschreibung: situation } : {}) };
}
function einheit(lektionId: string, titel: string, lernziel: string, text: string,
  aufgabenIds: string[], abrufFrage: string, abrufMuster: string, aktivitaet: Aktivitaet,
  begriffe: string[] = [], nummer = 1): LernEinheit {
  const id = `${lektionId}-e${String(nummer).padStart(2, "0")}`;
  return { id, version: 2, titel, lernziel, minuten: 7, textschritte: [text],
    lektionIds: [lektionId], aufgabenIds, abrufFrage, abrufMuster, begriffe: [...new Set([...begriffe, ...findeBegriffe(text).map((b) => b.id)])],
    aktivitaet: { ...aktivitaet, id: `${id}-aktiv` } };
}

const falschesDreieck = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 200"><title>Fehlerhafte Winkelsumme</title><path d="M60 155H400L220 30Z" fill="none" stroke="currentColor" stroke-width="3"/><g fill="currentColor" font-family="sans-serif" font-size="20"><text x="90" y="145">60°</text><text x="330" y="145">45°</text><text x="205" y="70">90°?</text></g></svg>';
const falscheDachskizze = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 220"><title>Verwechselte Beschriftung am Dachquerschnitt</title><path d="M50 175L250 40L450 175ZM250 40V175" fill="none" stroke="currentColor" stroke-width="3"/><g fill="currentColor" font-family="sans-serif" font-size="18"><text x="65" y="95">A: Sparren</text><text x="265" y="115">B: Firsthöhe</text><text x="75" y="205">C: ganze Breite?</text></g></svg>';
const kreuzfuge = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 180"><title>Fehlerhafter Verband mit durchgehenden Stoßfugen</title><g fill="none" stroke="currentColor" stroke-width="3"><path d="M30 30H470V150H30ZM30 70H470M30 110H470M140 30V150M250 30V150M360 30V150"/></g><text x="35" y="175" font-family="sans-serif" font-size="16" fill="currentColor">Alle senkrechten Fugen liegen übereinander.</text></svg>';

const lf01: LernKapitel[] = [
  { id: "lf01-k01", titel: "Beruf, Beteiligte und Planung", einheiten: [
    einheit("lf01-l01", "Wer entscheidet, plant und baut?", "Du kannst die Rollen am Bau unterscheiden und eine notwendige Abstimmung zwischen Gewerken erklären.",
      "Bei einem Bauvorhaben greifen viele Arbeiten ineinander. Der Bauherr beauftragt das Vorhaben. Das Planungsbüro entwickelt die Planung und die Zeichnungen. Die ausführenden Betriebe setzen die vereinbarten Arbeiten um. Die Bauaufsicht hat eine andere Aufgabe: Sie überwacht öffentlich-rechtliche Anforderungen. Für dich wird das an einer Dachöffnung konkret. Der Zimmerer stellt die geplante Holzkonstruktion her; der Dachdecker schließt die Deckung und ihre Anschlüsse an. Beide brauchen denselben freigegebenen Planstand. Ändert sich die Öffnung, muss die Änderung vor der Ausführung abgestimmt werden. Eine ungeklärte Vorleistung verschwindet nicht durch schnelleres Weiterarbeiten. Benenne deshalb zuerst die betroffene Arbeit, dann den zuständigen Beteiligten und schließlich den nötigen Zeitpunkt der Abstimmung.",
      ["lf01-026", "lf01-033"], "Warum müssen Zimmerer und Dachdecker eine geänderte Dachöffnung gemeinsam abstimmen?", "Tragkonstruktion und Deckungsanschluss müssen zum gleichen Planstand passen. Die Vorleistung und der Arbeitsbeginn müssen zeitlich aufeinander abgestimmt sein.",
      zuordnen("Rollen auseinanderhalten", [["Bauherr", "Beauftragt das Bauvorhaben"], ["Planungsbüro", "Erstellt Planung und Zeichnungen"], ["Baubetrieb", "Führt vereinbarte Bauarbeiten aus"], ["Bauaufsicht", "Überwacht öffentlich-rechtliche Anforderungen"]], "Eine fachliche Änderung wird mit den zuständigen Beteiligten vor der Ausführung abgestimmt.")),
    einheit("lf01-l06", "Drei Lernorte und die Organisation des Handwerks", "Du kannst Betrieb, Berufsschule und überbetriebliche Ausbildung sowie Innung und ZVDH ihren Aufgaben zuordnen.",
      "Deine Dachdeckerausbildung dauert drei Jahre. Dual bedeutet, dass Betrieb und Berufsschule zusammenwirken. Im Betrieb übst du praktische Fertigkeiten und lernst Arbeitsabläufe kennen. Die Berufsschule vermittelt fachliche Zusammenhänge und weitere schulische Kenntnisse. Überbetriebliche Ausbildungsstätten ergänzen die Ausbildung, etwa wenn ein Betrieb bestimmte Verfahren selten ausführt. Auch das Handwerk organisiert sich auf mehreren Ebenen. Betriebe können einer Dachdeckerinnung angehören. Die Innungen wirken unter anderem an der Ausbildung und am Prüfungswesen mit. Darüber stehen Landesinnungsverbände und der Zentralverband des Deutschen Dachdeckerhandwerks, kurz ZVDH. Trenne dabei Lernort und Organisation: Eine Innung ist kein Ersatz für die Berufsschule. Bei einer Ausbildungsfrage hilft dir diese Ordnung, die passende Ansprechstelle zu finden.",
      ["lf01-001", "lf01-008", "lf01-031", "lf01-043"], "Was bedeutet dual, und welche Aufgabe hat die überbetriebliche Ausbildung?", "Betrieb und Berufsschule sind die beiden Lernorte. Überbetriebliche Ausbildung ergänzt die dort vermittelten Kenntnisse und Fertigkeiten.",
      zuordnen("Wer unterstützt deine Ausbildung?", [["Betrieb", "Praktische Fertigkeiten im Arbeitsalltag"], ["Berufsschule", "Theorie und schulische Kenntnisse"], ["Überbetriebliche Ausbildung", "Ergänzende praktische Ausbildungsinhalte"], ["ZVDH", "Bundesweite Dachorganisation des Dachdeckerhandwerks"]], "Lernorte vermitteln Ausbildung; Verbände und Innungen unterstützen und organisieren das Handwerk."), ["lf01-008"]),
    einheit("lf01-l07", "Genehmigung, Vertrag und Bauzeitenplan lesen", "Du kannst Bauantrag, Vergabe und prüfbare Abrechnung unterscheiden und parallele Arbeiten im Bauzeitenplan erkennen.",
      "Zum Bauantrag gehören Unterlagen, mit denen die zuständige Stelle das Vorhaben prüfen kann: etwa Lageplan, Entwurfszeichnungen, Baubeschreibung und erforderliche Nachweise. Das Angebot eines Unternehmens gehört dagegen zur Vergabe. Im hier behandelten genehmigungspflichtigen Bauvorhaben folgt die Ausführung auf die erteilte Genehmigung. Für den Auftrag werden Leistungen und Termine vereinbart; die VOB ist dafür ein wichtiges Regelwerk. Bei der Abrechnung muss die ausgeführte Leistung nachvollziehbar belegt werden, zum Beispiel durch Aufmaß und Zeichnungen. Der Bauzeitenplan ordnet die Gewerke zeitlich. Addierst du alle angegebenen Arbeitstage, erhältst du den gesamten Arbeitsumfang dieser Vorgänge. Die tatsächliche Bauzeit kann kürzer sein, wenn Arbeiten gleichzeitig laufen. Prüfe deshalb zusätzlich die Lage der Balken im Plan.",
      ["lf01-002", "lf01-007", "lf01-026", "lf01-033"], "Warum ist die Summe aller Arbeitstage nicht automatisch die gesamte Bauzeit?", "Mehrere Gewerke können gleichzeitig arbeiten. Die Bauzeit ergibt sich aus dem zeitlichen Ablauf und seinen Abhängigkeiten, nicht allein aus der Summe.",
      fall("33 Arbeitstage im Plan", "Alle Vorgänge ergeben zusammen 33 Arbeitstage. Im Balkenplan überschneiden sich mehrere Gewerke.", [["Die tatsächliche Dauer kann unter 33 Arbeitstagen liegen.", true], ["Abhängige Vorleistungen müssen trotzdem rechtzeitig fertig sein.", true], ["Aus der Summe folgt zwingend ein Fertigstellungstermin nach 33 Tagen.", false]], "Eine Summe beschreibt Arbeitsumfang; der Ablaufplan zeigt zusätzlich Parallelität und Abhängigkeiten."), ["lf01-002"]),
    einheit("lf01-l02", "Eine Baustelle mit kurzen, sicheren Wegen planen", "Du kannst Kran, Lager, Zufahrt und Versorgung im Baustelleneinrichtungsplan begründet anordnen.",
      "Bevor Material geliefert wird, braucht die Baustelle eine durchdachte Einrichtung. Im Baustelleneinrichtungsplan werden Zufahrten, Lagerflächen, Kran, Unterkünfte sowie Strom und Wasser eingezeichnet. Ein angegebener Maßstab macht Entfernungen prüfbar; Sinnbilder kennzeichnen die Einrichtungen. Beginne beim Materialfluss: Wo kommt die Lieferung an, wo wird sie sicher abgeladen und wie gelangt sie an die Einbaustelle? Schwere Baustoffe sollten erreichbar liegen, ohne Verkehrswege zu blockieren. Gleichzeitig müssen Personen ihre Arbeitsplätze sicher erreichen können. Kurze Wege sparen Zeit, dürfen aber keine gefährlichen Kreuzungen erzwingen. Prüfe den Plan deshalb einmal aus Sicht einer Lieferung und einmal aus Sicht eines gehenden Beschäftigten. So fallen Engstellen und ungünstige Lagerflächen früh auf.",
      ["lf01-003", "lf01-027", "lf01-036"], "Welche zwei Wege verfolgst du bei der Prüfung einer Baustelleneinrichtung?", "Den Materialweg von der Anlieferung zur Einbaustelle und den sicheren Personenweg zum Arbeitsplatz.",
      ordnen("Materialfluss vorbereiten", ["Zufahrt und mögliche Entladestelle im Plan prüfen", "Kranreichweite und geeignete Lagerfläche zuordnen", "Sichere Verkehrswege und Versorgung abstimmen", "Einrichtung vor der ersten Lieferung kontrollieren"], "Lager und Kran werden gemeinsam geplant; freie und sichere Wege bleiben Teil derselben Aufgabe."), ["lf01-027"]),
  ] },
  { id: "lf01-k02", titel: "Baustellenbetrieb sicher vorbereiten", einheiten: [
    einheit("lf01-l03", "Gefahren nach STOP verringern", "Du kannst Schutzmaßnahmen nach ihrer Wirksamkeit ordnen und technische Sicherung vor persönlicher Ausrüstung prüfen.",
      "Bei einer Gefahr suchst du zuerst nach einer Lösung, die möglichst viele Menschen zuverlässig schützt. Das STOP-Prinzip gibt dir dafür eine Reihenfolge. Substitution bedeutet, eine gefährliche Tätigkeit oder einen gefährlichen Stoff durch eine weniger gefährliche Lösung zu ersetzen. Technische Maßnahmen wirken an der Gefahrenstelle, etwa ein geeigneter Seitenschutz gegen Absturz. Organisatorische Maßnahmen regeln den Ablauf, zum Beispiel Unterweisungen und abgesperrte Bereiche. Persönliche Schutzausrüstung wirkt an der einzelnen Person und erfordert korrekte Auswahl und Anwendung. Ein Auffanggurt rechtfertigt deshalb nicht, eine mögliche technische Sicherung wegzulassen. Entscheidend ist die konkrete Gefährdungsbeurteilung. Benenne bei einem Fall zuerst die Gefahr und prüfe anschließend die wirksameren Maßnahmen, bevor du nur Ausrüstung auswählst.",
      ["lf03-048", "lf02-100"], "Warum beginnt die Auswahl einer Absturzsicherung nicht einfach beim Auffanggurt?", "Zuerst werden Gefahrenvermeidung sowie technische und organisatorische Maßnahmen geprüft. Persönliche Ausrüstung steht in der STOP-Rangfolge zuletzt.",
      ordnen("Wirksamkeit hat Vorrang", ["Gefahr vermeiden oder ungefährlicher ersetzen", "Technische Schutzmaßnahme vorsehen", "Arbeitsablauf organisatorisch absichern", "Erforderliche persönliche Schutzausrüstung ergänzen"], "Die Reihenfolge beschreibt die Prüfung der Schutzmaßnahmen. Mehrere Maßnahmen können zusammen erforderlich bleiben.")),
    einheit("lf01-l08", "Kranbereich und knappen Lagerplatz organisieren", "Du kannst eine Anlieferung bei wenig Lagerplatz planen und Kranbereich, Aufenthaltsbereich und Verkehrsabsicherung unterscheiden.",
      "Ein Kran nützt wenig, wenn schwere Paletten außerhalb seiner vorgesehenen Reichweite stehen. Ordne deshalb Bauwerk, schwere Baustoffe und Ladezone im abgestimmten Arbeitsbereich an. Unterkünfte und andere Aufenthaltsflächen werden getrennt davon geplant. Bei einer engen innerörtlichen Baustelle kann eine Lieferung genau zum Einbauzeitpunkt sinnvoll sein: Der Lkw bringt das benötigte Material, und der abgestimmte Transport führt es direkt weiter. Das nennt man Just-in-time-Anlieferung. Sie braucht eine verlässliche Absprache, weil kaum Pufferfläche vorhanden ist. Kommt öffentlicher Verkehr hinzu, muss die dafür festgelegte Absicherung eingerichtet sein. Die im Lehrbeispiel genannten Schranken und Warnleuchten gehören zu dessen Verkehrsführung. Übertrage sie nicht ungeprüft auf jede andere Baustellensituation.",
      ["lf01-003", "lf01-013", "lf01-020", "lf01-027"], "Was muss bei einer Just-in-time-Lieferung besonders gut abgestimmt sein?", "Lieferzeit, freie Ladezone, Transportmittel und Einbaubereitschaft müssen zusammenpassen, weil kaum Zwischenlager vorhanden ist.",
      fall("Der Lkw kommt zu früh", "Auf einer engen Baustelle trifft eine Ziegellieferung ein. Die vorgesehene Ladezone ist noch gesperrt, ein Gehweg wäre frei.", [["Die Anlieferung und den freigegebenen Entladebereich neu abstimmen.", true], ["Den Gehweg ohne abgestimmte Verkehrsführung als Lager nutzen.", false], ["Vor dem Abladen Kranreichweite und freien Materialweg prüfen.", true]], "Zeitgewinn durch Direktanlieferung funktioniert nur mit einem sicheren, verfügbaren Materialweg."), ["lf01-027"]),
    einheit("lf01-l10", "Ausladung und Traglast beim Kran verstehen", "Du kannst die Hauptteile eines Turmdrehkrans benennen und erklären, weshalb die Traglast von der Ausladung abhängt.",
      "Am Turmdrehkran trägt der senkrechte Turm den Ausleger. Auf dem Ausleger bewegt sich die Laufkatze; an ihr hängt über das Hubseil der Lasthaken. Der Ballast bildet das Gegengewicht. Die Ausladung ist die waagerechte Entfernung zwischen Drehachse und Last. Wird diese Entfernung größer, wächst die Hebelwirkung derselben Last. Deshalb darf der Kran außen meist weniger heben als nahe am Turm. Für den tatsächlichen Einsatz zählt die passende Traglasttabelle, nicht eine geschätzte Palettenmasse. Ein Schnellaufbaukran kann bei kurzen Einsätzen Vorteile beim Aufbau bieten; auch er braucht geeignete Einsatzbedingungen. Lastaufnahmemittel dienen dem vorgesehenen Materialtransport. Steinkörbe und ähnliche Hilfsmittel sind kein improvisierter Personenaufzug. Unklare Transportaufgaben werden vor dem Heben geklärt.",
      ["lf01-009", "lf01-014", "lf01-024", "lf01-046"], "Warum darfst du eine nahe am Turm zulässige Last nicht automatisch am äußeren Auslegerende heben?", "Die größere Ausladung vergrößert das Lastmoment. Die zulässige Traglast muss für genau diese Ausladung aus den Einsatzangaben geprüft werden.",
      zuordnen("Kranbauteile und Aufgaben", [["Turm", "Trägt den hochliegenden Ausleger"], ["Laufkatze", "Verändert die Lage des Hakens auf dem Ausleger"], ["Ballast", "Wirkt als Gegengewicht"], ["Traglasttabelle", "Gibt zulässige Lasten für Einsatzbedingungen an"]], "Die Bauteilnamen helfen beim Lesen der Darstellung; für das Heben gelten die konkreten Einsatzangaben."), ["lf01-046"]),
  ] },
  { id: "lf01-k03", titel: "Messen, Zeichnen und Projektmaße", einheiten: [
    einheit("lf01-l09", "Geraden und rechte Winkel abstecken", "Du kannst Messband, Fluchtstab und Kreuzscheibe unterscheiden und einen rechten Winkel mit einem 3:4:5-Dreieck prüfen.",
      "Beim Abstecken wird eine geplante Geometrie auf die Baustelle übertragen. Ein Messband liefert die Länge. Fluchtstäbe markieren Messpunkte; durch Einfluchten bringst du weitere Punkte auf dieselbe Gerade. Eine Kreuzscheibe hilft, dazu einen rechten Winkel anzupeilen. Auch ein Dreieck im Verhältnis 3:4:5 erzeugt einen rechten Winkel. Beispiel: Die Seiten 6 m, 8 m und 10 m haben dieses Verhältnis. Der rechte Winkel liegt zwischen den Seiten 6 m und 8 m. Die längste Seite ist die Hypotenuse. Kontrolliere mit 6² + 8² = 10². Vorher müssen alle Längen dieselbe Einheit haben: Ein Meter entspricht 100 cm beziehungsweise 1000 mm. Schiefe Stäbe und wechselnde Bezugspunkte verfälschen selbst eine richtige Rechnung.",
      ["lf01-004", "lf01-010", "lf01-016", "lf01-030"], "Zwischen welchen Seiten eines 6:8:10-Dreiecks liegt der rechte Winkel?", "Zwischen den Seiten 6 und 8. Die Seite 10 ist die Hypotenuse; 36 + 64 = 100 bestätigt den rechten Winkel.",
      ordnen("Einen Bauwinkel kontrollieren", ["Gerade und eindeutigen Ausgangspunkt festlegen", "Zwei Seiten im Verhältnis 3 zu 4 abmessen", "Abstand ihrer Endpunkte auf den Anteil 5 einstellen", "Längen, Einheiten und Lage des rechten Winkels prüfen"], "Ein gemeinsamer Maßfaktor erhält das Verhältnis 3:4:5. Der rechte Winkel liegt den fünf Anteilen gegenüber."), ["lf01-016", "lf01-030"]),
    einheit("lf01-l05", "Maßstab und Zeichensprache richtig lesen", "Du kannst Maßstabsstrecken umrechnen und verdeckte Kanten sowie Rohbau- und Fertighöhen unterscheiden.",
      "Eine Bauzeichnung muss von allen Beteiligten gleich verstanden werden. Lies zuerst Planart, Maßstab und Maßangaben. Bei 1:50 entspricht ein Zentimeter im Plan 50 Zentimetern am Gebäude. Für eine echte Länge von 6 m rechnest du zunächst 600 cm und teilst dann durch 50: Im Plan sind das 12 cm. Umgekehrt wird eine Planlänge mit der Maßstabszahl multipliziert. Maßzahlen, Querschnittszeichen und Linien liefern zusätzliche Informationen. Ø kennzeichnet den Durchmesser; eine Strichlinie zeigt verdeckte Kanten. Eine Strichpunktlinie hat eine andere Bedeutung, etwa die Mittellinie. Bei den hier verwendeten Höhendreiecken steht offen für die Fertighöhe und schwarz für die Rohbauhöhe. Prüfe diese Bezugshöhe, bevor du daraus ein Anschlussmaß ableitest.",
      ["lf01-005", "lf01-011", "lf01-034", "lf01-039"], "Wie wird aus einer wirklichen Länge von 6 m bei 1:50 eine Planlänge?", "6 m in 600 cm umrechnen und durch 50 teilen: 12 cm. Die Gegenprobe ist 12 cm × 50 = 600 cm.",
      zuordnen("Was sagt das Zeichen?", [["Ø", "Durchmesser eines runden Querschnitts"], ["Strichlinie", "Verdeckte Kante"], ["Offenes Höhendreieck", "Fertige Höhenlage in dieser Zeichensprache"], ["1:50", "Ein Planmaß entspricht dem Fünfzigfachen in Wirklichkeit"]], "Zeichen und Maßstab liefern verschiedene Informationen. Beide müssen vor der Ausführung gelesen werden."), ["lf01-022"]),
    einheit("lf01-l11", "Hausfläche und Projekthöhe nachvollziehbar prüfen", "Du kannst Grundfläche und Planlänge berechnen und eine projektspezifische Traufhöhenvorgabe mit den richtigen Bezugspunkten lesen.",
      "Bei einem rechteckigen Haus erhältst du die überbaute Grundfläche aus Länge mal Breite. Im Buchbeispiel ergeben 12,50 m mal 7,25 m genau 90,625 m². Das ist eine Fläche; eine Traufhöhe ist dagegen eine Länge. Die genannte Höhengrenze von 5,50 m gehört zur Baubeschreibung dieses Beispielprojekts. Sie wird vom gewachsenen Boden bis zur Traufe gemessen, nicht bis zum First. Für eine Zeichnung brauchst du zusätzlich den Maßstab. Eine echte Wand von 10 m wird bei 1:125 zunächst in 1000 cm umgerechnet. 1000 geteilt durch 125 ergibt 8 cm auf dem Papier. Halte Fläche, Höhe und Planlänge als getrennte Ergebnisse fest. Runde erst so spät, wie es die Aufgabenstellung verlangt.",
      ["lf01-015", "lf01-038", "lf01-040"], "Warum ist die Angabe 5,50 m aus dieser Aufgabe keine allgemeine zulässige Haushöhe?", "Sie ist eine Vorgabe der konkreten Baubeschreibung und hat festgelegte Bezugspunkte: gewachsener Boden bis Traufe.",
      fall("Drei Angaben kontrollieren", "Im Beispiel stehen 90,625 m² Grundfläche, 5,50 m Höhenbegrenzung bis Traufe und Maßstab 1:125.", [["Die Höhenbegrenzung gehört zu diesem Projekt.", true], ["10 m Wandlänge werden im Plan zu 8 cm.", true], ["Die Grundfläche beschreibt die Entfernung vom Boden zum First.", false]], "Einheiten und Bezugspunkte machen deutlich, ob Fläche, Bauhöhe oder Zeichnungslänge gemeint ist.")),
  ] },
  { id: "lf01-k04", titel: "Geometrie konstruieren und prüfen", einheiten: [
    einheit("lf01-l04", "Winkel im Dreieck und an Geraden prüfen", "Du kannst Winkelarten erkennen und fehlende Neben- und Dreieckswinkel berechnen.",
      "Ein rechter Winkel hat 90 Grad. Kleinere Winkel heißen spitz; Winkel zwischen 90 und 180 Grad heißen stumpf. Diese Einteilung hilft dir beim schnellen Prüfen einer Skizze. Nebenwinkel ergänzen sich zu 180 Grad. Zu 125 Grad gehört deshalb ein Nebenwinkel von 55 Grad. Auch die drei Innenwinkel eines Dreiecks ergeben zusammen 180 Grad. Sind zwei Winkel 60 und 45 Grad groß, bleiben für den dritten 75 Grad. Verwechsle diese Summe nicht mit einem einzelnen rechten Winkel. An zwei parallelen Geraden sind entsprechend gleich liegende Stufenwinkel gleich groß. Der direkt benachbarte Winkel ist wiederum der Nebenwinkel. Markiere vor jeder Rechnung, welche Winkel tatsächlich gegeben und gesucht sind; die Lage entscheidet über die richtige Beziehung.",
      ["lf01-006", "lf01-017", "lf01-021", "lf01-035"], "Ein Dreieck enthält 60 und 45 Grad. Wie groß ist der dritte Winkel, und wie prüfst du ihn?", "180 − 60 − 45 = 75 Grad. Die Probe lautet 60 + 45 + 75 = 180 Grad.",
      fall("Der dritte Winkel ist falsch", "Die Skizze zeigt ein Dreieck mit 60 Grad, 45 Grad und dem fraglichen Eintrag 90 Grad am oberen Punkt.", [["Die drei Einträge ergeben zusammen 195 Grad und passen nicht.", true], ["Der obere Winkel muss 75 Grad betragen.", true], ["Jedes Dreieck hat automatisch oben einen rechten Winkel.", false]], "Nicht das Aussehen der Zeichnung entscheidet, sondern die Innenwinkelsumme von 180 Grad.", falschesDreieck), ["lf01-035"]),
    einheit("lf01-l04", "Mittelsenkrechte und Schwerpunkt konstruieren", "Du kannst die Mittelsenkrechte konstruieren und sie von einer Seitenhalbierenden unterscheiden.",
      "Eine Mittelsenkrechte halbiert eine Strecke und steht senkrecht auf ihr. Stelle den Zirkel auf mehr als die halbe Streckenlänge ein. Schlage mit derselben Einstellung Kreisbögen um beide Endpunkte. Die Bögen schneiden sich oberhalb und unterhalb der Strecke. Verbindest du diese Schnittpunkte, erhältst du die Mittelsenkrechte. Jeder Punkt dieser Geraden hat denselben Abstand zu beiden Endpunkten. Eine Seitenhalbierende im Dreieck ist etwas anderes: Sie verbindet einen Eckpunkt mit der Mitte der gegenüberliegenden Seite. Die drei Seitenhalbierenden treffen sich im Schwerpunkt. Eine Seitenhalbierende muss nicht senkrecht auf der Seite stehen. Achte deshalb auf den Arbeitsauftrag: Geht es um gleiche Abstände zu zwei Punkten oder um den Schwerpunkt eines Dreiecks? Davon hängt deine Konstruktion ab.",
      ["lf01-012", "lf01-037", "lf01-042"], "Worin unterscheiden sich Mittelsenkrechte und Seitenhalbierende?", "Die Mittelsenkrechte steht senkrecht auf einer Strecke in deren Mitte. Die Seitenhalbierende verbindet eine Dreiecksecke mit der Mitte der gegenüberliegenden Seite.",
      ordnen("Die Mittelsenkrechte entsteht", ["Zirkelradius größer als die halbe Strecke wählen", "Mit gleicher Öffnung Bögen um beide Endpunkte schlagen", "Beide Schnittpunkte der Bögen markieren", "Schnittpunkte verbinden und rechten Winkel prüfen"], "Die unveränderte Zirkelöffnung sichert gleiche Abstände zu den Endpunkten."), ["lf01-012", "lf01-042"], 2),
    einheit("lf01-l04", "Stabile Dreiecke und regelmäßige Vielecke", "Du kannst Dreiecke nach Seiten unterscheiden und ein regelmäßiges Sechseck mithilfe seines Umkreises erklären.",
      "Ein Dreieck behält bei festen Seitenlängen seine Form. Deshalb begegnet es dir in Verstrebungen und Dachkonstruktionen. Beim Viereck kann sich die Form ohne zusätzliche Aussteifung leichter verschieben. Nach den Seitenlängen unterscheidest du gleichseitige Dreiecke mit drei gleich langen Seiten, gleichschenklige mit zwei gleich langen Seiten und ungleichseitige mit verschiedenen Seiten. Bei einem regelmäßigen Vieleck sind sämtliche Seiten und Innenwinkel gleich groß. Besonders praktisch ist das regelmäßige Sechseck: Seine Seitenlänge entspricht dem Radius des Umkreises. Du kannst diese Zirkelöffnung deshalb sechsmal auf dem Kreis abtragen. Verbinde danach die benachbarten Punkte. Kontrolliere, ob der sechste Schritt wieder zum Anfang führt; eine ungenaue Zirkeleinstellung zeigt sich dort besonders deutlich.",
      ["lf01-025", "lf01-028", "lf01-032", "lf01-044"], "Warum lässt sich ein regelmäßiges Sechseck mit unveränderter Zirkelöffnung im Umkreis abtragen?", "Die Sechseckseite ist genauso lang wie der Radius des Umkreises. Dieser Abstand passt sechsmal auf den Kreis.",
      zuordnen("Figuren sicher unterscheiden", [["Gleichseitiges Dreieck", "Drei gleich lange Seiten"], ["Gleichschenkliges Dreieck", "Zwei gleich lange Seiten"], ["Regelmäßiges Vieleck", "Alle Seiten und alle Innenwinkel sind gleich groß"], ["Regelmäßiges Sechseck", "Seitenlänge entspricht dem Umkreisradius"]], "Das Wort regelmäßig beschreibt Seiten und Winkel gemeinsam; gleiche Seiten allein reichen bei einem Vieleck nicht."), [], 3),
  ] },
];

const lf02: LernKapitel[] = [
  { id: "lf02-k01", titel: "Dachformen, Wasserweg und Brandverhalten", einheiten: [
    einheit("lf02-l01", "Dachform erkennen und Wasser verfolgen", "Du kannst die wichtigsten Dachformen unterscheiden und First, Traufe, Ortgang, Grat und Kehle am Wasserweg erklären.",
      "Beginne bei einem unbekannten Dach mit der Zahl und Lage seiner Flächen. Ein Satteldach besitzt zwei geneigte Dachflächen. Beim Pultdach ist es eine, beim Walmdach sind auch die Giebelseiten geneigt. Ein Zeltdach führt seine Flächen zu einer Spitze. Danach benennst du die Kanten. Der First liegt oben, die Traufe unten und der Ortgang seitlich am Giebel. Ein Grat ist eine vorspringende Schnittlinie zweier Dachflächen; eine Kehle springt nach innen ein. Diese Wörter beschreiben zugleich den Wasserweg: Wasser läuft über die Fläche nach unten, in einer Kehle kommt es von zwei Seiten zusammen. Erkläre deshalb nicht nur den Namen, sondern auch die Lage und die Aufgabe der betrachteten Stelle.",
      ["lf02-001", "lf02-002", "lf02-003", "lf02-101"], "Was unterscheidet Grat und Kehle, und wo sammelt sich Wasser?", "Der Grat springt nach außen vor, die Kehle nach innen ein. In der Kehle sammelt sich Wasser von beiden angrenzenden Flächen.",
      zuordnen("Namen am Dach", [["First", "Obere waagerechte Schnittlinie"], ["Traufe", "Untere Dachkante mit ablaufendem Wasser"], ["Ortgang", "Seitliche Dachkante am Giebel"], ["Kehle", "Einspringende Schnittlinie mit zusammenlaufendem Wasser"]], "Richtige Bauteilnamen helfen beim Planlesen, beim Aufmaß und bei der Verständigung am Dach."), ["lf02-002", "lf02-003"]),
    einheit("lf02-l12", "Fläche, Linie und Punkt in der Dachausmittlung", "Du kannst eine Draufsicht des Walmdachs als Flächen, Linien und Punkte lesen und besondere Wasseranfallsstellen erkennen.",
      "Eine Dachausmittlung zeigt das Dach von oben. Ihre Flächen werden von Linien begrenzt; Linien treffen sich in Punkten. Beim einfachen Walmdach erkennst du einen First in der Mitte, Grate zu den Gebäudeecken und die umlaufende Traufe. Die geneigten Walmflächen ersetzen die senkrechten Giebel eines Satteldachs. Ein Ortgang gehört daher nicht automatisch an jede gezeichnete Außenkante. Suche bei einem zusammengesetzten Dach zusätzlich die Kehlen. Dort fließt Wasser zweier Flächen zusammen, weshalb Anschluss und Wasserführung besondere Aufmerksamkeit brauchen. Aus einer Draufsicht allein liest du jedoch nicht jede tatsächliche Neigung ab. Ergänze deshalb Schnitt oder Höhenangaben, bevor du die Eignung eines Deckdetails beurteilst. Die Skizze ordnet das Dach, ersetzt aber keine vollständige Planung.",
      ["lf02-004", "lf02-006", "lf02-102"], "Welche drei geometrischen Bestandteile unterscheidest du in einer Dachausmittlung?", "Dachflächen, begrenzende Dachlinien und Dachpunkte als Anfang, Ende oder Schnittpunkt der Linien.",
      fall("Eine Walmdach-Draufsicht lesen", "Ein Plan zeigt einen kurzen mittleren First und vier schräge Linien zu den Hausecken. Ringsum liegt eine Trauflinie.", [["Die schrägen Außenkanten sind Grate.", true], ["Die Walmflächen ersetzen hier die Giebelseiten.", true], ["Jede schräge Linie muss eine wasserführende Kehle sein.", false]], "Die Richtung der Flächen zueinander entscheidet: vorspringend bedeutet Grat, einspringend bedeutet Kehle.")),
    einheit("lf02-l11", "Neigungsklassen und harte Bedachung trennen", "Du kannst eine benannte Dachneigungsklassifikation einordnen und harte Bedachung vom Brandverhalten einzelner Baustoffe unterscheiden.",
      "Die Bezeichnungen Flachdach und Steildach werden in Lehrwerken nicht immer mit denselben Winkelgrenzen verwendet. In der hier zitierten Buchklassifikation liegen die Übergänge bei 5 und 22 Grad. Nenne diese Quelle, wenn du mit ihren Grenzen arbeitest. Für den konkreten Dachaufbau reichen solche Sammelnamen nicht; Decksystem und tatsächliche Neigung müssen zusammenpassen. Auch das Wort harte Bedachung wird leicht missverstanden. Es bezeichnet den Widerstand gegen Flugfeuer und strahlende Wärme, keine fühlbare Materialhärte. Die Baustoffklasse eines einzelnen Materials beantwortet wiederum eine andere Frage. In der deutschen Einteilung steht A für nichtbrennbare Baustoffe; A1 enthält keine brennbaren Bestandteile. Beurteile deshalb Dachsystem, Deckungsnachweis und Materialklassifikation jeweils anhand der passenden Unterlagen.",
      ["lf02-007", "lf02-008", "lf02-012", "lf02-013"], "Warum bedeutet ein hart anzufassender Baustoff noch keine harte Bedachung?", "Harte Bedachung beschreibt das nachgewiesene Verhalten des Dachsystems gegenüber Flugfeuer und strahlender Wärme, nicht die mechanische Härte eines Materials.",
      zuordnen("Welche Frage wird beantwortet?", [["Neigungsklasse", "Ordnet den Dachwinkel nach einer genannten Einteilung ein"], ["Harte Bedachung", "Widersteht Flugfeuer und strahlender Wärme"], ["Baustoffklasse A1", "Nichtbrennbarer Baustoff ohne brennbare Bestandteile"], ["Decksystemwahl", "Prüft Material, tatsächliche Neigung und Einbaubedingungen gemeinsam"]], "Klassifikationen lassen sich nur mit derselben Bezugsfrage sinnvoll vergleichen.")),
    einheit("lf02-l13", "Ableiten und Abdichten unterscheiden", "Du kannst die Wasserführung einer überdeckenden Deckung und einer verbundenen Dachabdichtung erklären.",
      "Eine Ziegeldeckung besteht aus einzelnen Elementen, die sich schuppenförmig überdecken. Das Wasser läuft über diese Überdeckungen ab. Die Fugen bilden dabei keine geschlossene wasserdichte Haut. Deshalb gehören ausreichende Neigung und passende Zusatzmaßnahmen zum System. Bei einer Dachabdichtung werden Bahnen und ihre Anschlüsse dagegen so verbunden, dass eine durchgehende Abdichtung entsteht. Der Unterschied liegt in der Wirkungsweise, nicht allein im Namen des Daches. Auch eine Abdichtung braucht einen geplanten Wasserweg zu den Abläufen. Vergleiche bei einem Detail deshalb zuerst, ob Wasser über Elemente abgeleitet oder durch eine durchgehende Schicht zurückgehalten werden soll. Prüfe danach die Fugen und Anschlüsse. Eine einzelne unverbundene Bahn erfüllt die Aufgabe eines fertig abgedichteten Dachaufbaus noch nicht.",
      ["lf02-009", "lf02-010", "lf02-011"], "Warum brauchen schuppenförmig überdeckte Ziegel einen passenden Neigungsbereich?", "Ihre Fugen sind nicht geschlossen wasserdicht. Die Neigung unterstützt das sichere Ableiten des Wassers über die Überdeckungen.",
      zuordnen("Wie wirkt die Dachhaut?", [["Ziegeldeckung", "Leitet Wasser über sich überdeckende Einzelelemente ab"], ["Verbundene Abdichtungsbahnen", "Bilden mit dichten Anschlüssen eine durchgehende Abdichtung"], ["Überdeckungsfuge", "Ist keine beliebig wasserdichte Verbindung"], ["Dachentwässerung", "Führt das anfallende Wasser kontrolliert weiter"]], "Deckung oder Abdichtung: Ein nachvollziehbarer Wasserweg bleibt immer erforderlich.")),
  ] },
  { id: "lf02-k02", titel: "Regensicherheit und Windsog", einheiten: [
    einheit("lf02-l03", "Regeldachneigung und erhöhte Anforderungen prüfen", "Du kannst Regeldachneigung und Mindestdachneigung unterscheiden und Gründe für eine zusätzlich zu planende Maßnahme nennen.",
      "Die Regeldachneigung gehört zu einer bestimmten Deckungsart. Sie ist der Vergleichswert, ab dem diese unter den zugehörigen Bedingungen als regensicher gilt. Liegt das geplante Dach darunter, musst du die zusätzliche Sicherung unter der Deckung prüfen. Auch oberhalb der Regeldachneigung können erhöhte Anforderungen eine solche Maßnahme verlangen, etwa besondere Dachformen, lange Sparren oder eine stärker beanspruchte Lage. Mindestdachneigung und Regeldachneigung sind verschiedene Grenzen: Eine Zusatzmaßnahme erlaubt keine beliebige Unterschreitung. Die vorhandene Übersicht unterscheidet wasserdichte und regensichere Unterdächer sowie Unterdeckungen und Unterspannungen verschiedener Ausführung. Die Auswahl erfolgt mit der zutreffenden Fachregel und den Systemangaben. Ein einzelnes Stichwort wie Wohnraum ersetzt diese vollständige Prüfung nicht. Halte die verwendeten Randbedingungen schriftlich fest.",
      ["lf02-015", "lf02-016", "lf02-018"], "Warum ersetzt ein Unterdach nicht die Prüfung der Mindestdachneigung?", "Die Mindestdachneigung bleibt eine Systemgrenze. Eine Zusatzmaßnahme erhöht die Regensicherheit, macht aber nicht jede beliebige Neigung zulässig.",
      ordnen("Eine Deckung auswählen", ["Deckungsart und geplante Dachneigung feststellen", "Regel- und Mindestdachneigung des Systems nachschlagen", "Erhöhte Anforderungen für das Gebäude erfassen", "Passende Zusatzmaßnahme anhand der zutreffenden Vorgaben planen"], "Die Maßnahme folgt aus mehreren Randbedingungen; sie wird nicht allein anhand eines Produktnamens ausgewählt."), ["lf02-015", "lf02-018"]),
    einheit("lf02-l07", "Bahnen unter der Deckung als Wasserweg verstehen", "Du kannst die Aufgabe einer Vordeckung, Unterdeckung und Unterspannung erklären und notwendige Produktangaben benennen.",
      "Unter einer Deckung kann eine zusätzliche Bahn Wasser auffangen, das durch die Deckelemente gelangt. Damit sie diese Aufgabe erfüllt, müssen Überdeckungen, Befestigungen und Anschlüsse einen zusammenhängenden Weg zur Traufe bilden. Die Verlegung beginnt deshalb üblicherweise unten; obere Bahnen überdecken die unteren in Wasserlaufrichtung. Eine Vordeckung liegt auf einer flächigen Unterlage. Bei Unterdeck- und Unterspannbahnen sind außerdem die zulässige Unterlage und die Einbausituation zu prüfen. Der Produktname allein verrät nicht zuverlässig, wie stark Wasserdampf gebremst wird. Dafür liest du die technischen Angaben, insbesondere den sd-Wert und die vorgesehenen Anschlussdetails. Auch eine ausreichend große Überdeckung hilft wenig, wenn Wasser an einer Durchdringung hinter die Bahn geführt wird. Kontrolliere deshalb Fläche und Details gemeinsam.",
      ["lf02-034", "lf02-035", "lf02-036"], "Warum prüfst du neben der Überdeckung auch Durchdringungen und Traufanschluss?", "Nur zusammen entsteht ein durchgehender Wasserweg. Eine undichte Durchdringung oder ein falsch angeschlossener Rand kann Wasser hinter die Bahn führen.",
      ordnen("Wasserweg der Bahn prüfen", ["Zulässige Unterlage und Produkteigenschaften feststellen", "Untere Bahn mit geplantem Traufanschluss anordnen", "Obere Bahnen in Wasserlaufrichtung überdecken lassen", "Durchdringungen, Nähte und freien Ablauf kontrollieren"], "Überdeckungen werden als Teil eines vollständigen Systems betrachtet, nicht als einzelne Zahl.")),
    einheit("lf02-l07", "Unterdach, Fugenschluss und Anschluss unterscheiden", "Du kannst Unterdach, Docken und Verklammerung nach ihrer Aufgabe trennen und einen geeigneten Anschluss begründen.",
      "Bei einem Unterdach sind nicht nur die Bahnen entscheidend. Auch Konterlatten, Durchdringungen und Einfassungen gehören zum geplanten System. Ein wasserdichtes Unterdach verlangt eine entsprechend wasserdichte Einbindung dieser Details. Ein regensicheres Unterdach hat eine andere, dafür vorgesehene Ausführung. Übertrage deshalb keine Detailzeichnung ungeprüft von einem System auf das andere. Docken schließen bestimmte Fugen zwischen Deckelementen. Sie ersetzen jedoch keine erforderliche Zusatzmaßnahme unter der Deckung. Verklammerung erfüllt wiederum eine andere Aufgabe: Sie befestigt Deckelemente gegen Abheben. Auch beim Anschluss einer Luftdichtheitsebene brauchst du ein geeignetes, dauerhaft verbundenes System. Eine beliebige Schaumschicht ist kein verlässlich geplanter Folienanschluss. Ordne einem Problem deshalb zuerst die richtige Schutzfunktion zu, bevor du ein Material auswählst.",
      ["lf02-037", "lf02-038", "lf02-039", "lf02-040"], "Welche drei verschiedenen Aufgaben haben Unterdach, Docken und Verklammerung?", "Das Unterdach bietet zusätzliche Wasserführung, Docken schließen bestimmte Fugen, und Verklammerung sichert Deckelemente mechanisch gegen Abheben.",
      fall("Drei vermeintlich gleiche Lösungen", "Eine Kolonne schlägt vor, geforderte Unterdachdetails und Sturmklammern vollständig durch vermörtelte Fugen zu ersetzen.", [["Fugenschluss ersetzt die mechanische Befestigung nicht.", true], ["Die erforderliche Zusatzmaßnahme muss passend zum Dach geplant bleiben.", true], ["Alle Maßnahmen erfüllen unabhängig vom Aufbau dieselbe Aufgabe.", false]], "Regensicherheit, Fugenschluss und mechanische Befestigung haben unterschiedliche Funktionen."), [], 2),
    einheit("lf02-l04", "Randbereiche gegen Windsog sichern", "Du kannst besonders beanspruchte Dachbereiche erkennen und notwendige Angaben für einen Befestigungsplan nennen.",
      "Wind kann Druck auf eine Dachfläche ausüben und an anderen Stellen einen Sog erzeugen. Dieser Sog versucht Deckelemente anzuheben. Besonders Rand- und Eckbereiche sind oft stärker beansprucht als die übrige Fläche. Deshalb reicht eine gleichmäßig geschätzte Zahl von Klammern nicht aus. Für die Befestigungsplanung brauchst du unter anderem Gebäudegeometrie, Höhe, Dachform, örtliche Windbeanspruchung und das verwendete Decksystem. Die passende Klammer muss außerdem zum Ziegel und zur Unterkonstruktion gehören. Der Befestigungsplan zeigt, welche Bereiche wie gesichert werden. Mehr Mörtel in einer Fuge ersetzt diesen Nachweis nicht. Kontrolliere beim Eindecken fortlaufend, ob Bereich, Klammerart und Befestigungsabstand dem Plan entsprechen; nach der fertigen Fläche sind ausgelassene Klammern nur schwer zu erkennen.",
      ["lf02-038", "lf08-066", "lf08-067", "lf08-070"], "Warum kann am Ortgang eine andere Befestigung nötig sein als mitten in der Fläche?", "Randbereiche können stärkere Windsogkräfte erhalten. Die Sicherung wird deshalb nach Bereichen und den tatsächlichen Gebäude- und Systemdaten geplant.",
      fall("Ein Klammermuster für alles?", "Auf der Baustelle wird vorgeschlagen, dieselbe gelegentliche Verklammerung von der Fläche bis in alle Eckbereiche fortzuführen.", [["Zuerst den gebäude- und systembezogenen Befestigungsplan prüfen.", true], ["Besonders beanspruchte Randbereiche gesondert betrachten.", true], ["Die Windbeanspruchung hat mit der Lage eines Deckelements nichts zu tun.", false]], "Das Dach wird für die Befestigung in unterschiedlich beanspruchte Bereiche eingeteilt.")),
  ] },
  { id: "lf02-k03", titel: "Deckmaterial herstellen und beurteilen", einheiten: [
    einheit("lf02-l02", "Tonziegel und Betondachsteine unterscheiden", "Du kannst Dachziegel und Dachsteine nach Ausgangsstoff und Herstellung unterscheiden und Falz sowie Überdeckung erklären.",
      "Dachziegel und Dachsteine können auf dem fertigen Dach ähnlich aussehen. Ihre Herstellung ist verschieden: Dachziegel entstehen aus geformtem und gebranntem Ton. Betondachsteine enthalten Zement, Sand und Wasser und erhärten ohne Ziegelbrand. Innerhalb der Tonziegel gibt es unterschiedliche Formen. Beim Biberschwanz entsteht die Regensicherheit durch die zur Deckungsart gehörende mehrfache Überdeckung. Falzziegel besitzen geformte Ränder, die ineinandergreifen und Wasser führen. Mönch und Nonne bestehen aus sich ergänzenden Schalenelementen. Die Form bestimmt also mit, wie gedeckt und eingeteilt wird. Ein ähnlicher Farbton macht verschiedene Produkte nicht austauschbar. Prüfe bei Ersatzmaterial deshalb Hersteller, Modell, Deckmaße und die passende Deckungsart. Ein korrekt benannter Werkstoff ist der erste Schritt zu einer passenden Reparatur.",
      ["lf02-049", "lf02-050", "lf02-052", "lf02-063"], "Was unterscheidet einen Betondachstein von einem Dachziegel aus Ton?", "Der Dachziegel wird aus Ton gebrannt. Der Dachstein besteht aus zementgebundenem Feinbeton und erhärtet ohne Ziegelbrand.",
      zuordnen("Material und Wasserführung", [["Dachziegel", "Geformtes und gebranntes Tonprodukt"], ["Betondachstein", "Zementgebundenes Deckelement"], ["Falz", "Geformter Rand zum Ineinandergreifen und Wasserführen"], ["Biberschwanzdeckung", "Regensicherheit durch passende mehrfache Überdeckung"]], "Werkstoff, Form und Deckungsart müssen gemeinsam erkannt werden.")),
    einheit("lf02-l14", "Vom Tonrohling zum farbigen Dachziegel", "Du kannst die Herstellungsschritte ordnen und die Größenzugabe eines Rohlings sowie Engobe und Glasur unterscheiden.",
      "Ton wird für Dachziegel aufbereitet und unter anderem mit Quarzsand oder Ziegelmehl gemagert. Das begrenzt das Schwinden beim Trocknen und Brennen. Danach erhält der Rohling seine Form, etwa über eine Strangpresse oder eine Formpresse. Er wird getrocknet und gebrannt. Im vorliegenden Rechenbeispiel ist ein Rohling um zehn Prozent größer als das gewünschte Endmaß. Bei 440 mm Rohlingslänge erhältst du daher 440 geteilt durch 1,10 gleich 400 mm Endlänge. Einfach zehn Prozent von 440 abzuziehen wäre die falsche Bezugsgröße. Die Oberfläche kann zusätzlich gestaltet werden. Eine Engobe ist eine aufgetragene mineralische Schicht zur Oberflächengestaltung; eine Glasur bildet beim Brand eine glasartige Oberfläche. Die konkrete Produkteigenschaft wird anhand der Herstellerangaben beurteilt.",
      ["lf02-041", "lf02-042", "lf02-045", "lf02-046"], "Warum wird im Beispiel 440 durch 1,10 geteilt statt zehn Prozent von 440 abzuziehen?", "Die zehnprozentige Zugabe bezieht sich auf das kleinere Endmaß. Der Rohling entspricht 110 Prozent dieses Endmaßes.",
      ordnen("Ein Dachziegel entsteht", ["Ton aufbereiten und mit geeigneten Stoffen magern", "Größeren Rohling formen", "Rohling kontrolliert trocknen", "Ziegel brennen und entstandenes Endmaß prüfen"], "Die Zugabe wird vor dem Schwinden eingeplant. Farb- und Oberflächenbehandlung gehört zum jeweiligen Herstellungsverfahren.")),
    einheit("lf02-l15", "Biber, Schalen und Falzziegel erkennen", "Du kannst wichtige Ziegelformen anhand ihrer sichtbaren Merkmale unterscheiden und daraus Fragen für die Verlegung ableiten.",
      "Beim Biberschwanz siehst du eine weitgehend flache Platte mit unterschiedlich gestaltetem Fuß. Segment- und Rundschnitt sind häufige Formen. Das Berliner und das Süddeutsche Modell unterscheiden sich unter anderem in der Breite. Bei Mönch und Nonne liegt die Nonne als Rinne unten; der Mönch überdeckt die Stoßfugen als obere Schale. Die Hohlpfanne hat eine andere Deckgeometrie, bei der die Schnittausbildung zur gewählten Deckungsart passen muss. Falzziegel besitzen geformte Kopf- und Seitenbereiche, die Wasser führen. Ein Flachdachziegel heißt trotz seines Namens nicht, dass du ihn beliebig auf ein flaches Dach legen darfst. Prüfe stets Deckungsart, zulässige Neigung und Modellangaben. Auch Deckrichtung und Einteilung werden vom konkreten Produkt bestimmt.",
      ["lf02-047", "lf02-048", "lf02-050", "lf02-054"], "Wie liegen Mönch und Nonne, und was überdeckt der Mönch?", "Die Nonne liegt als untere Rinnenschale. Der Mönch liegt darüber und überdeckt die Stoßfugen zwischen den Nonnen.",
      zuordnen("Was erkennst du auf der Palette?", [["Biberschwanz", "Flache Form mit gestaltetem Fuß"], ["Nonne", "Untere wasserführende Schale"], ["Mönch", "Obere Schale über den Stoßfugen"], ["Falzziegel", "Deckelement mit geformten ineinandergreifenden Rändern"]], "Eine sichere Formzuordnung ist die Grundlage für Deckrichtung, Überdeckung und Materialbestellung.")),
    einheit("lf02-l08", "Lieferung prüfen und Formziegel zuordnen", "Du kannst Sicht-, Klang- und Hauprobe als einfache Hinweise einordnen und den Nutzen passender Formziegel erklären.",
      "Prüfe eine Ziegellieferung vor dem Einbau. Bei der Sichtprobe suchst du sichtbare Schäden und Auffälligkeiten. Eine Klangprobe kann auf Risse hinweisen: Ein auffällig dumpfer Klang ist ein Anlass für weitere Prüfung. Die Hauprobe ergänzt die Beurteilung des Materials. Diese Baustellenprüfungen ersetzen keine vorgeschriebene Produktprüfung, helfen aber, verdächtige Stücke auszusondern. Kennzeichnungen ermöglichen die Zuordnung zu Hersteller und Produkt. Oberflächenaussprengungen können durch eingeschlossene Kalkteilchen entstehen, die bei Feuchtigkeit reagieren und ihr Volumen vergrößern. Für Anschlüsse gibt es passende Formziegel, etwa am First, Ortgang oder an Durchdringungen. Sie müssen zum jeweiligen Modell gehören. Ein ähnlich gefärbter Formziegel ist noch kein passender Anschluss. Halte beschädigte oder unklare Ware getrennt und kläre die Verwendung vor dem Decken.",
      ["lf02-055", "lf02-058", "lf02-059", "lf02-060"], "Was machst du mit einem Ziegel, der bei der Klangprobe auffällig klingt?", "Ich verwende ihn nicht ungeprüft weiter, sondern sortiere ihn zur weiteren Beurteilung aus. Der Klang ist ein Hinweis auf mögliche Risse.",
      fall("Auffällige Palette", "Mehrere Ziegel zeigen Aussprengungen; ein weiterer klingt auffällig dumpf. Die Kolonne möchte die Stücke zwischen unbeschädigten Ziegeln verstecken.", [["Verdächtige Stücke vor dem Einbau getrennt beurteilen.", true], ["Kennzeichnung und Lieferzuordnung dokumentieren.", true], ["Eine verdeckte Einbaustelle beseitigt einen Materialschaden.", false]], "Die Qualitätskontrolle geschieht vor dem Einbau. Überdecken verändert die Materialeigenschaften nicht.")),
    einheit("lf02-l16", "Betondachsteine und Einbauteile systemgerecht wählen", "Du kannst die Besonderheiten von Dachsteinen und die drei Aufgabenbereiche von Einbauteilen erklären.",
      "Ein Betondachstein besteht aus zementgebundenem Feinbeton. Sein Decksystem unterscheidet sich von einem rundum verfalzten Tonziegel. Der zulässige Bereich der Höhenüberdeckung kann verschiedene Lattenabstände ermöglichen; diese Freiheit endet aber an den konkreten Systemgrenzen. Profilierte Fußbereiche erschweren das Einwehen von Staub oder Schnee, machen die Deckung jedoch nicht zur geschlossenen Abdichtung. Zusätzlich zur Flächendeckung brauchst du Einbauteile. Sie dienen der Sicherheit, schaffen eine Verbindung zwischen innen und außen oder bringen Licht in den Raum. Ein Sicherheitsdachhaken ist beispielsweise Teil einer geplanten Sicherung und braucht eine dafür geeignete Befestigung. Wähle jedes Teil nach Funktion, Deckmodell und Einbauunterlage aus. Die passende Farbe allein sagt weder etwas über Tragfähigkeit noch über einen regensicheren Anschluss aus.",
      ["lf02-062", "lf02-064", "lf02-065", "lf02-068"], "Nach welchen drei Aufgaben werden Einbauteile unterschieden?", "Sicherheit, Verbindung zwischen innen und außen sowie Belichtung der Räume unter dem Dach.",
      zuordnen("Einbauteil mit passender Aufgabe", [["Sicherheitsdachhaken", "Sicherung mit dafür vorgesehener Befestigung"], ["Dachdurchführung", "Verbindung eines Bauteils zwischen innen und außen"], ["Dachflächenfenster", "Bringt Licht in den Dachraum"], ["Zulässiger Lattenabstand", "Wird aus dem konkreten Decksystem bestimmt"]], "Auch Einbauteile müssen zum Decksystem und zu ihrer Beanspruchung passen.")),
  ] },
  { id: "lf02-k04", titel: "Unterkonstruktion und Dachöffnungen", einheiten: [
    einheit("lf02-l06", "Traglatte und Konterlatte haben verschiedene Aufgaben", "Du kannst Trag- und Konterlatten unterscheiden und Holzqualität, Stützweite und Befestigung als zusammenhängende Auswahl prüfen.",
      "Die Traglatten tragen die Deckelemente. Die Konterlatten verlaufen darunter entlang der Sparren und schaffen den geplanten Abstand zwischen Deckung und Zusatzmaßnahme. Dieser Raum kann Wasserführung und Belüftung unterstützen. Beide Latten sind damit Teile des Dachaufbaus und keine beliebig austauschbaren Leisten. Für ihre Auswahl brauchst du geeignete Holzsortierung, Feuchte, Querschnitt, Stützweite und Befestigung. Eine größere freie Stützweite belastet die Latte stärker. Deshalb darfst du einen bekannten Regelquerschnitt nicht einfach auf weiter auseinanderliegende Sparren übertragen. Die erforderliche Eindringtiefe eines Verbindungsmittels hängt unter anderem von dessen Art und Durchmesser ab. Prüfe deshalb die passende Ausführungsregel oder den Nachweis. Eine einzelne passende Maßzahl genügt nicht, wenn Holzqualität oder Verbindung nicht stimmen.",
      ["lf02-026", "lf02-028", "lf02-029", "lf02-030"], "Was musst du außer dem Lattenquerschnitt prüfen?", "Holzsortierung und Feuchte, freie Stützweite, Art der Verbindungsmittel sowie ihre erforderliche Befestigung im Untergrund.",
      fall("Andere Sparrenabstände", "Eine bekannte Lattenausführung soll auf ein Dach mit größeren Sparrenabständen übertragen werden. Ein Nachweis liegt dafür nicht vor.", [["Querschnitt, Stützweite und Befestigung erneut gemeinsam prüfen.", true], ["Die größere Stützweite ist eine veränderte Beanspruchung.", true], ["Die alte Ausführung passt automatisch, weil dieselben Ziegel verwendet werden.", false]], "Deckelement, tragende Latte und Verbindung bilden einen Lastweg; jede geänderte Randbedingung ist zu prüfen.")),
    einheit("lf02-l06", "Schalung passend auswählen und prüfen", "Du kannst den Zusammenhang zwischen Unterkonstruktionsabstand, Schalungsdicke und Holzverformung erklären.",
      "Eine Holzschalung bildet eine flächige Unterlage. Zwischen ihren Auflagern muss sie Lasten tragen und ausreichend formstabil bleiben. Wird der Abstand der Unterkonstruktion größer, kann deshalb eine dickere Schalung oder ein besonderer Nachweis nötig werden. Vergleiche die vorhandenen Abstände mit den dafür geltenden Ausführungsangaben. Auch die Brettbreite beeinflusst das Verhalten: Sehr breite Bretter können stärker schüsseln und sich verwerfen. Die Lage der Jahrringe hilft, eine mögliche Verformungsrichtung zu erkennen. Prüfe außerdem Fehlkanten, Beschädigungen und die Auflage auf den Sparren. Die Schalung muss zum nachfolgenden Befestigungssystem passen. Beginne erst mit der Deckung, wenn die Unterlage kontrolliert ist; später verdeckte Fehler lassen sich nur aufwendig beheben.",
      ["lf02-027", "lf02-031", "lf02-032", "lf02-033"], "Warum wird bei größerem Auflagerabstand die gleiche dünne Schalung nicht automatisch weiterverwendet?", "Die Schalung muss eine größere Strecke frei überspannen. Tragfähigkeit und Verformung müssen deshalb für den geänderten Abstand geprüft werden.",
      ordnen("Die Schalungsunterlage kontrollieren", ["Abstände und Zustand der Unterkonstruktion aufnehmen", "Passende Schalungsart und Dicke anhand der Vorgaben prüfen", "Bretter auf Breite, Schäden und mögliche Verformung prüfen", "Auflage und Befestigung vor der Deckung kontrollieren"], "Die Unterlage wird vor dem Verdecken geprüft, weil ihre Trag- und Befestigungsfunktion später schwer zugänglich ist."), [], 2),
    einheit("lf02-l09", "Eine Öffnung braucht einen geplanten Lastweg", "Du kannst die Aufgabe eines Wechsels erklären und die Auswirkungen einer Dachöffnung auf Konstruktion und Anschluss benennen.",
      "Gauben und Dachflächenfenster bringen Licht oder zusätzlichen Raum. Gleichzeitig unterbrechen sie den bisherigen Dachaufbau. Eine Schleppgaube hat ein geneigtes Dach, eine Satteldachgaube zwei Dachflächen; die Fledermausgaube bildet einen geschwungenen Übergang. Für jede Öffnung prüfst du zuerst Lage, Größe und Tragkonstruktion. Muss ein Sparren unterbrochen werden, fängt ein geplanter Wechsel die Last oberhalb und unterhalb der Öffnung ab und leitet sie weiter. Dabei können benachbarte Sparren zusätzlich beansprucht werden. Sie werden daher nicht allein nach Augenmaß verändert. Anschließend werden Deckung, Zusatzmaßnahme, Dämmung und innere Anschlüsse geplant. Die im Lehrbeispiel genannten Raum- und Fenstermaße gehören zu dessen Bedingungen. Ein zugesagtes Wunschmaß ersetzt die konstruktive Prüfung des vorhandenen Daches nicht.",
      ["lf02-021", "lf02-022", "lf02-024", "lf02-025"], "Welche Aufgabe hat der Wechsel bei einem unterbrochenen Sparren?", "Er fängt die unterbrochenen Sparrenteile ab und überträgt ihre Lasten auf die dafür vorgesehenen benachbarten Bauteile.",
      fall("Fenster nach Wunschmaß", "Ein großes Dachfenster soll eingesetzt werden. Dafür müssten mehrere Sparren ohne vorhandene Detailplanung durchtrennt werden.", [["Vor dem Eingriff Tragkonstruktion und Lastweiterleitung planen lassen.", true], ["Auch Wasserführung und innere Anschlüsse der Öffnung berücksichtigen.", true], ["Sparren zunächst abschneiden und den Wechsel später nach Bedarf ergänzen.", false]], "Die Last muss vor dem Eingriff einen geplanten sicheren Weg erhalten."), ["lf02-024"]),
  ] },
  { id: "lf02-k05", titel: "Gefahren erkennen und Arbeitsplätze sichern", einheiten: [
    einheit("lf02-l05", "Freileitungen vor dem Materialtransport klären", "Du kannst die Gefahr durch elektrische Freileitungen erkennen und Sicherheitsabstand, Materialbewegung und Zuständigkeit gemeinsam berücksichtigen.",
      "Elektrische Freileitungen sind auch gefährlich, wenn du sie nicht direkt berührst. Bei Annäherung können Stromüberschläge entstehen. Lange Dachlatten, Leitern oder Kranlasten vergrößern den Bereich, den du beim Transport überblicken musst. Feuchtes Material kann zusätzlich leitfähig werden. Kläre deshalb vor Beginn die Leitung, ihre Spannung und die festgelegten Schutzmaßnahmen mit den zuständigen Stellen. In den vorhandenen Übungsaufgaben wird bei unbekannter Spannung mit dem größten genannten Sicherheitsabstand von 5 m gearbeitet. Dieser Abstand muss für Personen, Werkzeuge und mögliche Bewegungen eingehalten werden. Ein Helm oder trockene Handschuhe machen eine unzulässige Annäherung nicht sicher. Bei unklarer Situation wird der gefährdete Transport unterbrochen und fachlich abgestimmt, bevor weitergearbeitet wird.",
      ["lf02-085", "lf02-086", "lf02-087", "lf02-088"], "Warum kann eine lange nasse Dachlatte in Leitungsnähe besonders gefährlich sein?", "Sie kann beim Schwenken in den gefährlichen Bereich gelangen und durch Feuchtigkeit leitfähig sein. Die gesamte Bewegung muss im Schutzkonzept berücksichtigt werden.",
      fall("Unbekannte Leitung", "Lange feuchte Latten sollen nahe einer Freileitung gedreht werden. Die Spannung ist nicht bekannt.", [["Transport unterbrechen und Leitung sowie Schutzmaßnahmen klären.", true], ["Die gesamte Länge und mögliche Schwenkbewegung berücksichtigen.", true], ["Ein Helm erlaubt es, die Latte näher an die Leitung zu führen.", false]], "Der Abstand gilt für die gesamte Arbeitssituation. Persönliche Ausrüstung beseitigt die elektrische Gefahr nicht.")),
    einheit("lf02-l05", "Leitern und Dachhaken vor der Nutzung prüfen", "Du kannst sichere Benutzung von Anlege- und Dachauflegeleitern begründen und ungeeignete Befestigungen erkennen.",
      "Eine Leiter muss zur vorgesehenen Aufgabe passen. Eine Anlegeleiter braucht einen sicheren Stand, einen passenden Anstellwinkel und einen gesicherten Austritt. Die vorhandenen Übungswerte unterscheiden dabei Sprossen- und Stufenleitern. Eine Dachauflegeleiter liegt dagegen auf der Dachfläche und wird in dafür vorgesehene, fachgerecht befestigte Sicherheitsdachhaken eingehängt. Sie wird nicht in eine Dachrinne gestellt. Auch das Zusammenbinden ungeeigneter Leitern schafft keine zulässige Verlängerung. Prüfe vor jeder Benutzung sichtbare Schäden, Stand beziehungsweise Einhängung und die vorgesehenen Belastungsgrenzen. Ein fehlender Haken wird nicht durch einen zufälligen anderen Dachbauteil ersetzt. Der sichere Zugang ist Teil des Arbeitsplatzes; ist er unklar oder beschädigt, wird die Arbeit erst nach der Klärung begonnen.",
      ["lf02-089", "lf02-090", "lf02-092", "lf02-093"], "Warum ist eine Dachrinne kein geeigneter Ersatz für den vorgesehenen Dachhaken?", "Sie ist kein dafür vorgesehenes und nachgewiesen befestigtes Sicherungsbauteil. Die Dachauflegeleiter braucht ihre geeignete Einhängung.",
      ordnen("Vor dem Aufsteigen", ["Geeignete Leiter für Zugang oder Dachfläche auswählen", "Leiter und vorgesehenes Befestigungsbauteil auf Mängel prüfen", "Stand, Anstellung oder Einhängung vorschriftsgemäß herstellen", "Zugang und zulässige Nutzung vor dem Betreten kontrollieren"], "Die Prüfung geschieht vor jeder Benutzung; ein vorhandenes Dachbauteil ist nicht automatisch ein geeigneter Anschlag."), [], 2),
    einheit("lf02-l05", "Arbeitsplatz und Fangschutz zusammen planen", "Du kannst sicheren Arbeitsplatz, Seitenschutz und Fangschutz unterscheiden und Absturzgefahren nach außen sowie nach innen berücksichtigen.",
      "Auf einer geneigten Dachfläche brauchst du einen geeigneten Arbeitsplatz und eine passende Sicherung gegen Absturz. Dachdeckerstühle können einen Arbeitsbelag tragen, sind aber nicht automatisch für zusätzlich angebrachte Geländerpfosten ausgelegt. Solche Anbauten können ihre Standsicherheit beeinträchtigen. Schutzwände und Fanglagen erfüllen eigene Aufgaben und müssen passend zur Neigung, möglichen Fallhöhe und Arbeitssituation geplant werden. Prüfe außerdem die Öffnungen innerhalb des Gebäudes. Eine geringe Dachneigung beseitigt die Gefahr eines Absturzes durch eine Öffnung nicht. Dafür können zum Beispiel fachgerecht geplante Fangnetze oder Fanggerüste erforderlich sein. Vor der Nutzung kontrollierst du die vorgesehene Sicherung und meldest Veränderungen. Ein Arbeitsplatz wird nicht dadurch sicher, dass die Kolonne dort bisher ohne Unfall gearbeitet hat.",
      ["lf02-096", "lf02-098", "lf02-099", "lf02-100"], "Warum prüfst du bei einer Dacharbeit auch die Absturzgefahr nach innen?", "Öffnungen können unabhängig von der Dachneigung einen Absturz ins Gebäude ermöglichen. Die äußere Sicherung schützt diesen Weg nicht automatisch.",
      fall("Sicherung nur an der Traufe", "Eine Dachfläche besitzt einen gesicherten äußeren Rand. In der Fläche liegt eine ungesicherte Öffnung über dem Gebäudeinneren.", [["Die innere Öffnung braucht eine dafür geeignete Sicherung.", true], ["Den vorhandenen Randsschutz und die Sicherung der Öffnung getrennt prüfen.", true], ["Der äußere Randsschutz verhindert automatisch jeden inneren Absturz.", false]], "Jeder mögliche Absturzweg braucht eine passende Maßnahme. Außenkante und Öffnung sind verschiedene Gefahrenstellen."), [], 3),
  ] },
  { id: "lf02-k06", titel: "Dachmaße berechnen und kontrollieren", einheiten: [
    einheit("lf02-l10", "Erst die Form erkennen, dann rechnen", "Du kannst Dreiecks- und Trapezflächen sowie Sparrenlängen mit geeigneten Hilfsgrößen berechnen.",
      "Wähle die Formel erst, wenn die gesuchte Form klar ist. Ein Giebeldreieck hat die Fläche Grundlinie mal zugehörige senkrechte Höhe geteilt durch zwei. Beim Trapez bildest du zuerst den Mittelwert der parallelen Seiten und multiplizierst ihn mit ihrem senkrechten Abstand. Eine schräge Dachfläche ist nicht automatisch ein Dreieck. Für eine Sparrenlänge nutzt du das rechtwinklige Dreieck aus waagerechtem Grundmaß und Firsthöhe: s = √(g² + h²). Beim symmetrischen Satteldach ist g die halbe Gebäudebreite. Alle Längen müssen in derselben Einheit stehen. Eine Länge erhält Meter, eine Fläche Quadratmeter. Beim Wechsel zwischen benachbarten Flächeneinheiten wirkt der Faktor 100. Kontrolliere am Ende Formel, Hilfsgröße und Einheit getrennt voneinander.",
      ["lf02-072", "lf02-081", "lf02-082", "lf02-083"], "Welche Hilfsgröße brauchst du für die Sparrenlänge eines symmetrischen Satteldachs?", "Das Grundmaß g als halbe Gebäudebreite. Mit der Firsthöhe h gilt s = √(g² + h²).",
      zuordnen("Welche Rechnung passt?", [["Giebeldreieck", "Grundlinie × senkrechte Höhe ÷ 2"], ["Trapezfläche", "Mittelwert der parallelen Seiten × Abstand"], ["Sparren bei bekanntem g und h", "√(g² + h²)"], ["Grundmaß am symmetrischen Satteldach", "Halbe Gebäudebreite"]], "Die geometrische Zuordnung geht jeder Zahlenrechnung voraus.")),
    einheit("lf02-l17", "Gefälle in Prozent und als Verhältnis", "Du kannst Prozentgefälle, Höhenunterschied und Verhältnis 1:n umrechnen und die Einheiten prüfen.",
      "Drei Prozent Gefälle bedeuten drei Längeneinheiten Höhenunterschied auf 100 gleiche Längeneinheiten waagerechter Strecke. Für eine Strecke von 12 m rechnest du h = 3 × 12 ÷ 100 = 0,36 m. Das sind 36 cm. Umgekehrt erhältst du p = h × 100 ÷ Länge, wenn beide Längen dieselbe Einheit haben. Bei 0,30 m Höhenunterschied auf 6 m ergeben sich fünf Prozent. Das Verhältnis 1:20 beschreibt denselben Anstieg: 100 geteilt durch 20 ergibt fünf Prozent. Prozent und Grad sind verschiedene Angaben. Erst bei 45 Grad sind Höhe und waagerechte Strecke gleich groß; das entspricht 100 Prozent. Schreibe die verwendete Angabe deshalb ausdrücklich dazu, damit eine Zahl nicht versehentlich als Winkel gelesen wird.",
      ["lf02-073", "lf02-074", "lf02-075"], "Wie groß ist der Höhenunterschied bei drei Prozent Gefälle auf 12 m?", "3 × 12 ÷ 100 = 0,36 m, also 36 cm. Prozentgefälle bezieht sich auf die waagerechte Strecke.",
      fall("Fünf Prozent sind fünf Grad?", "Auf einer Skizze steht 1:20. Ein Kollege trägt dafür ohne weitere Rechnung 5 Grad ein.", [["1:20 entspricht fünf Prozent.", true], ["Prozent und Grad dürfen nicht direkt gleichgesetzt werden.", true], ["Die Angabe fünf Grad folgt allein aus 100 ÷ 20.", false]], "Die Rechnung 100 ÷ n liefert Prozent, keinen Winkel in Grad.")),
    einheit("lf02-l17", "Dachrand an einem versprungenen Grundriss messen", "Du kannst den Dachrand als Summe aller Randstrecken ermitteln und die Bedingungen einer Rechteckabkürzung prüfen.",
      "Der Dachrand ist eine Länge. Du erhältst ihn zuverlässig, indem du jede Randstrecke der Draufsicht einmal erfasst und addierst. Bei einem Rechteck gilt U = 2 × Länge + 2 × Breite. Im vorgegebenen Übungsgrundriss ersetzen rechtwinklige Versprünge lediglich entsprechende Strecken des umschließenden Rechtecks; deshalb bleibt dessen Umfang erhalten. Diese Abkürzung ist keine allgemeine Regel für jeden rechtwinkligen Grundriss. Ein zusätzlicher tiefer Einschnitt kann den Rand verlängern. Verfolge daher die Linie einmal vollständig mit dem Finger und markiere jede bereits gezählte Strecke. Vergleiche anschließend die horizontalen und vertikalen Teilstrecken. Erst wenn ihre Summen zum Rechteckmodell passen, ist dessen kurze Umfangsformel hier begründet. Für eine Bestellung werden zusätzliche Anschluss- oder Bearbeitungszugaben gesondert betrachtet.",
      ["lf02-070", "lf01-010"], "Warum darfst du nicht jeden versprungenen Dachrand automatisch mit dem umschließenden Rechteck berechnen?", "Zusätzliche Einschnitte können den Rand verlängern. Die Abkürzung passt nur, wenn die Teilstrecken im vorgegebenen Grundriss die Rechteckseiten entsprechend ersetzen.",
      ordnen("Den Rand ohne Doppelzählung erfassen", ["Eindeutigen Startpunkt am Dachrand markieren", "Alle Randstrecken bis zum Startpunkt einzeln beschriften", "Teilmaße in dieselbe Einheit bringen und addieren", "Ergebnis anhand des tatsächlichen Grundrisses kontrollieren"], "Die vollständige Streckensumme bleibt auch dann richtig, wenn eine kurze Rechteckformel nicht passt."), [], 2),
    einheit("lf02-l18", "Das richtige rechtwinklige Dachdreieck wählen", "Du kannst Grundmaß, Firsthöhe und Sparren zuordnen und die Sparrenlänge mit dem Kosinus berechnen.",
      "Im Dachquerschnitt liegt die Sparrenlänge auf der Schräge. Sie ist die Hypotenuse des rechtwinkligen Dreiecks. Die waagerechte Strecke heißt Grundmaß, die senkrechte Strecke Firsthöhe. Beim Pultdach ohne Überstand ist das Grundmaß die Gebäudebreite; beim symmetrischen Satteldach ist es die halbe Breite. Kennst du Neigung und Grundmaß, rechnest du s = g ÷ cos(DN). Der Taschenrechner muss zur Winkelangabe passen, hier also auf Grad stehen. Die Firsthöhe folgt aus h = g × tan(DN). Zeichne die drei Strecken vor dem Einsetzen der Zahlen ein. Die halbe Breite darf nicht mit der ganzen verwechselt werden. Eine schräge Sparrenlänge ist bei positiver Neigung größer als ihr waagerechtes Grundmaß; diese Probe deckt viele Eingabefehler auf.",
      ["lf02-076", "lf02-077", "lf02-103"], "Welche Strecke bildet am symmetrischen Satteldach das Grundmaß eines Dachdreiecks?", "Die halbe Gebäudebreite. Mit diesem Grundmaß und der Neigung wird die Länge eines Sparrens bestimmt.",
      fall("Falscher Eintrag am Querschnitt", "A bezeichnet einen Sparren, B die senkrechte Firsthöhe. C liegt nur zwischen linker Traufe und Firstlot, ist aber als ganze Breite bezeichnet.", [["C ist beim symmetrischen Satteldach nur die halbe Gebäudebreite.", true], ["A ist die Hypotenuse des linken Dachdreiecks.", true], ["B muss dieselbe Länge wie A haben.", false]], "Das Firstlot teilt das symmetrische Dach in zwei rechtwinklige Dreiecke.", falscheDachskizze)),
    einheit("lf02-l18", "Dachflächen und Gratsparren mit einer Probe prüfen", "Du kannst die Gesamtfläche eines gleich geneigten Satteldachs berechnen und Kontrollfläche sowie Gratsparren geometrisch einordnen.",
      "Für ein gleich geneigtes Satteldach berechnest du zunächst die Sparrenlänge einer Seite. Eine Dachfläche ist Trauflänge mal Sparrenlänge. Beide gleich großen Seiten ergeben zusammen die doppelte Fläche. Ohne Dachüberstände lässt sich das Ergebnis auch über die waagerechte Grundfläche prüfen: Dachfläche = Grundfläche ÷ cos(DN). Diese Kontrollrechnung muss zu denselben Randbedingungen gehören. Überstände oder unterschiedlich geneigte Teilflächen dürfen nicht unbemerkt fehlen. Beim gleich geneigten Walmdach ist der Gratsparren räumlich schräg. Im passenden Hilfsdreieck ergibt sich seine Länge aus der halben Gebäudebreite und der zuvor berechneten Sparrenlänge. Rechne mit ungerundeten Zwischenwerten weiter. Erst am Schluss rundest du passend zur Aufgabe und vergleichst beide Flächenwege auf Plausibilität.",
      ["lf02-078", "lf02-079", "lf02-080"], "Welche Bedingungen braucht die Kontrolle Dachfläche = Grundfläche ÷ cos(DN) in dieser Übung?", "Eine einheitliche Dachneigung und dieselbe zugehörige Grundfläche ohne unberücksichtigte Dachüberstände. Beide Rechenwege müssen dieselben Flächen beschreiben.",
      ordnen("Die Fläche zweimal prüfen", ["Grundmaße und einheitliche Neigung feststellen", "Sparrenlänge aus dem Dachdreieck berechnen", "Einzelflächen berechnen und addieren", "Dieselbe Grundfläche durch cos(DN) teilen und vergleichen"], "Zwei Wege sind nur dann eine sinnvolle Gegenprobe, wenn sie dieselbe Geometrie und dieselben Überstände berücksichtigen."), [], 2),
  ] },
];

const lf03: LernKapitel[] = [
  { id: "lf03-k01", titel: "Mauersteine, Mörtel und Wandaufgaben", einheiten: [
    einheit("lf03-l01", "Steinarten anhand ihrer Eigenschaften wählen", "Du kannst Ziegel, Kalksandstein und Porenbeton unterscheiden und eine Materialwahl auf die Aufgabe beziehen.",
      "Mauersteine unterscheiden sich nicht nur in Farbe und Gewicht. Ziegel werden aus tonigen Rohstoffen gebrannt. Lochungen können Gewicht und Wärmeleitung beeinflussen. Kalksandstein wird aus Kalk, Sand und Wasser hergestellt und unter Dampfdruck gehärtet. Er ist besonders für hohe Rohdichte und guten Schallschutz bekannt. Porenbeton enthält viele kleine Poren, ist leicht und lässt sich vergleichsweise einfach bearbeiten. Seine Eigenschaften unterscheiden sich deutlich von dichtem Kalksandstein. Für einen Schornsteinkopf, eine Attika oder eine andere kleine Mauerarbeit ist deshalb zuerst die geplante Beanspruchung zu klären. Tragfähigkeit, Feuchteeinwirkung und späterer Anschluss müssen passen. Die Bezeichnung einer Steinart ersetzt keine passende Produktklasse. Vergleiche die Planung mit der Kennzeichnung, bevor du Material und Befestigungen auswählst.",
      ["lf03-009", "lf03-015", "lf03-017", "lf03-093"], "Warum ist Porenbeton nicht einfach gegen Kalksandstein gleicher Abmessung austauschbar?", "Rohdichte, Festigkeit, Dämmwirkung und Befestigungsbedingungen unterscheiden sich. Das Produkt muss zur vorgesehenen Wand und ihren Anschlüssen passen.",
      zuordnen("Werkstoff und typisches Merkmal", [["Mauerziegel", "Tonprodukt mit keramischem Brand"], ["Kalksandstein", "Kalk und Sand, unter Dampfdruck gehärtet"], ["Porenbeton", "Leichter mineralischer Stein mit vielen Poren"], ["Produktklasse", "Ergänzt den Werkstoffnamen um erforderliche Eigenschaften"]], "Eine Entscheidung wird mit Eigenschaften begründet; der bloße Name beschreibt noch nicht jede Eignung."), ["lf03-017"]),
    einheit("lf03-l06", "Steinformat und Kennzeichnung lesen", "Du kannst Steinmaße, Format und Materialkurzzeichen unterscheiden und den sicheren Materialtransport berücksichtigen.",
      "Ein Steinformat beschreibt Länge, Breite und Höhe in einer festgelegten Reihenfolge. Dünnformat und Normalformat haben im Buchbeispiel dieselbe Länge und Breite, aber verschiedene Höhen. Ein größeres Format ist deshalb nicht in jeder Richtung einfach doppelt so groß. Prüfe immer die Maßtabelle. Zusätzlich helfen Kurzzeichen wie HLz für Hochlochziegel oder KS für Kalksandstein bei der Materialzuordnung. Weitere Angaben betreffen zum Beispiel Festigkeit und vorgesehene Verwendung. Sie müssen zu den Planungsunterlagen passen. Auch das Versetzen gehört zur Auswahl: Ein großer Stein kann ein geeignetes Hebezeug statt Handtransport erfordern. Ein vermeintlicher Zeitgewinn durch große Formate funktioniert nur mit passendem Arbeitsablauf. Stelle Materialkennung, Maßfolge und vorgesehenes Versetzverfahren vor der Bestellung zusammen.",
      ["lf03-006", "lf03-007", "lf03-012", "lf03-020"], "Warum darfst du aus 2 DF nicht auf eine Verdoppelung aller drei Steinabmessungen schließen?", "Die Formatbezeichnung beschreibt ein Format im Maßsystem. Die tatsächlichen Länge-, Breite- und Höhenwerte müssen aus der passenden Tabelle gelesen werden.",
      fall("Gleiche Palette, anderes Format", "Geliefert werden größere Steine als geplant. Die Kolonne möchte sie mit demselben Handgriff und derselben Schichthöhe einsetzen.", [["Maße und Schichthöhe erneut mit der Planung vergleichen.", true], ["Gewicht und geeignetes Versetzverfahren prüfen.", true], ["Größeres Format verändert nur die Anzahl auf der Palette.", false]], "Ein Formatwechsel betrifft Maße, Schichten, Bedarf und Arbeitsverfahren.")),
    einheit("lf03-l04", "Mörtelart und Fugen dem Steinsystem zuordnen", "Du kannst Lager- und Stoßfuge unterscheiden und Normal-, Leicht- sowie Dünnbettmörtel nach ihrer Verwendung einordnen.",
      "Mörtel verbindet Mauersteine und gleicht kleine Unebenheiten aus. Die waagerechte Fuge zwischen Schichten heißt Lagerfuge. Die senkrechte Fuge zwischen benachbarten Steinen heißt Stoßfuge. Normalmörtel wird mit einer anderen Fugenausbildung verarbeitet als Dünnbettmörtel. Dünnbettmörtel benötigt besonders maßgenaue Plansteine; er ist keine beliebige Sparvariante für unebene Steine. Leichtmörtel enthält leichte Zuschläge und kann zu einem wärmedämmenden Steinsystem gehören. Auch die Stoßflächen sind wichtig. Bei glatten Flächen kann Stoßfugenmörtel vorgesehen sein; Nut-Feder-Systeme haben eigene Regeln. Lies deshalb die zum Produkt gehörende Ausführung, statt die Fuge nach Gefühl dünner zu machen. Eine passende Mischung allein hilft nicht, wenn falsche Fugen oder ungeeignete Steine verwendet werden.",
      ["lf03-028", "lf03-029", "lf03-043", "lf03-074"], "Warum eignet sich Dünnbettmörtel nicht automatisch für beliebige Mauersteine?", "Die dünne Fuge kann größere Maßabweichungen nicht ausgleichen. Das System benötigt dafür geeignete, besonders maßgenaue Plansteine.",
      zuordnen("Welche Fuge, welcher Mörtel?", [["Lagerfuge", "Waagerechte Fuge zwischen Steinschichten"], ["Stoßfuge", "Senkrechte Fuge zwischen benachbarten Steinen"], ["Dünnbettmörtel", "Gehört zu einem passenden Plansteinsystem"], ["Leichtmörtel", "Enthält leichte Zuschläge"]], "Die richtige Kombination aus Stein und Mörtel bestimmt die Ausführung."), ["lf03-029"]),
    einheit("lf03-l04", "Bindemittel, Sand und Wasser wirken zusammen", "Du kannst die Aufgaben der Mörtelbestandteile und den Unterschied zwischen Luftkalk und hydraulischen Bindemitteln erklären.",
      "Sand bildet im Mörtel das Korngerüst. Das Bindemittel umhüllt und verbindet die Körner; Wasser macht die frische Mischung verarbeitbar und ist je nach Bindemittel auch an der Erhärtung beteiligt. Luftkalk erhärtet durch die Aufnahme von Kohlendioxid aus der Luft. Hydraulische Bindemittel können dagegen durch Reaktion mit Wasser erhärten. Deshalb verhalten sich Kalk-, Kalkzement- und Zementmörtel unterschiedlich. Mehr Zement ist nicht automatisch die beste Lösung für jede Wand: Festigkeit, Verformung und Verträglichkeit mit dem Stein müssen zusammenpassen. Eine Mörtelklasse beschreibt die Druckfestigkeit. Bei fertig geliefertem Trockenmörtel werden Bindemittel und Körnung bereits abgestimmt; auf der Baustelle wird nach Produktangabe Wasser zugesetzt. Zusätzliche beliebige Bindemittel verändern dieses vorgesehene System.",
      ["lf03-021", "lf03-026", "lf03-028", "lf03-030"], "Welche unterschiedlichen Aufgaben haben Sand und Bindemittel im Mörtel?", "Der Sand bildet das Korngerüst. Das Bindemittel umhüllt die Körner und verbindet sie beim Erhärten.",
      zuordnen("Mörtelbestandteile verstehen", [["Gesteinskörnung", "Bildet das feste Korngerüst"], ["Bindemittel", "Verbindet die Körner beim Erhärten"], ["Luftkalk", "Erhärtet durch Reaktion mit Kohlendioxid der Luft"], ["Mörtelklasse", "Beschreibt die Druckfestigkeit"]], "Die Zusammensetzung wird für eine Aufgabe gewählt. Ein hoher Festigkeitswert allein beschreibt nicht die gesamte Eignung."), ["lf03-021"], 2),
    einheit("lf03-l05", "Vor dem Eingriff die Wandaufgabe klären", "Du kannst tragende, aussteifende, raumtrennende und brandschützende Wandfunktionen unterscheiden.",
      "Eine Wand kann mehrere Aufgaben gleichzeitig erfüllen. Tragende Wände leiten Lasten aus anderen Bauteilen weiter. Aussteifende Wände stabilisieren das Gebäude gegen seitliche Verformungen. Eine nichttragende Trennwand grenzt Räume ab, kann aber trotzdem Anforderungen an Schall- oder Brandschutz erfüllen. Eine Brandwand soll die Ausbreitung eines Brandes begrenzen und muss dafür die vorgesehenen Eigenschaften einschließlich ihrer Anschlüsse besitzen. Aus dem sichtbaren Stein oder einer gemessenen Dicke allein kannst du diese Funktionen nicht zuverlässig ableiten. Die im Lehrbuch genannten Dicken gehören zur dort beschriebenen Bauweise und ersetzen keinen Nachweis für den Bestand. Prüfe Planung, Konstruktion und Anschlussdetails, bevor du schlitzt, entfernst oder eine Öffnung herstellst. Eine ungeklärte Wandfunktion ist zuerst eine Planungsfrage.",
      ["lf03-001", "lf03-002", "lf03-004", "lf03-005"], "Warum reicht die gemessene Wanddicke nicht aus, um einen Durchbruch freizugeben?", "Sie zeigt nicht zuverlässig, ob die Wand trägt, aussteift oder eine Brandschutzfunktion hat. Funktion und zulässiger Eingriff müssen anhand der Planung geklärt werden.",
      fall("Eine vermeintliche Trennwand", "Eine dünn wirkende Wand soll für eine Leitung geöffnet werden. Ihre Aufgabe ist aus den verfügbaren Unterlagen nicht bekannt.", [["Wandfunktion und zulässigen Eingriff vor der Bearbeitung klären.", true], ["Mögliche Schall- und Brandschutzanforderungen berücksichtigen.", true], ["Jede dünne Wand darf ohne Prüfung entfernt werden.", false]], "Auch eine nichttragende Wand kann wichtige Schutzfunktionen haben."), ["lf03-005"]),
  ] },
  { id: "lf03-k02", titel: "Maßordnung und Materialbedarf", einheiten: [
    einheit("lf03-l02", "Stein und Fuge gemeinsam planen", "Du kannst das Achtelmeter-Raster erklären und Richtmaß vom tatsächlichen Bauteilmaß unterscheiden.",
      "Mauerwerk wird mit einem gemeinsamen Maßraster geplant, damit Steine, Fugen und Öffnungen aufeinander abgestimmt werden können. Im oktametrischen System ist ein Achtelmeter gleich 12,5 cm. Ein typisches Kopfmaß entsteht beispielsweise aus 11,5 cm Steinbreite und einer zugehörigen Fuge von 1 cm. Das Richtmaß enthält die Rastervorstellung; das Nennmaß beschreibt das vorgesehene Bauteilmaß. Deshalb ist ein Rastermaß von 25 cm nicht automatisch eine tatsächliche Steinlänge von 25 cm. Je nach Maßart und Fugenlage ergibt sich ein anderer Wert. Zeichne bei einer Aufgabe zuerst Stein und Fugen ein. So erkennst du, welche Fugen mitgezählt werden und welche am freien Ende fehlen. Diese kleine Skizze verhindert ein ständiges und unbegründetes Zuschneiden auf der Baustelle.",
      ["lf03-008", "lf03-036", "lf03-042"], "Warum sind 25 cm Rastermaß und 24 cm Steinlänge kein Widerspruch?", "Das Raster berücksichtigt die zugehörige Fuge. Die Steinlänge ist das Bauteilmaß ohne diese zusätzliche Rasterfuge.",
      zuordnen("Maße nicht vermischen", [["Ein Achtelmeter", "12,5 cm"], ["Baurichtmaß", "Planungsmaß im Raster mit Fugenbezug"], ["Nennmaß", "Vorgesehenes Maß des Bauteils"], ["Maßskizze", "Zeigt, welche Fugen in einer Strecke liegen"]], "Die Fugenlage erklärt den Unterschied zwischen Richt- und Bauteilmaß."), ["lf03-036"]),
    einheit("lf03-l07", "Außenmaß, Öffnung und Schichthöhe rechnen", "Du kannst Außen-, Innen- und Anbaumaße im vorgegebenen Raster unterscheiden und Mauerhöhen aus Schichten bestimmen.",
      "Im Achtelmeter-Raster beginnt jede Rechnung mit der Anzahl der Köpfe mal 12,5 cm. Danach entscheidet die Maßart. Im vorgegebenen Modell wird beim frei endenden Außenmaß 1 cm abgezogen, beim Öffnungsmaß 1 cm addiert und beim Anbaumaß nichts verändert. Mit acht Köpfen entstehen deshalb 99 cm außen, 101 cm für die Öffnung und 100 cm als Anbaumaß. Diese Regeln beschreiben die jeweilige Fugenlage; sie sind keine beliebigen Korrekturen. Für die Höhe zählt eine ganze Schicht aus Stein und Lagerfuge. Im Beispiel hat eine 2-DF-Schicht 12,5 cm. Eine Höhe von 250 cm entspricht dann 20 Schichten. Prüfe vor dem Rechnen Format, Fugenmodell und Bezug der angegebenen Maße.",
      ["lf03-037", "lf03-038", "lf03-041", "lf03-096"], "Welche drei Maße ergeben sich im Übungsmodell aus acht Köpfen?", "8 × 12,5 = 100 cm. Außenmaß 99 cm, Öffnungsmaß 101 cm, Anbaumaß 100 cm.",
      zuordnen("Die richtige Korrektur wählen", [["Frei endendes Außenmaß", "Kopfanzahl × 12,5 cm minus 1 cm"], ["Öffnungsmaß", "Kopfanzahl × 12,5 cm plus 1 cm"], ["Anbaumaß", "Kopfanzahl × 12,5 cm"], ["Mauerhöhe", "Schichtanzahl × zugehörige Schichthöhe"]], "Erst die Maßart festlegen, dann die Rasterrechnung ausführen.")),
    einheit("lf03-l08", "Steine und Mörtel aus der Nettofläche ermitteln", "Du kannst Wandöffnungen abziehen und einen zum Steinformat und zur Wanddicke passenden Tabellenbedarf anwenden.",
      "Für eine Materialbestellung brauchst du zuerst die tatsächlich zu mauernde Wandfläche. Länge mal Höhe ergibt die Bruttofläche. Davon ziehst du in dieser Bedarfsrechnung die vorgesehenen Öffnungsflächen ab. Erst die Nettofläche wird mit dem Bedarf je Quadratmeter multipliziert. Die Tabellenzeile muss zu Steinformat, Wanddicke und Fugenart passen. Beispiel aus der vorhandenen Übung: Eine 24-cm-Wand aus HLz 5 DF ist 6 m lang und 2,5 m hoch. Ohne Öffnungen sind das 15 m². Bei 26 Steinen und 40 Litern Mörtel je Quadratmeter folgen 390 Steine und 600 Liter Mörtel. Diese Werte gehören genau zu diesem Rechenmodell. Für ein anderes Format wird die passende Zeile neu gewählt; ein pauschaler Wert für alle Wände wäre irreführend.",
      ["lf03-075", "lf03-076", "lf03-077", "lf03-078"], "Warum ziehst du Öffnungen ab, bevor du mit dem Tabellenbedarf multiplizierst?", "Durch Öffnungen entfällt zu mauernde Fläche. Der Materialbedarf wird mit der zugehörigen Nettofläche statt mit der gesamten Rechteckfläche berechnet.",
      ordnen("Eine Wandbestellung vorbereiten", ["Bruttowandfläche aus Länge und Höhe berechnen", "Öffnungsflächen ermitteln und abziehen", "Bedarfswerte für Format, Wanddicke und Fugenart auswählen", "Nettofläche mit Stein- und Mörtelbedarf multiplizieren"], "Öffnungsabzug und passende Tabellenzeile sind zwei getrennte Voraussetzungen für eine richtige Bedarfsrechnung.")),
    einheit("lf03-l12", "Mörtelvolumen in Ausgangsstoffe zurückrechnen", "Du kannst mit dem vorgegebenen Mörtelfaktor und den Raumteilen den Bedarf an Sand und Bindemittel berechnen.",
      "Die Volumina trockener Ausgangsstoffe ergeben beim Mischen nicht einfach dieselbe Menge fertigen Mörtel. Feine Bindemittelteilchen füllen Hohlräume zwischen den Sandkörnern. Dafür verwendet die Übung einen vorgegebenen Mörtelfaktor. Bei 400 Litern gewünschtem Mörtel und Faktor 1,6 rechnest du zunächst 640 Liter Ausgangsstoffe. Das Mischungsverhältnis 1:4 besteht aus insgesamt fünf Raumteilen. Ein Raumteil ist daher 640 geteilt durch fünf gleich 128 Liter. Davon gehören 128 Liter zum Bindemittel und 512 Liter zum Sand. Die Raumteile sind Volumenanteile, keine Kilogrammangaben. Sackmassen müssen gegebenenfalls mit dem ausdrücklich vorgegebenen Schüttvolumen umgerechnet werden. Kontrolliere zum Schluss, ob beide Stoffmengen zusammen wieder die berechneten 640 Liter Ausgangsstoffe ergeben.",
      ["lf03-031", "lf03-032", "lf03-033", "lf03-034"], "Wie viel Sand ergibt die Beispielmischung für 400 l Mörtel, Faktor 1,6 und Verhältnis 1:4?", "400 × 1,6 = 640 l Ausgangsstoffe. 640 ÷ 5 = 128 l je Raumteil; vier Sandanteile ergeben 512 l.",
      ordnen("Raumteile sauber berechnen", ["Mörtelbedarf mit dem vorgegebenen Mörtelfaktor multiplizieren", "Alle Raumteile des Mischungsverhältnisses addieren", "Ausgangsvolumen durch die Summe der Raumteile teilen", "Volumen je Raumteil mit den Anteilen jedes Stoffes multiplizieren"], "Der Mörtelfaktor wird zuerst auf den fertigen Bedarf angewendet, erst danach wird nach Raumteilen aufgeteilt.")),
  ] },
  { id: "lf03-k03", titel: "Verband, Arbeitsablauf und Projekt", einheiten: [
    einheit("lf03-l03", "Fugen versetzen und Lasten weiterleiten", "Du kannst Läufer und Binder unterscheiden und einen fehlerhaften Verband mit durchgehenden Stoßfugen erkennen.",
      "Mauerwerk besteht nicht aus voneinander unabhängigen Steinstapeln. Durch den Verband greifen aufeinanderfolgende Schichten ineinander und verteilen Lasten. Eine lange sichtbare Steinseite kennzeichnet den Läufer, eine kurze Kopfseite den Binder. Beim Läuferverband sind die Schichten gegeneinander versetzt. Block- und Kreuzverbände kombinieren Läufer- und Binderschichten auf unterschiedliche Weise. Wichtig ist, dass die vorgeschriebene Überbindung an Fläche, Ecke und Anschluss eingehalten wird. Senkrecht durchlaufende Stoßfugen verringern die Verzahnung und sind ein Warnzeichen. Prüfe den geplanten Verband daher bereits in einer kleinen Skizze über mehrere Schichten. Teilsteine werden gezielt für passende Anschlüsse eingesetzt. Ein scheinbar einfacher Start mit nur ganzen Steinen darf am Ende keine Kreuzfugen erzwingen.",
      ["lf03-066", "lf03-067", "lf03-068", "lf03-072"], "Warum sind übereinanderliegende Stoßfugen im Mauerwerk problematisch?", "Sie unterbrechen die Verzahnung der Schichten und verschlechtern die Lastverteilung. Der Verband braucht ausreichende Überbindung.",
      fall("Fehler in drei Schichten", "Die Skizze zeigt drei Schichten. Jede senkrechte Stoßfuge läuft ohne Versatz von oben bis unten durch.", [["Die fehlende Überbindung ist ein Verbandsfehler.", true], ["Die Schichten müssen passend zum geplanten Verband versetzt werden.", true], ["Gerade senkrechte Fugen ersetzen die Verzahnung durch Mörtel allein.", false]], "Waagerechte Schichten allein reichen nicht: Der Fugenversatz verbindet die Schichten miteinander.", kreuzfuge), ["lf03-067", "lf03-068"]),
    einheit("lf03-l11", "Von den Mauerecken zur fluchtgerechten Schicht", "Du kannst den Mauerablauf sinnvoll ordnen und Werkzeug, Schnur sowie Teilsteine ihren Aufgaben zuordnen.",
      "Eine gerade Wand beginnt mit richtig angelegten Enden und Ecken. Prüfe deren Lage und Höhe, bevor du die Fläche dazwischen schließt. Eine gespannte Maurerschnur zeigt den Verlauf der nächsten Schicht. Wasserwaage, Richtscheit und Senklot helfen bei waagerechter, fluchtgerechter und senkrechter Ausrichtung. Die Kelle bringt den vorgesehenen Mörtel auf. Beim Versetzen eines Einhandsteins bereitest du die erforderlichen Fugen vor, setzt den Stein in sein Mörtelbett und schiebst ihn passend an. Hervorquellenden Mörtel streichst du ab. Teilsteine ergänzen den Verband, wenn ganze Steine allein nicht passen. Kontrolliere die Lage fortlaufend, statt eine schiefe Wand erst am Ende zu bemerken. Ein sicherer Arbeitsplatz und geeignete Werkzeuge gehören zu diesem Ablauf ebenso wie saubere Fugen.",
      ["lf03-044", "lf03-045", "lf03-047", "lf03-049"], "Warum wird die Schnur zwischen bereits kontrollierten Enden oder Ecken gespannt?", "Sie übernimmt deren Lage als Richtlinie für die Zwischenschicht. Falsch angelegte Endpunkte würden die gesamte Schicht falsch führen.",
      ordnen("Eine Schicht mauern", ["Mauerenden und Ecken lot- und höhengerecht anlegen", "Schnur für die Schicht spannen", "Vorgesehene Lager- und Stoßfugen vorbereiten", "Steine versetzen, ausrichten und Mörtel abstreichen", "Verband, Höhe und Flucht fortlaufend kontrollieren"], "Die Schnur führt die Lage, ersetzt aber weder die Kontrolle der Endpunkte noch die Prüfung des Verbands."), ["lf03-045"]),
    einheit("lf03-l09", "Eine Aufmaßskizze verständlich aufbauen", "Du kannst isometrische und dimetrische Darstellung unterscheiden und Maße sowie sichtbare und verdeckte Kanten eindeutig festhalten.",
      "Eine Aufmaßskizze hält die Form und die gemessenen Größen eines Bauteils fest. Sie muss nicht schön wirken, sondern eindeutig verständlich sein. Eine räumliche Darstellung zeigt Zusammenhänge oft besser als eine einzelne Ansicht. Bei der Isometrie werden die drei Achsen im gleichen Maßstab dargestellt; die Höhe steht senkrecht, die beiden anderen Achsen verlaufen schräg. Bei einer Dimetrie wird eine Achse gegenüber den anderen verkürzt. Diese Darstellung ist keine Einladung, fehlende Maße aus dem Bild zu schätzen. Trage Messpunkte, Bezugskanten und Maße ausdrücklich ein. Sichtbare Kanten werden durchgezogen, verdeckte gestrichelt gezeichnet. Ergänze einen Schnitt oder eine zweite Ansicht, wenn ein Anschluss räumlich unklar bleibt. So kann eine andere Person aus deiner Aufnahme nachvollziehbar weiterarbeiten.",
      ["lf03-080", "lf03-081", "lf03-082"], "Was macht eine Aufmaßskizze für andere nutzbar, auch wenn sie nicht maßstäblich gezeichnet ist?", "Eindeutige Maße, Bezugspunkte und erkennbare Bauteilkanten. Unklare räumliche Stellen werden durch zusätzliche Ansichten oder Schnitte ergänzt.",
      zuordnen("Darstellung richtig lesen", [["Isometrie", "Drei Achsen im gleichen Maßverhältnis"], ["Dimetrie", "Eine Achse ist gegenüber den anderen verkürzt"], ["Gestrichelte Kante", "Liegt aus dieser Sicht verdeckt"], ["Aufmaßskizze", "Dokumentiert Form, Bezugspunkte und gemessene Maße"]], "Eine räumliche Zeichnung erklärt die Form; die eingetragenen Maße liefern die überprüfbaren Längen."), ["lf03-081"]),
    einheit("lf03-l13", "Gartenhaus als zusammenhängende Aufgabe planen", "Du kannst Projektvorgaben, Steinwahl, Verband und geneigte Dachfläche zu einer begründeten Planung verbinden.",
      "Das Gartenhausprojekt verbindet mehrere bisher getrennte Rechnungen. Im Buchbeispiel sind drei Räume und höchstens 24 m² Grundfläche vorgesehen. Diese Grenze ist eine Projektvorgabe, keine allgemeine Aussage über jedes Gartenhaus. Prüfe zunächst, ob Raumflächen und Wände in den Grundriss passen. Die Steinwahl wird nach Anforderungen wie Tragfähigkeit, Wärmeschutz und Bearbeitbarkeit begründet. Für die Wand brauchst du einen funktionierenden Verband und passende Anschlussdetails. Das vorgegebene Pultdach hat 15 Grad Neigung. Ohne Überstand erhältst du die Sparrenlänge aus der waagerechten Breite geteilt durch cos(15°). Diese Länge mal Gebäudelänge ergibt die Dachfläche. Sie ist bei geneigtem Dach größer als die überdeckte Grundfläche. Halte Vorgaben und errechnete Ergebnisse getrennt fest, damit deine Lösung überprüfbar bleibt.",
      ["lf03-083", "lf03-084", "lf03-085", "lf03-086"], "Wie berechnest du die Pultdachfläche aus waagerechter Breite und Länge im 15-Grad-Beispiel?", "Sparrenlänge = Breite ÷ cos(15°). Dachfläche = Sparrenlänge × Gebäudelänge, bei den angegebenen Bedingungen ohne zusätzlichen Überstand.",
      fall("Die Dachfläche ist kleiner?", "Für ein Pultdach ohne Überstand ergibt eine Rechnung weniger Fläche als die waagerechte Gebäudegrundfläche.", [["Die Rechnung und den Gradmodus des Taschenrechners prüfen.", true], ["Die geneigte Fläche muss unter diesen Bedingungen größer sein.", true], ["Eine Neigung verkleinert die tatsächliche Deckfläche gegenüber ihrer Projektion.", false]], "Bei positiver Neigung ist cos(DN) kleiner als eins. Das Teilen durch diesen Wert vergrößert die Fläche.")),
  ] },
  { id: "lf03-k04", titel: "Gerüste passend nutzen", einheiten: [
    einheit("lf03-l10", "Gerüstaufgabe und Tragsystem unterscheiden", "Du kannst Arbeits- und Schutzgerüste sowie Stand-, Hänge-, Ausleger- und Konsolgerüste nach unterschiedlichen Merkmalen zuordnen.",
      "Ein Gerüst wird nach seiner Aufgabe und nach seinem Tragsystem beschrieben. Ein Arbeitsgerüst bietet einen Arbeitsplatz für Bauarbeiten. Ein Schutzgerüst soll vor tieferem Absturz oder herabfallenden Gegenständen schützen. Ein Fanggerüst und ein Schutzdach haben dabei verschiedene Schutzaufgaben. Das Tragsystem beschreibt dagegen, wie die Konstruktion gehalten wird. Ein Standgerüst steht auf dem Untergrund, ein Hängegerüst ist an geeigneten Bauteilen abgehängt. Ausleger- und Konsolgerüste leiten ihre Lasten über die dafür geplanten tragenden Teile in das Gebäude. Ein Rahmengerüst besteht aus zusammengehörigen Systembauteilen. Keine dieser Bezeichnungen erlaubt allein jede beliebige Nutzung. Vor Arbeitsbeginn müssen Verwendungszweck, Lasten, sicherer Zugang und vorgesehene Schutzfunktion zu deiner tatsächlichen Arbeit passen.",
      ["lf03-050", "lf03-051", "lf03-052", "lf03-060"], "Warum sind Arbeitsgerüst und Standgerüst keine Gegensätze?", "Arbeitsgerüst beschreibt den Verwendungszweck, Standgerüst das Tragsystem. Ein Gerüst kann beides zugleich sein.",
      zuordnen("Zwei verschiedene Einteilungen", [["Arbeitsgerüst", "Beschreibt einen Arbeitsplatz für Bauarbeiten"], ["Fanggerüst", "Soll Personen vor tieferem Absturz schützen"], ["Standgerüst", "Leitet Lasten über Ständer in den Untergrund"], ["Hängegerüst", "Ist an geeigneten tragenden Bauteilen abgehängt"]], "Verwendungszweck und Tragsystem werden getrennt gelesen und anschließend gemeinsam auf Eignung geprüft."), ["lf03-051", "lf03-060"]),
    einheit("lf03-l10", "Lastklasse und Materiallagerung beachten", "Du kannst die Lastklasse als Nutzungsgrenze erklären und eine ungeklärte Materiallagerung auf dem Gerüst erkennen.",
      "Die Lastklasse eines Arbeitsgerüsts beschreibt seine vorgesehene Nutzlast. Dazu zählen Personen, Werkzeuge und Material. Für leichte Kontrolltätigkeiten gelten andere Bedingungen als für Mauerarbeiten mit Steinvorräten. Ein frei wirkender Belag ist deshalb noch kein erlaubtes Materiallager. Besonders konzentrierte Palettenlasten dürfen nicht einfach als gleichmäßig verteilte Last behandelt werden. Die Lastklasse 3 wird in den vorhandenen Aufgaben mit 2,00 kN/m² gleichmäßig verteilter Nutzlast behandelt. Das ist keine Freigabe für jede beliebige Einzellast. Prüfe die Gerüstkennzeichnung und die Nutzungsangaben, bevor du Steine oder Mörtelbehälter aufsetzt. Eine Änderung des Tragsystems oder der Abstände ist Sache der dafür zuständigen Fachleute. Mehr Material darf nicht durch eigenmächtig ergänzte Gerüstteile ermöglicht werden.",
      ["lf03-053", "lf03-054", "lf03-055", "lf03-063"], "Warum reicht eine bekannte Flächenlast nicht aus, um eine schwere Palette irgendwo abzustellen?", "Eine Palette kann eine hohe konzentrierte Last erzeugen. Lastklasse, Belagsbelastung und die konkreten Nutzungsangaben müssen für diese Lagerung passen.",
      fall("Steinpalette auf freiem Belag", "Eine volle Steinpalette soll auf einem Gerüstfeld abgestellt werden. Lastklasse und zulässige Lagerung sind der Kolonne nicht bekannt.", [["Kennzeichnung und Nutzungsfreigabe vor dem Absetzen prüfen.", true], ["Personen, Werkzeug und weiteres Material als zusätzliche Lasten berücksichtigen.", true], ["Freier Platz auf dem Belag beweist ausreichende Tragfähigkeit.", false]], "Platz und Tragfähigkeit sind verschiedene Dinge. Ungeklärte Lasten werden nicht durch Ausprobieren freigegeben."), [], 2),
    einheit("lf03-l10", "Seitenschutz, Aussteifung und Verankerung prüfen", "Du kannst die Aufgaben von Seitenschutz, Diagonalen und Verankerungen unterscheiden und unzulässige Veränderungen erkennen.",
      "Ein Gerüst muss sich selbst stabil halten und zugleich seine Nutzer schützen. Diagonalen und Rahmen steifen die Konstruktion aus. Verankerungen übertragen die vorgesehenen Kräfte in geeignete tragfähige Gebäudeteile. Eine Dachrinne oder ein Blitzableiter ist dafür kein Ersatz. Der Seitenschutz besteht aus Geländerholm, Zwischenholm und Bordbrett und sichert den Rand des Arbeitsplatzes. Diese Bauteile erfüllen unterschiedliche Aufgaben; das Entfernen eines störenden Teils kann deshalb eine ernste Gefahr erzeugen. Prüfe vor der Benutzung erkennbare Schäden, fehlende Beläge und Schutzteile sowie den vorgesehenen Zugang. Bei einem Fahrgerüst kommen die sichere Aufstellung und die dafür geltenden Verwendungsangaben hinzu. Melde Mängel und lasse die Nutzung klären. Eigenmächtiges Umbauen während der Dacharbeit ist keine zulässige Mängelbeseitigung.",
      ["lf03-048", "lf03-058", "lf03-061", "lf03-062"], "Welche verschiedenen Aufgaben haben Seitenschutz und Gerüstverankerung?", "Der Seitenschutz schützt Personen und Material am Belagrand. Die Verankerung stabilisiert das Gerüst durch Kraftübertragung in geeignete Gebäudeteile.",
      fall("Die Verankerung stört den Anschluss", "Für eine Fassadenarbeit soll eine Gerüstverankerung entfernt und stattdessen an einer Dachrinne befestigt werden.", [["Die Änderung vor der Arbeit mit der zuständigen Gerüstfachkraft klären.", true], ["Die Dachrinne ist kein geeigneter Ersatz für ein tragfähiges Verankerungsbauteil.", true], ["Eine beliebige andere Befestigungsstelle erfüllt denselben Nachweis.", false]], "Verankerungen sind Teil der geplanten Standsicherheit und werden nicht eigenmächtig umgesetzt."), [], 3),
  ] },
];

const falschePlattenbewehrung = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 180"><title>Fehlerskizze: Platte auf zwei Auflagern mit Stahl oben</title><g fill="none" stroke="currentColor" stroke-width="4"><path d="M50 70h420v45H50zM65 115v40m390-40v40M260 20v35m-10-10 10 10 10-10"/><path d="M65 80h390" stroke="#c45f32"/></g><g fill="currentColor" font-family="sans-serif" font-size="16"><text x="60" y="174">zwei Auflager</text><text x="315" y="52">Stahl oben</text></g></svg>';
const lf04: LernKapitel[] = [
  { id: "lf04-k01", titel: "Beton verstehen und beurteilen", einheiten: [
    einheit("lf04-l01", "Drei Bestandteile mit verschiedenen Aufgaben", "Du kannst erklären, warum Zement, Wasser und Gesteinskörnung gemeinsam Beton ergeben.",
      "Betrachte Beton zuerst als Mischung mit verteilten Aufgaben. Sand und Kies bilden das körnige Gerüst. Zement verbindet dieses Gerüst, sobald er mit Wasser reagiert. Aus dem zunächst weichen Zementleim entsteht fester Zementstein. Diese chemische Reaktion heißt Hydratation. Beton gewinnt seine Festigkeit deshalb nicht einfach durch Austrocknen. Frischer Beton braucht Wasser für die Reaktion und wird vor zu schnellem Feuchteverlust geschützt. Zusatzstoffe und Zusatzmittel können bestimmte Eigenschaften verändern, ersetzen aber die drei Grundbestandteile nicht. Entscheidend ist auch die Wassermenge im Verhältnis zum Zement. Einfach zusätzliches Wasser einzurühren verbessert zwar scheinbar die Verarbeitung, kann aber einen porösen und weniger dauerhaften Beton ergeben.",
      ["lf04-001", "lf04-010", "lf04-023"], "Warum ist schnelles Austrocknen bei frischem Beton unerwünscht?", "Zement benötigt Wasser für die Hydratation. Zu früher Wasserverlust behindert die Festigkeitsentwicklung und kann Risse begünstigen.",
      zuordnen("Bestandteil und Aufgabe", [["Zement", "Bindet durch Reaktion mit Wasser"], ["Gesteinskörnung", "Bildet das körnige Gerüst"], ["Wasser", "Ermöglicht Hydratation und Verarbeitung"]], "Die Bestandteile wirken zusammen; Trocknen allein erklärt das Erhärten nicht.")),
    einheit("lf04-l05", "Vom Klinker zur Zementbezeichnung", "Du kannst Herstellung, Zementart und Festigkeitsangaben auseinanderhalten.",
      "Zement entsteht in mehreren Arbeitsschritten. Kalkstein und Ton werden aufbereitet und im Ofen zu Klinker gebrannt. Erst beim anschließenden Feinmahlen mit Gips entsteht der verwendbare Zement. Der Gips regelt das Erstarren, damit die Mischung verarbeitbar bleibt. Die Bezeichnungen CEM I bis CEM V unterscheiden die Hauptbestandteile: Portlandzement, Portlandkompositzement, Hochofenzement, Puzzolanzement und Kompositzement. Hochofenzement enthält beispielsweise Hüttensand. Davon getrennt steht die Festigkeitsklasse mit den Zahlen 32,5, 42,5 oder 52,5. Sie beschreibt die Mindestdruckfestigkeit nach 28 Tagen. L, N und R kennzeichnen dagegen die Anfangsfestigkeit. Lies eine Sackaufschrift daher in Teilen: Zementart, Festigkeitsklasse und Entwicklung in den ersten Tagen beantworten unterschiedliche Fragen.",
      ["lf04-003", "lf04-006", "lf04-007", "lf04-008"], "Was unterscheidet die Zahl 42,5 vom Buchstaben R auf einer Zementbezeichnung?", "42,5 bezeichnet die Mindestdruckfestigkeit nach 28 Tagen; R kennzeichnet eine hohe Anfangsfestigkeit.",
      ordnen("Zement herstellen", ["Kalkstein und Ton aufbereiten und mischen", "Rohstoffe im Ofen zu Klinker brennen", "Klinker mit Gips fein mahlen", "Fertigen Zement anhand seiner Kennzeichnung auswählen"], "Klinker ist ein Zwischenprodukt. Der Gips wird beim abschließenden Mahlen zugesetzt.")),
    einheit("lf04-l13", "Korngrößen sinnvoll mischen", "Du kannst Sand, Kies und Splitt unterscheiden und den Nutzen einer abgestuften Sieblinie erklären.",
      "Gesteinskörnung ist mehr als ein beliebiger Haufen Steine. Bis zur in den Unterlagen verwendeten Grenze von 4 mm spricht man von Sand. Gröbere gerundete Körner heißen Kies, gebrochene Körner Splitt. Werden verschiedene Größen passend gemischt, füllen kleine Körner die Zwischenräume zwischen großen. Diese Verteilung zeigt die Sieblinie. Eine dichte Packung benötigt weniger Zementleim zum Füllen der Hohlräume. Eine zweite Einteilung betrachtet die Kornrohdichte. Normale Körnungen sind etwa Sand, Kies und Splitt. Leichte Körnungen wie Bims oder Blähton ermöglichen Leichtbeton mit geringerer Wärmeleitfähigkeit. Schwere Körnungen wie Baryt oder Magnetit werden für Schwerbeton verwendet, etwa bei Abschirmungen oder Gegengewichten.",
      ["lf04-012", "lf04-014", "lf04-015", "lf04-093"], "Warum ist eine Mischung aus großen und kleinen Körnern oft günstiger als nur gleich große Körner?", "Kleine Körner füllen Hohlräume zwischen großen. Die Packung wird dichter und benötigt weniger Zementleim.",
      zuordnen("Körnung richtig einordnen", [["Kies", "Gröbere, gerundete Körner"], ["Splitt", "Gröbere, gebrochene Körner"], ["Blähton", "Leichte Gesteinskörnung"], ["Baryt", "Schwere Gesteinskörnung"]], "Größe und Form sind andere Merkmale als die Kornrohdichte.")),
    einheit("lf04-l14", "Wassergehalt, Festigkeit und Konsistenz", "Du kannst den w/z-Wert berechnen und Festigkeitsklasse von Konsistenz unterscheiden.",
      "Frischbeton lässt sich noch einbringen und verdichten; Festbeton ist bereits erhärtet. Für beide Zustände brauchst du verschiedene Beurteilungen. Der Wasserzementwert vergleicht Wassermasse und Zementmasse. Im Beispiel ergeben 160 kg Wasser geteilt durch 320 kg Zement den Wert 0,50. Zusätzliches Wasser kann später Poren hinterlassen und die Dauerhaftigkeit verringern. Eine Festigkeitsbezeichnung wie C25/30 beschreibt dagegen die Druckfestigkeit an Zylinder und Würfel nach 28 Tagen. Wie weich der frische Beton ist, heißt Konsistenz. Sie wird beispielsweise mit dem Ausbreitversuch geprüft und durch F-Klassen beschrieben. Das Verdichtungsmaß verwendet andere Klassen. Verwechsle deshalb eine leichte Verarbeitung nicht mit einer hohen späteren Festigkeit.",
      ["lf04-019", "lf04-021", "lf04-024", "lf04-094"], "Welche drei verschiedenen Fragen beantworten w/z-Wert, Druckfestigkeitsklasse und Konsistenz?", "Der w/z-Wert beschreibt das Massenverhältnis Wasser zu Zement, die Klasse die Druckfestigkeit und die Konsistenz die Verformbarkeit des Frischbetons.",
      fall("Leichter einbauen durch Nachgießen?", "Der gelieferte Beton erscheint steif. Jemand will ohne Abstimmung Wasser nachgießen und nennt das eine Festigkeitsverbesserung.", [["Mehr Wasser kann die spätere Porigkeit erhöhen.", true], ["Konsistenz und Festigkeit sind verschiedene Eigenschaften.", true], ["Ein weicherer Beton ist automatisch fester.", false]], "Die vorgesehene Rezeptur wird nicht durch eigenmächtiges Nachgießen verändert.")),
  ] },
  { id: "lf04-k02", titel: "Stahl und Beton als Verbund", einheiten: [
    einheit("lf04-l02", "Druck und Zug aufteilen", "Du kannst die unterschiedlichen Aufgaben von Beton und Stahl im Stahlbeton erklären.",
      "Stell dir einen belasteten Balken vor. Ein Teil seines Querschnitts wird zusammengestaucht, ein anderer auseinandergezogen. Beton kann hohe Druckkräfte aufnehmen, bei Zug entstehen dagegen vergleichsweise früh Risse. Bewehrungsstahl übernimmt deshalb die Zugkräfte. Gemeinsam bilden beide den Verbundbaustoff Stahlbeton. Dafür müssen die Kräfte zwischen den Materialien übertragen werden können; lose nebeneinander liegende Teile genügen nicht. Der Beton umschließt den Stahl, dessen Oberflächenrippen die Verbindung unterstützen. Bei Wärme ändern beide ihre Länge ähnlich stark. Außerdem bietet der alkalische Beton dem eingebetteten Stahl Schutz gegen Korrosion. Ein tragfähiges Bauteil braucht daher sowohl den passenden Stahl als auch eine richtig ausgeführte Betonhülle.",
      ["lf04-045", "lf04-046", "lf04-047"], "Warum wird ein Betonbalken durch passend angeordnete Bewehrung leistungsfähiger?", "Beton trägt hauptsächlich Druck, während die Bewehrung Zug übernimmt. Der Verbund überträgt die Kräfte zwischen beiden Materialien.",
      zuordnen("Wer übernimmt welche Aufgabe?", [["Beton", "Nimmt hauptsächlich Druck auf"], ["Bewehrungsstahl", "Übernimmt die Zugkräfte"], ["Verbund", "Überträgt Kräfte zwischen den Materialien"]], "Die Materialien ergänzen sich, wenn sie gemeinsam und in der richtigen Lage eingebaut werden.")),
    einheit("lf04-l15", "Verbund braucht Kontakt und Verzahnung", "Du kannst drei Voraussetzungen für das Zusammenwirken von Stahl und Beton nennen.",
      "Der Merksatz „Beton drückt, Stahl zieht“ beschreibt die Aufgaben, erklärt aber noch nicht die Verbindung. Die Zugkraft muss aus dem Beton in den Stahl gelangen können. Dabei wirken die Haftung am Zementstein und die Verzahnung der Stahlrippen zusammen. Der Stab darf sich nicht einfach im Bauteil verschieben. Auch die ähnliche Wärmeausdehnung hilft: Bei Temperaturwechseln wollen Stahl und Beton ihre Länge annähernd gemeinsam ändern. Beim Einbau ist deshalb wichtig, dass der Beton die Stäbe vollständig umschließt. Hohlräume an der Bewehrung beeinträchtigen das Zusammenwirken. Betrachte Stahlbeton als zusammenhängendes System aus Kraftaufnahme, Kraftübertragung und Schutz, wenn du einen Aufbau beurteilst.",
      ["lf04-044", "lf04-045", "lf04-047"], "Warum reicht es nicht, einen Stahlstab lose neben einen Betonbalken zu legen?", "Ohne Haftung und Verzahnung werden die Kräfte nicht zuverlässig zwischen beiden übertragen. Der Stahl muss in den Beton eingebettet sein.",
      fall("Glatter Hohlraum am Stahl", "Bei einer Kontrolle wird ein größerer Hohlraum direkt an der Bewehrung gefunden.", [["Die vollständige Umschließung des Stahls ist für den Verbund wichtig.", true], ["Der Befund muss fachlich beurteilt werden.", true], ["Die Rippen ersetzen den fehlenden Beton unabhängig vom Hohlraum.", false]], "Rippen funktionieren durch ihren Kontakt mit dem umgebenden Beton.")),
    einheit("lf04-l16", "Wärmedehnung mit Einheiten rechnen", "Du kannst eine vorgegebene Längenänderung berechnen und ihre Bedeutung für Stahlbeton erklären.",
      "Wird ein Bauteil wärmer, nimmt seine Länge zu. Stahl und Beton haben ähnliche Wärmeausdehnungskoeffizienten und passen deshalb im Verbund gut zusammen. In der vorliegenden Übung wird für Stahl mit 0,012 mm je Meter und Kelvin gerechnet. Die Längenänderung erhältst du aus Koeffizient mal Ausgangslänge mal Temperaturänderung. Bei 10 m Länge und 30 K Erwärmung ergibt das 0,012 mal 10 mal 30 gleich 3,6 mm. Die Temperaturänderung ist eine Differenz, keine einzelne Außentemperatur. Schreibe alle Einheiten dazu: So erkennst du, dass das Ergebnis Millimeter sind. Ein deutlich unterschiedliches Dehnverhalten der beiden Werkstoffe würde dagegen zusätzliche Spannungen im Verbund erzeugen.",
      ["lf04-051", "lf04-052", "lf04-053"], "Welche drei Angaben brauchst du für die Längenänderung und welche Einheit erhältst du im Beispiel?", "Ausdehnungskoeffizient, Ausgangslänge und Temperaturdifferenz; mit mm/(m·K), m und K ergibt sich die Änderung in mm.",
      ordnen("Die Dehnung nachvollziehbar berechnen", ["Ausgangslänge und Temperaturdifferenz erfassen", "Passenden vorgegebenen Ausdehnungskoeffizienten wählen", "Koeffizient, Länge und Differenz multiplizieren", "Ergebnis mit Einheit und Größenordnung prüfen"], "Eine Temperaturdifferenz und die zugehörige Länge gehören zu jedem Rechenansatz.")),
    einheit("lf04-l06", "B500 und Matten richtig lesen", "Du kannst Streckgrenze, Duktilität und Mattenart unterscheiden.",
      "Die Bezeichnung B500 beschreibt Betonstahl mit einer Streckgrenze von 500 N/mm². Bis in den elastischen Bereich kehrt Stahl nach Entlastung in seine Ausgangsform zurück; nach Überschreiten der Grenze bleibt Verformung zurück. Duktilität beschreibt, wie weit sich Stahl plastisch verformen kann, bevor er bricht. B500A und B500B haben dieselbe angegebene Streckgrenze, unterscheiden sich aber im Verformungsverhalten. B ist die höherduktile Variante. Die Rippen unterstützen den Verbund mit dem Beton. Für Flächen werden Stäbe außerdem zu Matten verschweißt. Lagermatten sind standardisierte Produkte, Listenmatten werden nach einer projektspezifischen Bestellung hergestellt. Festigkeit, Verformbarkeit und Lieferform beantworten also unterschiedliche Auswahlfragen.",
      ["lf04-038", "lf04-039", "lf04-041", "lf04-042"], "Hat B500B eine höhere Streckgrenze als B500A? Was unterscheidet die beiden?", "Beide tragen die Streckgrenze 500 N/mm² in der Bezeichnung. B500B ist höherduktil und kann sich vor dem Bruch stärker verformen.",
      zuordnen("Kennzeichnung und Lieferform", [["500", "Angegebene Streckgrenze in N/mm²"], ["Duktilität", "Plastische Verformbarkeit vor dem Bruch"], ["Lagermatte", "Standardisierte Matte vom Lager"], ["Listenmatte", "Matte nach projektbezogener Bestellung"]], "Die Mattenart ist keine zusätzliche Festigkeitsklasse.")),
  ] },
  { id: "lf04-k03", titel: "Umgebung, Bestellung und Umwelt", einheiten: [
    einheit("lf04-l07", "Angriffe aus der Umgebung erkennen", "Du kannst Expositionsklassen als Beschreibung der Beanspruchung erklären.",
      "Ein Innenbauteil und ein bewittertes Bauteil brauchen nicht denselben Schutz. Die Expositionsklassen beschreiben, was aus der Umgebung auf den Beton und seine Bewehrung einwirkt. XC steht für Carbonatisierung, bei der der Schutz des Stahls durch Veränderungen im Beton abnehmen kann. XD beschreibt Chloride aus anderen Quellen als Meerwasser, XS den Einfluss von Meerwasser. XF betrifft Frost, XA chemischen Angriff und XM mechanischen Verschleiß. X0 bezeichnet fehlendes Korrosions- oder Angriffsrisiko unter den dafür passenden Bedingungen. Bei einer Bestellung wird die Umgebung deshalb vorab geklärt. Eine höhere Druckfestigkeit allein ersetzt nicht das Ermitteln der tatsächlich auftretenden Beanspruchungen und der dazugehörigen Betoneigenschaften.",
      ["lf04-025", "lf04-026", "lf04-027", "lf04-087"], "Warum gehört die spätere Umgebung zur Betonbestellung?", "Sie bestimmt mögliche Angriffe wie Frost, Chloride oder Carbonatisierung. Daraus ergeben sich Anforderungen an den Beton und den Schutz der Bewehrung.",
      zuordnen("Angriff und Kennzeichen", [["XC", "Carbonatisierung"], ["XS", "Chloride aus Meerwasser"], ["XF", "Frostangriff"], ["XM", "Mechanischer Verschleiß"]], "Die Kennzeichen beschreiben Beanspruchungen; sie sind keine Namen für Zementsorten.")),
    einheit("lf04-l10", "Leistung bestellen oder Rezeptur vorgeben", "Du kannst die drei Festlegungsarten von Beton auseinanderhalten.",
      "Vor einer Betonlieferung muss eindeutig sein, was bestellt wurde. Bei Beton nach Eigenschaften nennt der Besteller die benötigten Leistungen, zum Beispiel Druckfestigkeitsklasse, Expositionsklasse und Konsistenz. Das Betonwerk wählt die passende Zusammensetzung. Bei Beton nach Zusammensetzung wird dagegen die Rezeptur vorgegeben. Diese Unterscheidung betrifft auch die Verantwortung für die Festlegung. Standardbeton ist in den vorhandenen Unterlagen für einfache, untergeordnete Anwendungen mit begrenzten Anforderungen beschrieben. Er ist keine beliebige Abkürzung für tragende oder stärker beanspruchte Bauteile. Lies vor der Bestellung die Planung und kläre unvollständige Angaben. Eine reine Mengenangabe in Kubikmetern beschreibt noch nicht die Qualität des benötigten Betons.",
      ["lf04-031", "lf04-032", "lf04-033", "lf04-097"], "Was gibst du bei Beton nach Eigenschaften vor und wer bestimmt die Rezeptur?", "Der Besteller nennt die verlangten Eigenschaften; das Betonwerk stellt die dazu passende Rezeptur zusammen.",
      fall("Bestellung nur nach Menge", "Für ein geplantes Stahlbetonbauteil steht auf dem Bestellzettel lediglich „3 m³ Beton“.", [["Die erforderlichen Eigenschaften müssen anhand der Planung ergänzt werden.", true], ["Eine Menge beschreibt noch keine Festigkeits- oder Expositionsklasse.", true], ["Jeder Standardbeton passt automatisch.", false]], "Menge und geforderte Qualität werden bei der Bestellung gemeinsam festgelegt.")),
    einheit("lf04-l08", "Den gesamten Lebensweg betrachten", "Du kannst eine Baustoffentscheidung anhand von Herstellung, Nutzung und Entsorgung beurteilen.",
      "Eine ökologische Baustoffentscheidung endet nicht am Werkstor. Rohstoffe werden gewonnen, Produkte hergestellt und transportiert, Bauteile über lange Zeit genutzt und schließlich zurückgebaut. Die Ökobilanz erfasst Umweltwirkungen über diesen Lebensweg und zeigt Stellen für Verbesserungen. Eine Produktlinienanalyse bezieht darüber hinaus gesellschaftliche und wirtschaftliche Aspekte ein. Bei Beton ist besonders die Zementherstellung mit hohem Energiebedarf und Emissionen verbunden. Trotzdem ist die Herstellungsphase nicht bei jedem Bauteil die größte Belastung. Heizenergie während vieler Nutzungsjahre kann ebenfalls stark ins Gewicht fallen. Vergleiche daher sowohl den Aufwand für einen Baustoff als auch seinen Beitrag zur dauerhaften Nutzung, etwa durch Wärmeschutz, Lebensdauer und spätere Wiederverwendung.",
      ["lf04-080", "lf04-081", "lf04-084", "lf04-085"], "Warum reicht der Energiebedarf bei der Herstellung allein für einen Umweltvergleich nicht aus?", "Auch Transport, langjährige Nutzung und Entsorgung wirken auf die Umwelt. Beispielsweise kann guter Wärmeschutz über viele Jahre Heizenergie sparen.",
      ordnen("Der Lebensweg eines Baustoffs", ["Rohstoffe gewinnen", "Baustoff herstellen und zur Baustelle bringen", "Bauteil einbauen und während der Nutzung erhalten", "Bauteil zurückbauen und verwerten oder entsorgen"], "Die Betrachtung umfasst den gesamten Weg; die Bauausführung ist nur eine Phase.")),
  ] },
  { id: "lf04-k04", titel: "Bewehrung nach Plan einbauen", einheiten: [
    einheit("lf04-l03", "Zugzone vor der Lage des Stahls klären", "Du kannst bei den beiden einfachen Tragmodellen die passende Bewehrungsseite begründen.",
      "Bewehrung gehört dorthin, wo im Bauteil Zugkräfte auftreten. Bei einer einfachen Platte auf zwei Auflagern senkt sich die Mitte unter der Last. Dabei wird die Unterseite länger und die Oberseite gestaucht. Im Feld liegt die Zugzone deshalb unten. Eine auskragende Balkonplatte verhält sich am eingespannten Ende anders: Hier entsteht bei einer Last nach unten oben Zug. Die beiden Fälle dürfen nicht verwechselt werden. Auf der Baustelle wird die Bewehrung nach dem geprüften Plan eingebaut, nicht nach einer bloßen Faustregel für alle Bauteile. Abstandhalter sichern zusätzlich die vorgesehene Betondeckung. Sie ersetzen die richtige Seite der Bewehrung ebenso wenig wie eine größere Betonmenge.",
      ["lf04-057", "lf04-058", "lf04-098"], "Wo liegt im vereinfachten Modell einer auf zwei Wänden gelagerten Platte die Zugzone im Feld?", "Unter einer Last nach unten liegt sie im Feld unten. Bei der Kragplatte liegt die maßgebende Zugzone am eingespannten Ende oben.",
      fall("Bewehrung auf der falschen Seite", "Die Fehlerskizze zeigt eine auf zwei Auflagern liegende Platte unter einer Last nach unten. Der einzige Stahl ist oben eingezeichnet.", [["Im Feld fehlt die Bewehrung an der unteren Zugseite.", true], ["Die tatsächliche Ausführung wird mit dem Bewehrungsplan abgeglichen.", true], ["Oben ist bei jeder Platte die richtige Zugseite.", false]], "Die Lagerung entscheidet über den Kraftverlauf. Die gezeigte Lage passt nicht zum beschriebenen einfachen Modell.", falschePlattenbewehrung)),
    einheit("lf04-l11", "Betondeckung als Schutz sichern", "Du kannst die Funktionen der Betondeckung und der Abstandhalter erklären.",
      "Betondeckung ist der Abstand von der Stahloberfläche zur nächstgelegenen Betonoberfläche. Sie bildet eine schützende Hülle für die Bewehrung. Diese Hülle hilft gegen Korrosion und verzögert im Brandfall die Erwärmung des Stahls. Das erforderliche Maß folgt aus der Planung und den Beanspruchungen des Bauteils. Abstandhalter halten den Stahl beim Einbringen und Verdichten an seinem vorgesehenen Platz. Liegt ein Stab direkt an der Schalung, bleibt an dieser Stelle keine ausreichende Hülle. Eine hübsche Oberfläche verdeckt diesen Fehler später möglicherweise. Prüfe die Lage deshalb vor dem Betonieren und beobachte sie während des Einbaus. Verschobene oder fehlende Abstandhalter sind ein Anlass zur Korrektur vor dem Überdecken.",
      ["lf04-048", "lf04-049", "lf04-050"], "Welche beiden Schutzaufgaben erfüllt die Betondeckung und wie wird sie beim Einbau gesichert?", "Sie schützt den Stahl gegen Korrosion und Hitze im Brandfall. Passende Abstandhalter halten die geplante Lage der Bewehrung.",
      fall("Stahl liegt an der Schalhaut", "Vor dem Betonieren berühren mehrere Bewehrungsstäbe die Schalung. Abstandhalter fehlen.", [["Die vorgesehene Deckung ist dort nicht gesichert.", true], ["Vor dem Einbau des Betons müssen Lage und Abstandhalter korrigiert werden.", true], ["Der Stahl wird durch den Beton später von selbst passend angehoben.", false]], "Die Deckung wird durch eine gesicherte Lage hergestellt und nicht dem Zufall überlassen.")),
    einheit("lf04-l17", "Vom Bewehrungsplan zum gebundenen Stahl", "Du kannst Planangaben nutzen und die Bewehrungsarbeiten in der richtigen Reihenfolge nennen.",
      "Der Bewehrungsplan zeigt Lage, Anzahl, Durchmesser und Form der Stäbe. Positionsnummern verbinden die Zeichnung mit der Stahlliste, nach der Material bestellt und zugeordnet wird. Vor dem Einlegen werden die Stäbe nach Vorgabe zugeschnitten und gebogen. Anschließend werden sie in der Schalung verlegt und an den Kreuzungspunkten mit Bindedraht verknüpft. Der Draht hält die Anordnung während der weiteren Arbeiten zusammen; die Kraftübertragung im fertigen Bauteil entsteht im Verbund mit dem Beton. Abstandhalter sichern die Deckung, zusätzliche Unterstützungen die geplante Höhenlage. Vor dem Betonieren werden Plan und Ausführung verglichen. Eine unklare Positionsnummer wird geklärt, bevor der Stahl dauerhaft überdeckt ist.",
      ["lf04-054", "lf04-056", "lf04-059", "lf04-060"], "Welche Reihenfolge gilt für die vier grundlegenden Bewehrungsarbeiten?", "Nach Plan zuschneiden, biegen, verlegen und mit Bindedraht verknüpfen; anschließend wird die richtige Lage vor dem Betonieren kontrolliert.",
      ordnen("Bewehrung vorbereiten und einbauen", ["Stäbe nach Plan zuschneiden", "Stäbe in die vorgegebene Form biegen", "Stäbe mit gesicherter Deckung in der Schalung verlegen", "Kreuzungspunkte mit Bindedraht verknüpfen", "Lage und Positionsangaben vor dem Betonieren kontrollieren"], "Erst nach der Kontrolle wird betoniert. Spätere Korrekturen sind wesentlich aufwendiger.")),
  ] },
  { id: "lf04-k05", titel: "Schalen, betonieren und prüfen", einheiten: [
    einheit("lf04-l18", "Den Lastweg durch die Schalung verfolgen", "Du kannst Schalhaut, Träger und Stützen nach ihren Aufgaben unterscheiden.",
      "Eine Schalung muss den frischen Beton bis zum ausreichenden Erhärten tragen und in Form halten. Direkt am Beton liegt die Schalhaut. Sie bestimmt Maße und Oberfläche und muss ausreichend dicht sein, damit kein Zementleim austritt. Die darunterliegende Unterkonstruktion trägt diese Haut; Stützen leiten die Last weiter in den Untergrund. Diagonalen sichern die Unterstützung gegen seitliches Ausweichen. Bei Wandschalungen nimmt der Seitendruck mit der Tiefe zu, weshalb die Sicherung nicht überall gleich beansprucht wird. Holz, beschichtete Platten, Stahl und Kunststoff haben unterschiedliche Einsatzvorteile. Entscheidend ist immer das Zusammenwirken: Eine dichte Schalhaut hilft nicht, wenn Träger oder ausgesteifte Unterstützung fehlen.",
      ["lf04-062", "lf04-068", "lf04-070", "lf04-071"], "Wie verläuft der Lastweg von einer Deckenschalhaut bis zum Boden?", "Von der Schalhaut über die Schalungsträger in die ausgesteiften Stützen und weiter in den ausreichend tragfähigen Untergrund.",
      zuordnen("Teile einer Schalung", [["Schalhaut", "Berührt den Beton und gibt die Oberfläche vor"], ["Schalungsträger", "Trägt die Schalhaut"], ["Stütze", "Leitet Lasten zum Untergrund"], ["Diagonale", "Sichert gegen seitliches Ausweichen"]], "Tragen und seitliches Aussteifen sind verschiedene, gemeinsam notwendige Aufgaben.")),
    einheit("lf04-l19", "Schalung an das Bauteil anpassen", "Du kannst die Grundformen von Wand-, Balken- und Deckenschalung beschreiben.",
      "Die Form des Bauteils bestimmt die Grundform seiner Schalung. Bei einer Wand halten gegenüberliegende Schalseiten den Beton; Anker und Gurte sichern sie gegen den seitlichen Druck. Eine Balkenschalung bildet ein U aus einer Bodenplatte und zwei Seitenplatten. Die Lasten gelangen über Kopfhölzer und Stützen nach unten. Bei Decken tragen Schalungsträger die großflächige Schalhaut und geben ihre Last an die Unterstützung weiter. Die genauen Abstände ergeben sich aus der vorgesehenen Konstruktion und ihren Vorgaben. Vor dem Betonieren wird geeignetes Trennmittel auf die Schalhaut aufgebracht. Es vermindert das Anhaften des Betons und erleichtert das spätere Lösen. Trennmittel ersetzt weder Dichtheit noch eine ausreichend tragfähige Schalung.",
      ["lf04-072", "lf04-073", "lf04-075", "lf04-089"], "Welche Form hat eine Balkenschalung und wozu dient das Trennmittel?", "Sie hat eine Bodenplatte und zwei Seitenplatten, also einen U-förmigen Querschnitt. Trennmittel vermindert das Anhaften des Betons an der Schalhaut.",
      zuordnen("Konstruktion erkennen", [["Balkenschalung", "U-Form aus Boden und zwei Seiten"], ["Wandschalung", "Gegenüberliegende, gegeneinander gesicherte Schalseiten"], ["Deckenschalung", "Flächige Haut auf Trägern und Stützen"], ["Trennmittel", "Erleichtert das Lösen der Schalhaut"]], "Bauteilform, Lastabtragung und Oberflächenbehandlung werden gemeinsam geplant.")),
    einheit("lf04-l12", "Mengen berechnen und Ausschalen begründen", "Du kannst Fertigmenge, Rohmenge und Betonvolumen unterscheiden und den Ausschalzeitpunkt erklären.",
      "Aus dem Schalungsplan entsteht eine Holzliste mit Bezeichnungen, Stückzahlen, Querschnitten und Längen. Die Fertigmenge beschreibt das eingebaute Material, die Rohmenge enthält zusätzlich den vorgegebenen Verschnitt. Bei 24 m² Schalfläche und 15 Prozent Zuschlag ergibt die Übungsrechnung 24 mal 1,15 gleich 27,6 m². Beton wird dagegen als Volumen in Kubikmetern bestellt: Länge mal Breite mal Höhe. Beim Zuschnitt eines quadratischen Kantholzes aus Rundholz entspricht dessen Diagonale dem Kreisdurchmesser. Ausschalen ist schließlich eine Frage ausreichender Betonfestigkeit. Bauteil, Temperatur und Erhärtung beeinflussen den Zeitpunkt. Hilfsstützen können weiter erforderlich sein. Eine errechnete Materialmenge sagt daher noch nichts darüber, wann die Unterstützung entfallen darf.",
      ["lf04-076", "lf04-078", "lf04-079", "lf04-092"], "Warum wird die Schalungsfläche in m² und die Betonbestellung in m³ angegeben?", "Die Schalungsfläche ist eine Oberfläche. Die Betonbestellung beschreibt einen räumlichen Körper und benötigt zusätzlich dessen Dicke beziehungsweise Höhe.",
      fall("Alle Stützen sofort entfernen?", "Die seitliche Schalung lässt sich lösen. Eine Person will daraus ableiten, dass auch jede tragende Unterstützung entfernt werden kann.", [["Der erforderliche Festigkeitszustand und die Planung müssen geprüft werden.", true], ["Hilfsstützen können weiterhin notwendig sein.", true], ["Eine gelöste Seitenplatte beweist die volle Tragfähigkeit der Decke.", false]], "Die Lösbarkeit der Schalhaut ist kein Nachweis ausreichender Tragfähigkeit.")),
    einheit("lf04-l04", "Form, Verdichtung und Schutz verbinden", "Du kannst erklären, warum eine dichte Schalung, richtige Verdichtung und Nachbehandlung zusammengehören.",
      "Beim Betonieren wirken drei unterschiedliche Arbeitsschritte zusammen. Die Schalung hält den Frischbeton in der vorgesehenen Form und muss dessen Druck aufnehmen. Undichte Fugen lassen Zementleim austreten und können Fehlstellen verursachen. Nach dem Einbringen entfernt die Verdichtung eingeschlossene Luft und bringt den Beton dicht an die Bewehrung. Zu langes oder ungeeignetes Rütteln kann die Mischung jedoch entmischen. Danach schützt die Nachbehandlung den jungen Beton vor zu schnellem Austrocknen und schädlichen Witterungseinflüssen. Das Wasser wird für die Hydratation benötigt. Die Arbeit endet deshalb nicht mit dem Abziehen der Oberfläche. Behalte Formhaltung, innere Dichte und ungestörtes Erhärten als drei getrennte Kontrollpunkte im Blick.",
      ["lf04-035", "lf04-036", "lf04-071"], "Welche Aufgabe hat jeder der drei Schritte Schalung, Verdichtung und Nachbehandlung?", "Schalung hält Form und Frischbetonlast; Verdichtung entfernt eingeschlossene Luft; Nachbehandlung ermöglicht geschütztes Erhärten ohne zu frühen Wasserverlust.",
      ordnen("Betonierabschnitt ausführen", ["Dichte und tragfähige Schalung vorbereiten und kontrollieren", "Beton einbringen", "Beton fachgerecht verdichten", "Oberfläche fertigstellen und Nachbehandlung beginnen"], "Nachbehandlung schließt unmittelbar an die Herstellung an und gehört zum Arbeitsablauf.")),
    einheit("lf04-l09", "Lieferung, Einbau und Nachbehandlung planen", "Du kannst einen Betonierablauf so vorbereiten, dass Verarbeitungszeit und Erhärtung berücksichtigt werden.",
      "Transportbeton wird im Werk nach der Bestellung gemischt und mit dem Fahrmischer angeliefert. Auf der Baustelle müssen Einbauweg, Personal und Geräte vorbereitet sein, damit der Beton innerhalb seiner Verarbeitungszeit eingebaut wird. Beim Einbringen bleibt zunächst Luft in der Mischung. Innenrüttler arbeiten im Beton, Außenrüttler an der Schalung; beide unterstützen die Verdichtung auf unterschiedliche Weise. Anschließend beginnt der Schutz des jungen Betons. Folie, geeignetes Feuchthalten oder vorgesehene Nachbehandlungsmittel können den schnellen Wasserverlust begrenzen. Sonne, Wind und Frost sind dabei mitzudenken. Eine gute Rezeptur allein sichert das Ergebnis nicht: Der organisierte Einbau und die weitere Behandlung entscheiden mit über die tatsächlich erreichte Qualität.",
      ["lf04-034", "lf04-035", "lf04-037", "lf04-096"], "Warum müssen Geräte und Nachbehandlung bereits vor der Lieferung vorbereitet sein?", "Der Beton hat eine begrenzte Verarbeitungszeit und braucht nach dem Einbau sofort geeigneten Schutz. Unvorbereitete Abläufe gefährden Verdichtung und Erhärtung.",
      fall("Fahrmischer kommt zu früh", "Der Fahrmischer steht bereit, aber der Rüttler fehlt und Schutzmaterial für die fertige Fläche ist noch nicht vorhanden.", [["Der vorbereitete Betonierablauf ist unvollständig.", true], ["Verdichtung und Nachbehandlung müssen organisiert werden.", true], ["Das Betonwerk ersetzt die fehlenden Arbeiten durch die Rezeptur.", false]], "Bestellte Eigenschaften müssen durch geeignete Verarbeitung und Nachbehandlung erhalten werden.")),
  ] },
];
const fehlendeWandstrebe = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 210"><title>Fehlerskizze: rechteckige Holzrahmen ohne Aussteifung</title><g fill="none" stroke="currentColor" stroke-width="5"><path d="M80 160V50h330v110zM190 50v110M300 50v110M30 90h40m-12-10 12 10-12 10"/></g><g fill="currentColor" font-family="sans-serif" font-size="17"><text x="45" y="30">seitlicher Wind</text><text x="80" y="195">keine Strebe, keine aussteifende Beplankung</text></g></svg>';
const lf05: LernKapitel[] = [
  { id: "lf05-k01", titel: "Holz erkennen und auswählen", einheiten: [
    einheit("lf05-l14", "Aufbau und Wachstum des Holzes", "Du kannst Stammteile, Jahresringe und Schnittrichtungen ihren Merkmalen zuordnen.",
      "Ein Baum bildet mit Sonnenlicht aus Wasser und Kohlenstoffdioxid seine Aufbaustoffe. Diese Fotosynthese bindet Kohlenstoff und setzt Sauerstoff frei. Im Stamm erzeugt das Kambium zwischen Holz und Rinde neue Zellen. Innen liegt das häufig dunklere Kernholz, außen das saftführende Splintholz. Ein Jahresring umfasst helles Frühholz und dichteres Spätholz. Cellulose unterstützt vor allem die Zugfestigkeit, Lignin die Druckfestigkeit. Beim Nadelholz übernehmen Tracheiden sowohl Leitungs- als auch Stützaufgaben. Die Schnittrichtung verändert das sichtbare Bild: Im Querschnitt erkennst du Ringe, im Radialschnitt parallele Streifen und Markstrahlen, im Tangentialschnitt die Fladerung. Solche Merkmale helfen dir, ein Brett fachlich zu beschreiben.",
      ["lf05-008", "lf05-009", "lf05-010", "lf05-107"], "Wie unterscheiden sich Kernholz und Splintholz im lebenden Baum?", "Kernholz liegt innen und ist häufig durch eingelagerte Stoffe dunkler und widerstandsfähiger. Das äußere Splintholz führt Wasser und Nährstoffe.",
      zuordnen("Stamm und Schnitt erkennen", [["Kambium", "Wachstumsschicht zwischen Holz und Rinde"], ["Jahresring", "Frühholz und Spätholz eines Jahres"], ["Querschnitt", "Schnitt quer durch den Stamm"], ["Tangentialschnitt", "Längsschnitt mit Fladerung"]], "Die sichtbare Holzzeichnung hängt vom Wachstum und von der Lage des Schnitts ab.")),
    einheit("lf05-l01", "Nadelholz und Laubholz am Bau", "Du kannst typische Bauhölzer nennen und ihre Auswahl mit Eigenschaften begründen.",
      "Für einen Dachstuhl wird häufig Nadelholz eingesetzt, besonders Fichte oder Tanne. Solche Hölzer wachsen vergleichsweise gerade, sind gut zu bearbeiten und haben ein günstiges Verhältnis von Gewicht zu Tragfähigkeit. Kiefer, Lärche und Douglasie gehören ebenfalls zu den Nadelhölzern. Laubhölzer wie Eiche oder Buche sind häufig härter und schwerer. Eiche begegnet dir beispielsweise im historischen Fachwerk und bei stark beanspruchten Bauteilen. Die Holzart allein beweist jedoch keine ausreichende Tragfähigkeit eines einzelnen Balkens. Für tragende Teile wird sortiertes Bauholz in der vorgesehenen Qualität verwendet. Betrachte deshalb Art, Zustand, Feuchte und Kennzeichnung zusammen, bevor du ein Holz einem geplanten Einsatz zuordnest.",
      ["lf05-001", "lf05-002", "lf05-003"], "Warum reicht die Aussage „Das ist Fichte“ für die Freigabe eines tragenden Balkens nicht aus?", "Die Holzart beschreibt typische Eigenschaften. Tragfähigkeit und Eignung hängen auch von Sortierung, Zustand, Feuchte und der geforderten Klasse ab.",
      zuordnen("Holzarten unterscheiden", [["Fichte", "Häufiges Nadelholz für Dachstühle"], ["Tanne", "Nadelholz für Bauholz"], ["Eiche", "Hartes Laubholz, auch im historischen Fachwerk"], ["Buche", "Hartes Laubholz für beanspruchte Innenbauteile"]], "Typische Verwendungen geben Orientierung; die konkrete Eignung muss zusätzlich stimmen.")),
    einheit("lf05-l10", "Holzart und Wachstumsfehler prüfen", "Du kannst natürliche Merkmale benennen, die Auswahl und Tragfähigkeit beeinflussen.",
      "Bei der Holzauswahl werden erwünschte Eigenschaften und begrenzende Merkmale gemeinsam betrachtet. Fichte ist leicht zu bearbeiten und ein verbreitetes Bauholz. Kiefer und Lärche besitzen einen hohen Harzgehalt; Eiche ist hart, dicht und für bestimmte Feuchtebeanspruchungen dauerhaft. Solche Vorteile machen Holz aber nicht unabhängig von der Konstruktion. Ein Stamm kann krumm wachsen, stark zum Wipfel dünner werden oder spiralförmige Fasern entwickeln. Dieser Drehwuchs begünstigt Verziehen beim Trocknen. Äste, Risse und Harzgallen beeinflussen ebenfalls Nutzwert und Ausbeute. Erkenne und benenne sichtbare Merkmale, statt einen Balken nur nach seiner Farbe zu beurteilen. Die Bewertung für tragende Anwendungen folgt der vorgesehenen Sortierung.",
      ["lf05-004", "lf05-012", "lf05-013"], "Was bedeutet Drehwuchs und welche Folge kann er beim Trocknen haben?", "Die Fasern verlaufen spiralförmig um den Stamm. Das Holz kann sich beim Trocknen stark verziehen und windschief werden.",
      fall("Ein verdrehter Balken", "Ein angeliefertes Holz zeigt schräg umlaufende Fasern und hat sich nach dem Trocknen deutlich verdreht.", [["Drehwuchs kann die Verformung erklären.", true], ["Für tragenden Einsatz sind Sortierung und Eignung zu prüfen.", true], ["Die Holzart allein macht jede Verformung bedeutungslos.", false]], "Natürliche Merkmale werden bei der Qualitätsbeurteilung berücksichtigt.")),
    einheit("lf05-l16", "Sortierung und KVH einordnen", "Du kannst den Zweck der Sortierung und typische Eigenschaften von KVH erklären.",
      "Tragendes Holz wird nach Merkmalen sortiert, die seine Festigkeit beeinflussen. Besonders wichtig sind Äste, weil sie den geraden Faserverlauf unterbrechen. Auch Faserneigung, Risse, Jahrringbreite und Baumkante werden berücksichtigt. Sortierklasse und Festigkeitsklasse hängen zusammen; die vorhandenen Unterlagen zeigen beispielsweise die Zuordnung S10 zu C24. Eine solche Kennzeichnung ist aussagekräftiger als die bloße Einschätzung „sieht kräftig aus“. Konstruktionsvollholz, kurz KVH, ist ein entsprechend qualitätsgesichertes Vollholzprodukt. Es wird sortiert, technisch getrocknet und maßhaltig hergestellt; Keilzinken ermöglichen geeignete Längen. Für sichtbare Konstruktionen sind außerdem Oberflächenqualität und Rissarmut interessant. Verwende die jeweils in der Planung geforderte Klasse und Produktqualität.",
      ["lf05-019", "lf05-020", "lf05-021"], "Warum ist Ästigkeit ein wichtiges Sortiermerkmal?", "Äste unterbrechen beziehungsweise verändern den Faserverlauf und können dadurch die Tragfähigkeit des Holzes vermindern.",
      zuordnen("Auswahlkriterien verstehen", [["Sortierung", "Bewertet festigkeitsrelevante Holzmerkmale"], ["S10 zu C24", "Beispiel einer Zuordnung aus den Unterlagen"], ["KVH", "Qualitätsgesichertes, technisch getrocknetes Vollholz"], ["Ästigkeit", "Merkmal mit Einfluss auf den Faserverlauf"]], "Festigkeitsklasse, Produktart und sichtbare Oberfläche sind unterschiedliche Auswahlmerkmale.")),
  ] },
  { id: "lf05-k02", titel: "Feuchte, Bewegung und Holzschutz", einheiten: [
    einheit("lf05-l02", "Holzfeuchte verändert Maße", "Du kannst Schwinden und Quellen mit der Aufnahme und Abgabe von Wasser erklären.",
      "Holz passt seine Feuchte an die Umgebung an. Gibt es Wasser ab, kann es schwinden; nimmt es Wasser auf, kann es quellen. Die maßgeblichen Formänderungen entstehen unterhalb des Fasersättigungsbereichs bei ungefähr 30 Prozent Holzfeuchte. Deshalb wird frisches Holz vor dem Einbau passend getrocknet. Sonst können nachträglich Fugen, Verformungen oder Risse entstehen. Auch für den Schutz gegen Pilze ist Feuchte entscheidend: Länger anhaltende Durchfeuchtung schafft ungünstige Bedingungen. Eine einzelne Messzahl ohne Kenntnis des Bauteils beschreibt jedoch noch nicht die ganze Situation. Prüfe Feuchtequelle, zeitlichen Verlauf und Abtrocknungsmöglichkeiten gemeinsam. Ziel ist ein Holzfeuchtezustand, der zur späteren Nutzung und zur Konstruktion passt.",
      ["lf05-031", "lf05-032", "lf05-034"], "Was geschieht mit Holz beim Trocknen unterhalb des Fasersättigungsbereichs?", "Es gibt gebundenes Wasser aus den Zellwänden ab und schwindet. Die Bewegung kann zu Fugen oder Verformungen führen.",
      zuordnen("Feuchte und Bewegung", [["Wasseraufnahme", "Kann Quellen verursachen"], ["Wasserabgabe", "Kann Schwinden verursachen"], ["Holzfeuchtegleichgewicht", "Anpassung an die umgebende Luft"], ["Passende Einbaufeuchte", "Verringert spätere starke Maßänderungen"]], "Die Richtung der Feuchteänderung erklärt die Richtung der Maßänderung.")),
    einheit("lf05-l05", "Faserrichtung und Schwindrichtung beachten", "Du kannst die richtungsabhängigen Eigenschaften des Holzes auf eine Bauteilentscheidung anwenden.",
      "Holz ist längs und quer zur Faser unterschiedlich belastbar. Stell dir ein Bündel feiner Röhren vor: In Längsrichtung kann es gut Kräfte aufnehmen, quer lässt es sich leichter zusammendrücken oder aufspalten. Auch beim Trocknen ändert Holz seine Maße nicht in alle Richtungen gleich. Entlang der Fasern ist das Schwinden gering, tangential zu den Jahresringen größer als radial. Diese Unterschiede erklären das Wölben von Brettern und das Verziehen von Querschnitten. Rohdichte beeinflusst außerdem die Härte. Für eine gute Ausführung müssen daher Faserlage, geplante Beanspruchung und Feuchte zusammenpassen. Bewegungsmöglichkeiten und geeignete Befestigungen sind sinnvoller, als Holz als unveränderlichen, in jede Richtung gleichen Stoff zu behandeln.",
      ["lf05-028", "lf05-029", "lf05-033", "lf05-035"], "Warum kann ein Brett beim Trocknen hohl werden, obwohl die Feuchte insgesamt abnimmt?", "Es schwindet je nach Richtung unterschiedlich stark. Besonders der Unterschied zwischen tangentialem und radialem Schwinden verursacht Verformungen.",
      fall("Ein Brett ist kein Stahlprofil", "Ein Brett wird quer zur Faser auf Zug belastet. Jemand begründet die Eignung allein mit der hohen Zugfestigkeit längs zur Faser.", [["Die Faserrichtung muss bei der Beurteilung berücksichtigt werden.", true], ["Längs- und Querfestigkeit sind nicht gleich.", true], ["Feuchte und Äste können zusätzlich Einfluss haben.", true], ["Ein Wert längs zur Faser gilt unverändert quer dazu.", false]], "Holz besitzt richtungsabhängige Eigenschaften und braucht dazu passende Anschlüsse.")),
    einheit("lf05-l15", "Gleichmäßig statt möglichst schnell trocknen", "Du kannst Freilufttrocknung und technische Trocknung nach ihrem Zweck unterscheiden.",
      "Bei der Freilufttrocknung gibt luftig gestapeltes Holz Wasser an die Umgebung ab. Stapelleisten ermöglichen Luft zwischen den Lagen; Schutz vor Regen und direkter Sonne sowie Abstand zum Boden begrenzen erneute Befeuchtung und ungleichmäßiges Trocknen. Das Ergebnis hängt vom Außenklima ab und wird als lufttrocken bezeichnet. Für geringere oder gezielt eingestellte Feuchten wird technische Trocknung eingesetzt. Sie steuert die Bedingungen in einer Anlage und ist beispielsweise für entsprechend hergestellte Holzprodukte wichtig. Zu schnelles Austrocknen der Oberfläche kann Spannungen gegenüber dem noch feuchten Kern erzeugen. Risse werden deshalb durch abgestimmtes, gleichmäßiges Trocknen begrenzt. Entscheidend ist die benötigte Endfeuchte am vorgesehenen Einsatzort.",
      ["lf05-038", "lf05-039", "lf05-040", "lf05-109"], "Warum sind Sonne und hohe Geschwindigkeit nicht automatisch gute Bedingungen zum Holztrocknen?", "Die Oberfläche kann schneller trocknen als der Kern. Daraus entstehen Spannungen und Risse; gleichmäßige, kontrollierte Trocknung ist günstiger.",
      ordnen("Einen Freiluftstapel vorbereiten", ["Geeigneten geschützten Lagerplatz mit Bodenabstand wählen", "Holzlagen mit Stapelleisten luftig aufbauen", "Stapel gegen Regen und direkte Sonne schützen", "Trocknung und erforderliche Endfeuchte kontrollieren"], "Der Aufbau ermöglicht Luftzirkulation und begrenzt zugleich erneute Feuchteaufnahme.")),
    einheit("lf05-l03", "Feuchte zuerst konstruktiv vermeiden", "Du kannst bauliche Holzschutzmaßnahmen auswählen und ihre Grenzen erklären.",
      "Holzschutz beginnt mit einer Konstruktion, die Wasser fernhält und Abtrocknen ermöglicht. Dachüberstände, Abtropfkanten, Abstand zu feuchten Flächen und geeignete Hinterlüftung sind typische Maßnahmen. Besonders gefährdete Anschlüsse, etwa Balkenköpfe im Mauerwerk, brauchen einen geplanten Schutz gegen Feuchtenachschub. Dauerhaftes Trockenhalten begrenzt das Risiko holzzerstörender Pilze. Bei Insekten ist die Beurteilung differenzierter; trockenes Holz ist nicht für jede Art automatisch geschützt. Chemische Mittel werden passend zum festgestellten Bedarf und ihren Vorgaben eingesetzt. Sie können eine fehlerhafte Wasserführung nicht ausgleichen. Bei der Arbeit sind Kennzeichnung, Schutzmaßnahmen, sichere Aufbewahrung und fachgerechte Entsorgung zu beachten. Frage zuerst, woher Feuchte kommt und wie sie wieder entweichen kann.",
      ["lf05-045", "lf05-046", "lf05-048", "lf05-049"], "Warum beseitigt ein Holzschutzanstrich keinen undichten Anschluss?", "Er stoppt den Feuchtenachschub aus der fehlerhaften Konstruktion nicht. Zuerst müssen Wasserführung und Abtrocknung konstruktiv verbessert werden.",
      fall("Nasser Balkenkopf", "Ein Balkenkopf bleibt wegen eines undichten Anschlusses feucht. Als einzige Maßnahme wird ein Schutzmittel vorgeschlagen.", [["Die Feuchtequelle muss zuerst geklärt und beseitigt werden.", true], ["Der Anschluss braucht geeignete Abtrocknungsbedingungen.", true], ["Ein Mittel macht jede dauerhaft nasse Konstruktion zuverlässig unschädlich.", false]], "Baulicher Schutz hat Vorrang. Chemische Maßnahmen werden nur bedarfsgerecht ergänzt.")),
    einheit("lf05-l11", "Pilz und Insekt nicht verwechseln", "Du kannst typische Befallsmerkmale beschreiben und die Ursache fachlich unterscheiden.",
      "Holzzerstörende Pilze benötigen geeignete Feuchte, Wärme und Sauerstoff. Bei einer feuchten Schadstelle gehören deshalb die Suche nach der Wasserquelle und die Beurteilung der Ausbreitung zusammen. Der Echte Hausschwamm ist besonders kritisch, weil seine Stränge auch durch Risse und Poren benachbarter Baustoffe wachsen können. Insekten hinterlassen andere Spuren. Der Hausbock befällt Nadelholz; seine Larven können auch in trockenem Splintholz fressen. Typisch sind ovale Fluglöcher. Beim Nagekäfer fallen eher kleine runde Löcher und Bohrmehl auf; er kann auch Laubholz befallen. Solche Beobachtungen begründen einen Verdacht, ersetzen aber keine fachliche Feststellung des aktiven Befalls und des verbleibenden tragfähigen Querschnitts.",
      ["lf05-041", "lf05-042", "lf05-043", "lf05-044"], "Warum beweist trockenes Holz nicht, dass jeder Insektenbefall ausgeschlossen ist?", "Beispielsweise können Hausbocklarven im trockenen Splintholz von Nadelholz fressen. Pilz- und Insektenrisiken müssen getrennt beurteilt werden.",
      zuordnen("Schadenshinweise zuordnen", [["Pilzwachstum", "Benötigt geeignete Feuchtebedingungen"], ["Echter Hausschwamm", "Kann sich über Stränge in Nachbarbereiche ausbreiten"], ["Hausbock", "Nadelholz und eher ovale Fluglöcher"], ["Nagekäfer", "Eher kleine runde Löcher und Bohrmehl"]], "Die Merkmale helfen beim Beschreiben; Aktivität und Tragfähigkeit werden fachlich untersucht.")),
  ] },
  { id: "lf05-k03", titel: "Produkte, Werkzeuge und Verbindungen", einheiten: [
    einheit("lf05-l06", "Holzplatten nach ihrem Aufbau unterscheiden", "Du kannst Sperrholz, OSB und poröse Faserplatten passenden Aufgaben zuordnen.",
      "Holzwerkstoffe bestehen aus zusammengesetzten Schichten, Spänen oder Fasern. Beim Sperrholz werden Furnierlagen kreuzweise verleimt. Dadurch begrenzen sie gegenseitig das Quellen und Schwinden. Eine Tischlerplatte besitzt eine Mittellage aus Leisten oder Furnierstreifen zwischen Decklagen. OSB besteht dagegen aus langen Spänen, die in den Schichten gezielt ausgerichtet werden. Poröse Holzfaserplatten enthalten viel Luft und werden unter anderem zum Dämmen verwendet. Aus dieser Dämmwirkung folgt keine automatische Eignung als tragende Beplankung. Produktklasse, Feuchtebeanspruchung und vorgesehene Aufgabe müssen zusammenpassen. Auch vorgeformte Holzprodukte wie Fasebretter oder Fußleisten gehören zur Auswahl am Bau, erfüllen aber andere Aufgaben als aussteifende Platten.",
      ["lf05-023", "lf05-025", "lf05-026", "lf05-108"], "Was unterscheidet den Aufbau einer OSB-Platte von Sperrholz?", "OSB besteht aus ausgerichteten langen Holzspänen, Sperrholz aus kreuzweise verleimten Furnierlagen.",
      zuordnen("Aufbau und Einsatz", [["Sperrholz", "Kreuzweise verleimte Furnierlagen"], ["OSB", "Ausgerichtete lange Späne"], ["Tischlerplatte", "Mittellage zwischen Deckfurnieren"], ["Poröse Faserplatte", "Luftreiches Gefüge für Dämmaufgaben"]], "Der Materialname wird durch Produktklasse und vorgesehene Anwendung ergänzt.")),
    einheit("lf05-l17", "Handelsformen sicher bestellen", "Du kannst Einschnittart, Querschnittsform und Brettschichtholz auseinanderhalten.",
      "Eine Holzliste muss eindeutig sagen, welches Produkt benötigt wird. Die Einschnittart beschreibt zunächst, wie ein Stamm aufgeteilt wurde: als Ganzholz, Halbholz oder Viertelholz. Davon getrennt stehen die Handelsformen des Querschnitts, etwa Kantholz, Bohle, Brett und Latte. Für deren genaue Abgrenzung werden die Abmessungen mit den in den Unterlagen genannten Kriterien verglichen. Gib Breite, Höhe beziehungsweise Dicke und Länge deshalb vollständig an. Brettschichtholz entsteht auf andere Weise: Mehrere Brettlamellen werden flach miteinander verleimt. Damit lassen sich lange und auch gekrümmte tragende Bauteile herstellen. Ein Produktname ersetzt somit weder die benötigten Maße noch die geforderte Festigkeits- und Nutzungsqualität in der Bestellung.",
      ["lf05-014", "lf05-015", "lf05-016", "lf05-018"], "Beschreiben „Halbholz“ und „Brett“ dieselbe Eigenschaft?", "Nein. Halbholz beschreibt die Art des Einschnitts, Brett eine durch die Abmessungen bestimmte Querschnittsform.",
      zuordnen("Bezeichnungen sortieren", [["Halbholz", "Bezeichnet die Aufteilung des Stammes"], ["Brett", "Bezeichnet eine Querschnittsform"], ["Brettschichtholz", "Besteht aus verleimten Brettlamellen"], ["Holzliste", "Nennt Produkt, Anzahl und vollständige Maße"]], "Herstellung und Abmessungen sind getrennte Angaben desselben bestellten Bauteils.")),
    einheit("lf05-l08", "Werkzeug nach der Arbeit auswählen", "Du kannst wichtige Handwerkzeuge ihren Aufgaben zuordnen und sichere Vorbereitung begründen.",
      "Beim Bearbeiten von Holz bestimmt die Aufgabe das Werkzeug. Ein Stemmeisen eignet sich für viele Ausstemmungen; ein schmaler, kräftiger Lochbeitel für tiefe Zapfenlöcher. Beim Hobeln werden raue Flächen zunächst vorgehobelt und anschließend mit dem Putzhobel geglättet. Der Simshobel bearbeitet Fälze. Sägezähne und ihre Schränkung müssen zur Schnittaufgabe passen: Der Schnittspalt braucht Raum für das Blatt, damit es nicht klemmt. Forstnerbohrer erzeugen flache Bohrungen mit ebenem Grund, Schlangenbohrer dienen tiefen Bohrungen. Sichere Auflage, geeignete Werkzeuge und die vorgeschriebenen Schutzmaßnahmen gehören zusammen. Bei Montagearbeiten in der Höhe müssen außerdem sichere Arbeitsplätze und geeigneter Absturzschutz vor Beginn vorhanden sein.",
      ["lf05-050", "lf05-051", "lf05-054", "lf05-094"], "Warum ist der Lochbeitel für ein schmales tiefes Zapfenloch geeignet?", "Er besitzt eine schmale, kräftige Klinge für diese Arbeit. Werkzeugwahl und sichere Werkstückauflage müssen zur Aufgabe passen.",
      zuordnen("Werkzeug und Aufgabe", [["Lochbeitel", "Schmale tiefe Löcher ausstemmen"], ["Putzhobel", "Vorgehobelte Flächen fein glätten"], ["Simshobel", "Fälze hobeln"], ["Forstnerbohrer", "Flache Bohrung mit ebenem Grund herstellen"]], "Ein bekanntes Werkzeug wird nicht für jede Bearbeitung gleich eingesetzt.")),
    einheit("lf05-l18", "Verbindungsmittel passend einsetzen", "Du kannst Nagel, Schraubenbolzen, Stabdübel und besondere Dübel nach ihrer Funktion unterscheiden.",
      "Verbindungsmittel übertragen Kräfte nur in einer dazu passenden Anordnung. Bei Nägeln beeinflussen Holzart, Durchmesser, Einschlagrichtung und Einbindetiefe die Verbindung. Vorbohren oder geeignete Bearbeitung der Spitze kann Spalten begrenzen. Die in einer Übung verwendete Regel zur dreifachen Brettdicke ist eine Rechenvorgabe und ersetzt keine bemessene Verbindung. Schrauben brauchen ein passendes Werkzeug, damit der Kopf nicht beschädigt wird. Schraubenbolzen verspannen Hölzer mit Mutter und Unterlegscheibe. Stabdübel werden dagegen in passende vorgebohrte Löcher eingesetzt, ohne selbst zu verspannen. Ringkeil- und Krallendübel übertragen größere Kräfte über kleine Anschlussflächen und werden mit Bolzen zusammengespannt. Produktvorgaben und Planung bestimmen jeweils die tatsächliche Ausführung.",
      ["lf05-069", "lf05-071", "lf05-074", "lf05-115"], "Was ist der grundlegende Unterschied zwischen Schraubenbolzen und Stabdübel?", "Ein Schraubenbolzen verspannt die Verbindung mit Mutter und Unterlegscheibe. Ein Stabdübel wird in die Bohrung eingesetzt und verspannt sie nicht selbst.",
      fall("Ein Stabdübel soll verspannen", "Eine Verbindung muss laut Planung verspannt werden. Jemand ersetzt den vorgesehenen Schraubenbolzen durch einen glatten Stabdübel.", [["Ein Stabdübel stellt die verlangte Verspannung nicht selbst her.", true], ["Die geplante Verbindung muss eingehalten beziehungsweise fachlich geändert werden.", true], ["Gleicher Durchmesser bedeutet automatisch gleiche Funktion.", false]], "Geometrie allein macht unterschiedliche Verbindungsmittel nicht austauschbar.")),
  ] },
  { id: "lf05-k04", titel: "Wände und Holzbedarf", einheiten: [
    einheit("lf05-l19", "Eine Fachwerkwand trägt und steift aus", "Du kannst Rähm, Schwelle, Pfosten, Strebe und Riegel in einer Wand benennen.",
      "Eine Fachwerkwand muss senkrechte Lasten und seitliche Einwirkungen sicher weiterleiten. Oben liegt das Rähm, unten die Schwelle, dazwischen stehen die Pfosten. Diese Hölzer bilden den wesentlichen Weg der senkrechten Lasten. Schräge Streben verhindern gemeinsam mit der übrigen Konstruktion das seitliche Verschieben. Riegel liegen waagerecht zwischen den Pfosten und gliedern die Wand. Ein bloßes Rechteck aus gelenkigen Anschlüssen wäre seitlich verformbar; die Aussteifung gehört deshalb zum Tragprinzip. Die Schwelle liegt nahe am Sockel und braucht einen geplanten Schutz gegen aufsteigende Feuchte und Spritzwasser. Beim Beschreiben einer Wand benennst du zuerst die Lage und danach die jeweilige Funktion des Holzes.",
      ["lf05-055", "lf05-057", "lf05-058", "lf05-106"], "Wozu dient die schräge Strebe zusätzlich zu den senkrechten Pfosten?", "Sie hilft, seitliche Kräfte aufzunehmen und die Wand gegen Verschieben auszusteifen. Die Pfosten allein sichern diese Aufgabe nicht.",
      fall("Der Wand fehlt seitlicher Halt", "Die Fehlerskizze zeigt nur rechteckige Rahmen ohne Strebe und ohne aussteifende Beplankung. Seitlicher Wind wirkt auf die Wand.", [["Eine wirksame Aussteifung ist in dieser Darstellung nicht erkennbar.", true], ["Die seitliche Lastabtragung muss ergänzt beziehungsweise nachgewiesen werden.", true], ["Senkrechte Pfosten ersetzen stets jede Aussteifung.", false]], "Rechtecke können sich bei gelenkigen Anschlüssen verschieben. Die Aussteifung muss als System vorhanden sein.", fehlendeWandstrebe)),
    einheit("lf05-l09", "Rahmenbau und Skelettbau unterscheiden", "Du kannst den Lastweg und die Rolle der Beplankung in beiden Systemen erklären.",
      "Beim Holzrahmenbau bilden dicht angeordnete Rippen das Tragwerk. Die Holzwerkstoffbeplankung verbindet die Rippen zu einer Wandtafel und übernimmt Aussteifungsaufgaben. Sie kann außerdem die Ständer gegen Knicken sichern und je nach Planung an der Lastaufnahme mitwirken. Ein abgestimmtes Raster erleichtert passende Plattenstöße und die Vorfertigung. Die Elemente werden häufig in der Werkhalle liegend hergestellt und auf der Baustelle aufgerichtet. Beim Holzskelettbau tragen dagegen Stützen und Träger in einem größeren Raster; die Wände müssen nicht selbst tragend sein. Beide Systeme brauchen einen geplanten Weg für Windkräfte über Wand- und Deckenscheiben oder andere Aussteifungen. Vorfertigung ersetzt diese statischen Zusammenhänge nicht.",
      ["lf05-065", "lf05-067", "lf05-068", "lf05-075"], "Welche andere Rolle spielen Wände im Holzskelettbau gegenüber tragenden Holzrahmenwänden?", "Im Skelettbau übernehmen Stützen und Träger die Tragstruktur; die Wände können nichttragend sein. Holzrahmenwände tragen über Rippen und Beplankung.",
      zuordnen("System und Aufgabe", [["Rippen", "Tragende Hölzer im Holzrahmenelement"], ["Beplankung", "Verbindet und steift die Wandtafel aus"], ["Stützen und Träger", "Tragstruktur des Skelettbaus"], ["Wand- und Deckenscheiben", "Mögliche Wege zur Abtragung von Windkräften"]], "Tragende Struktur und Gebäudeaussteifung werden in jedem System gemeinsam betrachtet.")),
    einheit("lf05-l22", "Von der Holzliste zur Bestellmenge", "Du kannst die Fertigmenge ermitteln und einen vorgegebenen Verschnittzuschlag anwenden.",
      "Die Holzliste sammelt Anzahl, Querschnitt und Länge aller benötigten Hölzer. Daraus entsteht die Fertigmenge, die tatsächlich eingebaut werden soll. Die Bestellmenge muss zusätzlich den vorgegebenen Verschnitt berücksichtigen. Dazu multiplizierst du die Fertigmenge mit dem Faktor eins plus Zuschlag geteilt durch hundert. Im Beispiel ergeben 3,5 m³ und 6 Prozent Zuschlag eine Rohmenge von 3,71 m³. Der Zuschlag wird hinzugefügt, nicht abgezogen. Für Dachschalung wird zunächst die Fläche berechnet. Zwei gleiche rechteckige Dachflächen von jeweils 6 m Sparrenlänge und 10 m Trauflänge ergeben zusammen 120 m². Prüfe anschließend, ob nach Fläche, laufenden Metern oder Volumen bestellt werden soll.",
      ["lf05-063", "lf05-064", "lf05-098", "lf05-099"], "Wie wird aus 3,5 m³ Fertigholz mit einem vorgegebenen Zuschlag von 6 Prozent die Rohmenge?", "3,5 · 1,06 = 3,71 m³. Zuerst wird die Fertigmenge bestimmt, danach der Zuschlag aufgeschlagen.",
      ordnen("Holzbedarf berechnen", ["Bauteile und Maße in der Holzliste erfassen", "Fertigmenge mit passenden Einheiten berechnen", "Vorgegebenen Verschnittzuschlag aufschlagen", "Rohmenge mit lieferbaren Abmessungen abgleichen"], "Erst der tatsächliche Bedarf, dann der Zuschlag und zuletzt die konkrete Bestellung.")),
  ] },
  { id: "lf05-k05", titel: "Dachtragwerke und ihre Anschlüsse", einheiten: [
    einheit("lf05-l04", "Dachsystem und Verbindung zusammen lesen", "Du kannst Sparren- und Pfettendach anhand ihres Tragprinzips unterscheiden.",
      "Beim Sparrendach bilden zwei Sparren mit dem unteren Zugband ein tragendes Dreieck. Dadurch kann der Dachraum ohne innenliegende Pfetten und Stützen bleiben. Beim Pfettendach liegen die Sparren als geneigte Balken auf waagerechten Pfetten. Diese geben Lasten über ihre Unterstützung weiter. Ein Kehlbalkendach ergänzt das Sparrenpaar um einen waagerechten Balken. Die gewählte Konstruktion beeinflusst, welche Anschlüsse benötigt werden. Eine Kerve bildet eine Auflagerfläche am Sparren, ein Versatz überträgt Druck zwischen schrägen und anderen Hölzern. Zapfen, Blattungen und metallische Verbindungsmittel erfüllen weitere Anschlussaufgaben. Jede Ausnehmung verändert den Querschnitt; deshalb werden Anschlüsse nach Planung und mit passenden Verbindungsmitteln ausgeführt.",
      ["lf05-060", "lf05-080", "lf05-084", "lf05-095"], "Was unterscheidet den Lastweg eines Pfettendaches vom einfachen Sparrendach?", "Beim Pfettendach liegen Sparren auf Pfetten, die Lasten weiterleiten. Beim Sparrendach bildet das Sparrenpaar mit dem Zugband das tragende Dreieck.",
      zuordnen("Tragwerk und Anschluss", [["Sparrendach", "Tragendes Dreieck aus Sparrenpaar und Zugband"], ["Pfettendach", "Sparren liegen auf waagerechten Pfetten"], ["Kerve", "Ausnehmung zur Auflagerung eines Sparrens"], ["Versatz", "Zimmermannsmäßiger Anschluss zur Druckübertragung"]], "Ein Anschluss wird aus dem Kraftweg heraus verstanden und nicht nur nach seinem Aussehen benannt.")),
    einheit("lf05-l12", "Alte Dachtragwerke vor Veränderungen verstehen", "Du kannst Sprengwerk und Hängewerk unterscheiden und die Bedeutung des Lastwegs begründen.",
      "Historische Dachstühle können nach Erfahrungsregeln errichtet worden sein und besondere Lastwege besitzen. Beim Sprengwerk führen Streben die Kräfte zu den Außenwänden. Beim Hängewerk hängt eine darunterliegende Decke an Hängepfosten; ihr Gewicht wird somit über das Dachtragwerk abgeleitet. Ein scheinbar nur im Weg stehendes Holz kann deshalb Lasten aus einem anderen Geschoss mittragen. Auch ältere Pfetten- und Kehlbalkenkonstruktionen besitzen unterschiedliche Unterstützungen und Aussteifungen. Vor einer Veränderung werden System, Zustand und Anschlüsse fachlich untersucht. Beim Sparrendach ist besonders der Fußpunkt wichtig, weil das tragende Dreieck dort geschlossen wird. Holz darf bei einer Sanierung nicht allein aufgrund seiner störenden Lage entfernt werden.",
      ["lf05-086", "lf05-087", "lf05-111", "lf05-113"], "Warum kann das Entfernen eines Hängepfostens auch die Decke unter dem Dach gefährden?", "Beim Hängewerk ist die Decke am Dachtragwerk aufgehängt. Der Pfosten kann daher Deckenlasten in das Dach weiterleiten.",
      fall("Pfosten stört den Ausbau", "In einem alten Dachstuhl soll ein senkrechtes Holz entfernt werden. Es ist noch ungeklärt, ob eine Decke daran aufgehängt ist.", [["Zuerst Tragwerk und Lastweg fachlich klären.", true], ["Auch Lasten aus der darunterliegenden Decke berücksichtigen.", true], ["Ein Holz unter dem First ist grundsätzlich entbehrlich.", false]], "Die Funktion wird vor der Veränderung geklärt, besonders bei historischen Tragwerken.")),
    einheit("lf05-l20", "Pfetten, Kehlbalken und Aussteifung", "Du kannst die Aufgaben von Pfetten und Aussteifungsdreiecken erklären.",
      "Pfetten sammeln die Lasten der aufliegenden Sparren und geben sie an Pfosten, Streben und tragende Bauteile weiter. Für seitliche Stabilität genügt dieser senkrechte Lastweg nicht. Kopfbänder und andere Streben bilden zusammen mit Pfetten und Pfosten steife Dreiecke. Beim liegenden Stuhl werden die Unterstützungen geneigt angeordnet, damit der Dachraum freier bleibt. Am Sparren darf eine Kerve den verbleibenden Querschnitt nicht unangemessen schwächen; Abmessungen und alternative Anschlüsse folgen der Planung. Ein Kehlbalken verbindet die beiden Sparren eines Paares und beeinflusst deren Tragverhalten. Besonders bei ungleichmäßiger Belastung müssen seine Anschlüsse funktionieren. Betrachte daher senkrechte Lastabtragung, Queraussteifung und Längsaussteifung als zusammengehörige Aufgaben.",
      ["lf05-080", "lf05-082", "lf05-083", "lf05-085"], "Warum braucht ein Pfettendach neben Pfetten und Pfosten auch eine Aussteifung?", "Der senkrechte Lastweg verhindert noch kein seitliches Verschieben. Streben und Kopfbänder schaffen dazu geeignete steife Dreiecke.",
      zuordnen("Aufgaben im Dachstuhl", [["Pfette", "Sammelt Lasten mehrerer Sparren"], ["Pfosten", "Leitet Kräfte aus der Pfette nach unten"], ["Kopfband", "Wirkt an einem Aussteifungsdreieck mit"], ["Kehlbalken", "Verbindet die Sparren eines Paares"]], "Die Lasten nach unten und die Stabilität gegen seitliche Bewegung werden getrennt verfolgt.")),
  ] },
  { id: "lf05-k06", titel: "Lasten, Öffnungen und Dachgestalt", einheiten: [
    einheit("lf05-l07", "Kräfte mit ihrer Richtung beschreiben", "Du kannst Lastarten unterscheiden und eine schräge Kraft mit vorgegebenem Winkel zerlegen.",
      "Zum Dachgewicht kommen wechselnde Einwirkungen wie Schnee, Wind oder Personen. Eigengewicht gehört zu den ständigen Lasten, solche wechselnden Einwirkungen zu den veränderlichen. Wind kann drücken und saugen; Sog kann Bauteile anheben und muss in den Befestigungen berücksichtigt werden. Kräfte besitzen deshalb neben einem Betrag immer auch eine Richtung. Zwei Kräfte lassen sich zeichnerisch im Kräfteparallelogramm zur Resultierenden zusammenfassen. Für eine einzelne schräge Kraft mit Winkel zur Waagerechten ergibt sich der horizontale Anteil aus Kosinus mal Kraft und der vertikale aus Sinus mal Kraft. Die Winkelangabe ist dabei entscheidend. Eine Skizze mit Achsen verhindert, dass die beiden Komponenten vertauscht werden.",
      ["lf05-100", "lf05-101", "lf05-104", "lf05-105"], "Welche Winkelfunktion liefert die Vertikalkomponente, wenn der Winkel zur Waagerechten gegeben ist?", "Fv = sin(α) · F. Die Horizontalkomponente ist Fh = cos(α) · F; bei anderer Winkeldefinition muss die Zuordnung erneut geprüft werden.",
      fall("Wind hebt das Dach", "Ein Anschluss wird nur für das Gewicht nach unten betrachtet. In der Aufgabe tritt zusätzlich Windsog auf.", [["Eine mögliche aufwärts gerichtete Einwirkung muss berücksichtigt werden.", true], ["Die Richtung gehört zur Beschreibung jeder Kraft.", true], ["Eine schwere Deckung ersetzt grundsätzlich den Nachweis der Befestigung.", false]], "Das Tragwerk und seine Befestigungen müssen zu den tatsächlich angesetzten Einwirkungen passen.")),
    einheit("lf05-l13", "Gauben und Auswechslungen planen", "Du kannst Gaubenformen beschreiben und den Zweck einer Auswechslung erklären.",
      "Eine Gaube vergrößert den nutzbaren Dachraum und bringt Licht durch ein senkrechtes Fenster. Ihr Name beschreibt häufig die kleine Dachform: Eine Schleppgaube hat eine geneigte Fläche, eine Sattelgaube zwei, eine Walmdachgaube einen vorderen Walm. Die Fledermausgaube bildet einen weich geschwungenen Übergang. Unabhängig von der Form muss der Eingriff zum Tragwerk passen. Werden für eine Öffnung Sparren unterbrochen, brauchen ihre Lasten einen neuen Weg. Eine Auswechslung leitet sie über Wechsel und anschließende Hölzer zu benachbarten tragenden Teilen. Diese Nachbarteile werden dadurch zusätzlich beansprucht. Das Ausschneiden beginnt deshalb erst nach der geplanten und gesicherten Lösung für Tragwerk und Bauzustand.",
      ["lf05-088", "lf05-089", "lf05-090"], "Welche Aufgabe hat die Auswechslung bei einem unterbrochenen Sparren?", "Sie leitet die Last des unterbrochenen Sparrens über Wechsel und Anschlüsse zu benachbarten tragenden Teilen weiter.",
      ordnen("Eine Dachöffnung vorbereiten", ["Dachtragwerk und geplante Öffnung erfassen", "Neuen Lastweg und benötigte Anschlüsse planen lassen", "Erforderliche Sicherungen und Auswechslung vorbereiten", "Sparren erst nach dem vorgesehenen Bauablauf unterbrechen"], "Der neue Lastweg muss vor dem Unterbrechen des alten Tragwegs geklärt sein.")),
    einheit("lf05-l21", "Dachform, Neigung und Rand benennen", "Du kannst Traufe und Ortgang lokalisieren und die Quelle einer Neigungseinteilung angeben.",
      "Beschreibe ein Dach mit Form, Neigung und seinen Rändern. Ein Pultdach hat eine geneigte Fläche, ein Satteldach zwei. Mansard-, Walm- und andere Formen ergänzen diese Grundbegriffe. Die Traufe liegt am unteren Rand einer geneigten Dachfläche, der Ortgang seitlich am Giebel. Überstände schützen Teile der Fassade gegen Niederschlag und können im Sommer verschatten. Ortgangziegel, Bretter oder besondere Lösungen für die jeweilige Deckung bilden den seitlichen Abschluss. Die vorliegende Buchquelle unterscheidet Neigungsbereiche mit Grenzen bei 5 und 40 Grad. Andere Quellen teilen anders ein. Nenne daher die verwendete Einteilung und leite aus dem Wort „Steildach“ allein keine passende Deckung oder Abdichtung ab.",
      ["lf05-078", "lf05-079", "lf05-091", "lf05-092"], "Wo liegen Traufe und Ortgang und warum braucht eine Neigungseinteilung eine Quellenangabe?", "Traufe unten an der Dachfläche, Ortgang seitlich am Giebel. Neigungsgrenzen unterscheiden sich zwischen Lehrquellen und legen den geeigneten Aufbau nicht allein fest.",
      zuordnen("Lage und Form beschreiben", [["Traufe", "Unterer Rand der geneigten Dachfläche"], ["Ortgang", "Seitlicher Rand am Giebel"], ["Pultdach", "Dach mit einer geneigten Hauptfläche"], ["Dachüberstand", "Kann Fassade schützen und verschatten"]], "Bezeichnungen helfen beim Beschreiben; die Ausführung wird passend zur Deckung geplant.")),
  ] },
];
const harterOberputz = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 190"><title>Fehlerskizze: mineralischer Putz mit hartem Oberputz auf weicherem Unterputz</title><g fill="none" stroke="currentColor" stroke-width="3"><path d="M45 30h110v130H45zM155 30h60v130h-60M215 30h25v130h-25"/><path d="m228 45-9 25 15 20-14 20 10 30" stroke="#c45f32"/></g><g fill="currentColor" font-family="sans-serif" font-size="16"><text x="60" y="182">Mauerwerk</text><text x="265" y="70">Unterputz: weicher</text><text x="265" y="112">Oberputz: härter</text><text x="265" y="150">außen →</text></g></svg>';
const lf06: LernKapitel[] = [
  { id: "lf06-k01", titel: "Dämmung, Feuchte und Metalle", einheiten: [
    einheit("lf06-l01", "Dämmwirkung mit Lambda vergleichen", "Du kannst Dämmstoffgruppen nennen und die Richtung der Wärmeleitfähigkeit erklären.",
      "Dämmstoffe bremsen den Wärmetransport vor allem durch eingeschlossene, weitgehend ruhende Luft in Poren oder zwischen Fasern. Mineralische Dämmstoffe sind etwa Glas- und Steinwolle. Zu den synthetischen gehören EPS, XPS und PUR beziehungsweise PIR. Holzfaser, Zellulose und Hanf stammen aus nachwachsenden Rohstoffen. Für den Vergleich ist die Wärmeleitfähigkeit Lambda wichtig. Je kleiner dieser Wert bei vergleichbaren Bedingungen ist, desto schlechter leitet das Material Wärme und desto besser dämmt es bei gleicher Dicke. Die Herkunft allein entscheidet jedoch nicht über die Eignung. Ein Produkt muss außerdem zum Einbauort, zur Feuchtebeanspruchung und zu den mechanischen Anforderungen passen. Unter Estrichen zählt beispielsweise auch das Verhalten unter Last.",
      ["lf06-042", "anhang2-023", "anhang2-069"], "Welcher von zwei Dämmstoffen dämmt bei gleicher Dicke besser: der mit größerem oder kleinerem Lambda?", "Der mit kleinerem Lambda leitet weniger Wärme. Für die tatsächliche Auswahl müssen weitere Anforderungen des Einbauorts berücksichtigt werden.",
      zuordnen("Dämmstoffgruppen erkennen", [["Steinwolle", "Mineralischer Dämmstoff"], ["XPS", "Synthetischer Hartschaum"], ["Holzfaser", "Dämmstoff aus nachwachsendem Rohstoff"], ["Kleines Lambda", "Geringe Wärmeleitung"]], "Materialgruppe und technische Kennzahl sind verschiedene Angaben zur Auswahl.")),
    einheit("lf06-l02", "Einbauort vor dem Dämmstoff wählen", "Du kannst Druck-, Feuchte- und Brandbeanspruchung bei einer Dämmstoffwahl berücksichtigen.",
      "Ein Dämmstoff muss mehr können als Wärme bremsen. Bei einer begehbaren oder belasteten Fläche zählt die geeignete Druckbelastbarkeit. In feuchtebeanspruchten Bereichen ist außerdem die Wasseraufnahme wichtig. Mineralwolle wird wegen ihres Brandverhaltens und ihrer schalltechnischen Eigenschaften eingesetzt; die konkrete Produktart bestimmt, welche Lasten sie verträgt. EPS und XPS sind verschiedene Polystyrolprodukte. Geschlossenzelliges XPS wird unter anderem für dafür geeignete Anwendungen mit Feuchtebeanspruchung verwendet. PUR und PIR besitzen eine geringe Wärmeleitfähigkeit und werden häufig als druckbelastbare Dachprodukte angeboten. Solche Materialnamen ersetzen keine Produktprüfung. Vergleiche Anwendungsgebiet, deklarierte Eigenschaften und Systemvorgaben. Ein gutes Produkt am falschen Einbauort bleibt eine ungeeignete Auswahl.",
      ["anhang2-062", "anhang2-064", "anhang2-065"], "Welche Angaben brauchst du zusätzlich zur Wärmeleitfähigkeit für eine belastete, feuchtebeanspruchte Dämmung?", "Unter anderem Eignung für den Einbauort, Druckbelastbarkeit, Wasseraufnahme, Brandverhalten und die Vorgaben des jeweiligen Dach- oder Bauteilsystems.",
      fall("Eine Dämmplatte nur nach Preis", "Für einen feuchtebeanspruchten und belasteten Einbauort soll die billigste Platte gewählt werden. Ihr Anwendungsgebiet ist noch unbekannt.", [["Druckbelastbarkeit und Verhalten bei Feuchte müssen geprüft werden.", true], ["Das ausgewiesene Anwendungsgebiet gehört zur Auswahl.", true], ["Gleiche Dicke macht alle Dämmplatten austauschbar.", false]], "Die Auswahl verbindet Dämmwirkung mit den Beanspruchungen des tatsächlichen Einbauorts.")),
    einheit("lf06-l03", "Patina und Metallverträglichkeit unterscheiden", "Du kannst eine schützende Patina und ein Korrosionsrisiko durch Kupferwasser erklären.",
      "Metalle am Dach reagieren unterschiedlich auf ihre Umgebung. Titanzink kann eine matte graublaue Patina bilden, Kupfer langfristig eine grüne. Solche natürlichen Oberflächenschichten können das darunterliegende Material schützen. Sie sind anders zu beurteilen als schädliche Korrosion durch ungünstige Feuchtebedingungen. Aluminium ist leicht, Edelstahl widerstandsfähig; trotzdem muss jede Werkstoffpaarung zur Einbausituation passen. Besonders wichtig ist die Fließrichtung des Regenwassers. Von Kupferflächen ablaufendes Wasser kann Kupferverbindungen mitführen und darunterliegendes Titanzink oder verzinkten Stahl schädigen. Prüfe deshalb nicht nur direkten Kontakt, sondern auch den gesamten Wasserweg. Eine passende Trennlage an einer Stelle löst nicht automatisch ein Problem durch belastetes Wasser von weiter oben.",
      ["anhang3-013", "anhang3-014", "anhang3-024"], "Warum kann Kupfer oberhalb einer Zinkrinne problematisch sein, obwohl die Metalle sich nicht berühren?", "Das ablaufende Wasser kann Kupferverbindungen nach unten transportieren und Korrosion am unedleren Zink begünstigen.",
      fall("Kupferdach über Zinkrinne", "Eine größere Kupferfläche entwässert direkt in eine Titanzinkrinne. Zwischen Dachblech und Rinne besteht kein direkter Metallkontakt.", [["Auch der Wasserweg kann ein Korrosionsrisiko erzeugen.", true], ["Die Werkstoffkombination muss passend geändert oder fachlich geplant werden.", true], ["Ohne direkte Berührung ist jede Kombination unproblematisch.", false]], "Wasser kann Stoffe transportieren. Werkstoffverträglichkeit wird daher entlang des gesamten Abflusswegs geprüft.")),
    einheit("lf06-l04", "Lambda, My und sd getrennt lesen", "Du kannst Wärmetransport und Wasserdampftransport anhand ihrer Kennwerte unterscheiden.",
      "Drei ähnlich oft genannte Kennwerte beantworten verschiedene Fragen. Lambda beschreibt, wie gut ein Stoff Wärme leitet. Die Diffusionswiderstandszahl My vergleicht den Widerstand gegen Wasserdampf mit ruhender Luft und besitzt keine Einheit. Erst zusammen mit der Schichtdicke entsteht der sd-Wert: sd gleich My mal Dicke in Metern. Er beschreibt eine gleichwertige Luftschichtdicke und hat ebenfalls die Einheit Meter. Eine dünne Bahn mit hohem My kann daher Wasserdampf stärker bremsen als eine dicke, diffusionsoffene Schicht. Dampfbremsen und Unterdeckbahnen haben unterschiedliche Aufgaben im geplanten Aufbau. Feuchtevariable Bahnen ändern ihr Verhalten mit den Bedingungen. Die sichere Funktion ergibt sich aus dem ganzen Bauteil, nicht aus einem Einzelwert.",
      ["anhang2-023", "anhang2-099", "anhang2-100"], "Warum reicht der My-Wert allein nicht aus, um die Wirkung einer eingebauten Schicht auf Wasserdampf zu beschreiben?", "Die Schichtdicke wirkt mit. Der sd-Wert ergibt sich aus My mal Dicke in Metern und beschreibt die äquivalente Luftschichtdicke.",
      zuordnen("Kennwert und Aussage", [["Lambda", "Beschreibt die Wärmeleitung"], ["My", "Vergleicht Diffusionswiderstand mit Luft"], ["sd", "My mal Schichtdicke in Metern"], ["Meter", "Einheit des sd-Werts"]], "Wärmedämmung und Wasserdampfbremse dürfen nicht über denselben Kennwert beurteilt werden.")),
  ] },
  { id: "lf06-k02", titel: "Putz aufbauen und ausführen", einheiten: [
    einheit("lf06-l05", "Unterputz, Oberputz und Verstärkung", "Du kannst den grundlegenden Putzaufbau sowie Putzträger und Bewehrung unterscheiden.",
      "Putz schafft eine ebene Oberfläche und schützt den Untergrund. Der Putzmörtel besteht aus Bindemittel, Gesteinskörnung, Wasser und gegebenenfalls Zusätzen. Die Körnung bildet das Gerüst, das Bindemittel verbindet es. Bei einem mehrlagigen mineralischen Aufbau gleicht der Unterputz Unebenheiten aus, während der Oberputz die sichtbare Struktur bildet. Im beschriebenen Grundmodell nimmt die Festigkeit nach außen ab: Ein zu harter Oberputz auf weicherem Unterputz kann reißen. Eine Putzbewehrung liegt im Mörtel und begrenzt die Rissneigung. Ein Putzträger liegt darunter und schafft Halt, beispielsweise über ungeeigneten Teilflächen. Innenputz kann außerdem Feuchte puffern; offenporiger Akustikputz vermindert Nachhall. Der gewählte Aufbau muss zum Untergrund und zur Beanspruchung passen.",
      ["lf06-002", "lf06-003", "lf06-004", "lf06-005"], "Wodurch unterscheiden sich Putzbewehrung und Putzträger?", "Bewehrung liegt im Putz und verbessert dessen Verhalten gegenüber Zug und Rissen. Ein Träger liegt darunter und stellt den Halt des Putzes sicher.",
      fall("Die äußere Lage ist härter", "Die Fehlerskizze zeigt einen mineralischen Grundaufbau mit weicherem Unterputz und deutlich härterem Oberputz.", [["Die dargestellte Festigkeitsabstufung widerspricht dem behandelten Grundmodell.", true], ["Der Aufbau muss auf passende, miteinander verträgliche Lagen geprüft werden.", true], ["Eine möglichst harte äußere Lage verhindert bei jedem Unterputz Risse.", false]], "Im behandelten mineralischen Grundmodell wird weich auf härter aufgebaut; konkrete Systemvorgaben werden zusätzlich beachtet.", harterOberputz)),
    einheit("lf06-l06", "Putzhaftung vor dem Auftrag sichern", "Du kannst Untergrundprüfung, Vorbehandlung und Standzeit in den Arbeitsablauf einordnen.",
      "Putz haftet nur auf einem dafür geeigneten Untergrund. Prüfe deshalb Tragfähigkeit, Sauberkeit, Feuchte, Frostfreiheit, Rauheit und Saugverhalten, bevor Material aufgetragen wird. Staub, lose Teile und haftungsmindernde Schichten werden beseitigt. Bei glatten oder schwach saugenden Flächen kann die vorgesehene Haftbrücke beziehungsweise Vorbehandlung nötig sein. Profile unterstützen ebene Flächen und schützen Kanten. Danach folgen die zum System passenden Lagen und die gewünschte Oberflächenbearbeitung, die Putzweise. Temperatur, Schichtdicke und Wartezeit beeinflussen das Erhärten. Die im Buch genannte Tagesregel pro Millimeter ist eine Orientierung im Übungsmodell und keine universelle Freigabe. Für die nächste Beschichtung zählen der tatsächliche Zustand und die Vorgaben des verwendeten Systems.",
      ["lf06-021", "lf06-022", "lf06-023", "lf06-079"], "Warum wird eine glatte Betonfläche vor dem Verputzen geprüft und gegebenenfalls vorbehandelt?", "Glätte, geringe Saugfähigkeit oder ungeeignete Feuchte können die Haftung begrenzen. Eine passende Vorbehandlung und ein geeigneter Zustand sichern den Putzauftrag.",
      ordnen("Putzarbeiten vorbereiten", ["Untergrund und Feuchtezustand prüfen", "Lose und haftungsmindernde Schichten entfernen", "Erforderliche Vorbehandlung und Profile ausführen", "Putzlagen systemgerecht auftragen und bearbeiten", "Zustand und erforderliche Standzeit vor weiterer Beschichtung prüfen"], "Die Oberflächenbearbeitung kann eine mangelhafte Untergrundvorbereitung nicht ausgleichen.")),
    einheit("lf06-l07", "Den Gipskreislauf verstehen", "Du kannst Erhärten von Gips und seine Wirkung im Brandfall erklären.",
      "Gipsstein enthält chemisch gebundenes Kristallwasser. Beim Brennen wird ein Teil dieses Wassers ausgetrieben. Aus entsprechend gebranntem und gemahlenem Material entsteht beispielsweise Stuckgips. Wird er mit Wasser angemacht, bilden sich wieder Gipskristalle und die Mischung erhärtet schnell. Anders aufbereitete Gipsbindemittel können länger verarbeitbar bleiben und eignen sich dadurch für Putzarbeiten. Gips ist im Innenbereich verbreitet, weil er sich gut zu Oberflächen verarbeiten lässt und Feuchte mit der Raumluft austauschen kann. Im Brandfall hat das gebundene Kristallwasser eine weitere Wirkung: Beim Verdampfen nimmt es Wärme auf und verzögert die Erwärmung. Die brandschutztechnische Leistung eines ganzen Bauteils hängt zusätzlich vom vollständigen Aufbau ab.",
      ["lf06-017", "lf06-018", "lf06-019", "lf06-020"], "Warum hilft das Kristallwasser im Gips beim Brandschutz?", "Beim Erwärmen verdampft gebundenes Wasser und nimmt dabei Wärme auf. Dadurch wird die Erwärmung des Bauteils verzögert.",
      ordnen("Vom Gipsstein zum erhärteten Gips", ["Gipsstein mit gebundenem Kristallwasser gewinnen", "Beim Brennen einen Teil des Kristallwassers austreiben", "Gebranntes Material zum Bindemittel aufbereiten", "Mit Wasser anmachen", "Neue Gipskristalle bilden lassen und erhärten"], "Das Anmachwasser ermöglicht die erneute Kristallbildung; bloßes Trocknen erklärt den Vorgang nicht vollständig.")),
    einheit("lf06-l13", "Putzmörtel richtig zusammensetzen", "Du kannst die Aufgaben von Bindemittel und Anmachwasser erklären.",
      "Mineralischer Putzmörtel enthält ein Bindemittel wie Kalk, Zement oder Gips, dazu Körnung und Anmachwasser. Das Bindemittel verbindet die Bestandteile, die Körnung bildet das Gerüst. Das Verhältnis muss stimmen: Zu viel Bindemittel kann bei bestimmten Mörteln Schwinden begünstigen, zu wenig mindert den Zusammenhalt. Wasser sorgt zunächst für Verarbeitbarkeit und wird bei der Erhärtung benötigt. Eine eigenmächtige Zugabe verändert daher mehr als nur die Konsistenz. Die Mörtelart wird nach Untergrund und Nutzung gewählt. Kalk-, Kalkzement-, Zement- und Gipsmörtel haben verschiedene Einsatzbereiche. Organisch gebundener Dispersionsputz bildet dagegen beim Wasserverlust einen Bindemittelfilm. Beachte für Mischung und Verarbeitung immer die Angaben des konkreten Produkts.",
      ["lf06-012", "lf06-013", "lf06-014", "lf06-016"], "Welche zwei Aufgaben hat das Anmachwasser in einem mineralischen Putzmörtel?", "Es macht den Mörtel verarbeitbar und wird für die Erhärtungsreaktionen benötigt. Die vorgesehene Menge darf deshalb nicht beliebig verändert werden.",
      zuordnen("Bestandteil und Wirkung", [["Bindemittel", "Verbindet die Bestandteile dauerhaft"], ["Körnung", "Bildet das feste Gerüst"], ["Anmachwasser", "Ermöglicht Verarbeitung und Erhärtung"], ["Dispersionsputz", "Bildet beim Trocknen einen Bindemittelfilm"]], "Die Art des Bindemittels beeinflusst Verarbeitung, Erhärtung und den geeigneten Einsatz.")),
    einheit("lf06-l14", "Außenputz nach seiner Aufgabe auswählen", "Du kannst Grundaufgaben, Wärmedämmputz und Sanierputz unterscheiden.",
      "Außenputz gestaltet die Fassade und schützt sie gegen Witterung sowie mechanische Einwirkungen. Er muss auf Untergrund und Beanspruchung abgestimmt sein, damit der Aufbau dauerhaft zusammenwirkt. Wärmedämmputz enthält leichte Zuschläge wie Perlit oder passende Kunststoffkügelchen. Die eingeschlossene Luft verringert die Wärmeleitung. Sanierputz verfolgt einen anderen Zweck: Sein poriger Aufbau und die hohe Wasserdampfdurchlässigkeit unterstützen das Verdunsten von Feuchte und nehmen Salze auf. Damit beseitigt er jedoch nicht automatisch die Ursache einer durchfeuchteten Wand. Feuchtequelle und Salzbelastung müssen zur Planung gehören. Verwechsle daher einen optisch erneuerten Putz nicht mit einer vollständig beseitigten Feuchteursache. Schutz, Wärmedämmung und Umgang mit Salz sind getrennte Auswahlaufgaben.",
      ["lf06-009", "lf06-010", "lf06-011", "lf06-084"], "Warum ersetzt Sanierputz nicht die Untersuchung einer dauerhaft feuchten Wand?", "Er unterstützt Verdunstung und Salzaufnahme, stoppt aber nicht automatisch den Feuchtenachschub. Ursache und Belastung müssen zusätzlich untersucht werden.",
      fall("Neuer Putz auf nasser Wand", "Auf eine dauerhaft feuchte, salzbelastete Wand soll Sanierputz aufgebracht werden. Die Feuchtequelle wurde noch nicht untersucht.", [["Feuchtequelle und Salzbelastung gehören zur Planung.", true], ["Der porige Sanierputz hat eine andere Aufgabe als Wärmedämmputz.", true], ["Sanierputz macht jede Ursachenklärung überflüssig.", false]], "Materialwahl und Ursachenbeseitigung müssen zusammen geplant werden.")),
  ] },
  { id: "lf06-k03", titel: "Innenausbau, Beläge und Bedarf", einheiten: [
    einheit("lf06-l12", "Gipsplatten passend zur Anforderung wählen", "Du kannst Trockenputz erklären und wichtige Plattentypen unterscheiden.",
      "Beim Wandtrockenputz bilden Gipsplatten die Oberfläche statt einer vollflächig nass aufgetragenen Putzlage. Die Platten werden direkt angesetzt oder auf einer Unterkonstruktion befestigt. Ihr Gipskern und die Kartonummantelung wirken zusammen. Typ A bezeichnet eine allgemeine Bauplatte, Typ F besitzt verbesserten Gefügezusammenhalt im Brandfall, Typ H eine reduzierte Wasseraufnahme. Weitere Typkennzeichen beschreiben besondere Eigenschaften. Eine imprägnierte Platte ist dennoch keine vollständige Abdichtung für jede Nassbeanspruchung. Die Ausführung richtet sich nach dem vorgesehenen System. Beidseitige Beplankung einer passenden Unterkonstruktion ergibt eine leichte Trennwand; eingelegte Dämmstoffe können deren Eigenschaften verbessern. Für Schall- und Brandschutz zählt die gesamte Wand einschließlich Anschlüssen, Fugen und Befestigungen.",
      ["lf06-027", "lf06-029", "lf06-080", "lf06-096"], "Warum reicht eine Feuerschutzplatte allein nicht als Nachweis für die Feuerwiderstandsdauer einer Wand?", "Die Leistung hängt vom ganzen System ab, also auch von Unterkonstruktion, Lagen, Fugen, Befestigungen und Anschlüssen.",
      zuordnen("Gipsplatte und Aufgabe", [["Typ A", "Allgemeine Bauplatte"], ["Typ F", "Verbesserter Gefügezusammenhalt im Brandfall"], ["Typ H", "Reduzierte Wasseraufnahme"], ["Vorsatzschale", "Bekleidung auf einer Unterkonstruktion"]], "Das Plattenkennzeichen beschreibt eine Eigenschaft; die Eignung entsteht im geplanten Aufbau.")),
    einheit("lf06-l10", "Estrichkonstruktionen unterscheiden", "Du kannst Verbund-, Trennschicht- und schwimmenden Estrich sowie eine Kurzbezeichnung erklären.",
      "Estrich schafft einen nutzbaren Untergrund, verteilt Lasten und kann Gefälle oder Heizrohre aufnehmen. Verbundestrich ist fest mit dem tragenden Untergrund verbunden. Estrich auf Trennschicht bleibt durch eine Zwischenlage getrennt. Schwimmender Estrich liegt auf Dämmung und wird von Wänden sowie Durchdringungen entkoppelt, damit Wärme- und Trittschallschutz funktionieren. Das Bindemittel erhält ein Kurzzeichen, beispielsweise CT für Zement oder CA für Calciumsulfat. C beschreibt die Druckfestigkeit, F die Biegezugfestigkeit. Dicke und Fugen folgen Konstruktion, Lasten, Material und Dämmung; eine einzige Dicke passt nicht überall. Fließestrich erleichtert den ebenen Einbau, Trockenestrich verwendet Fertigteile. Calciumsulfatestrich wird vor dauernder Feuchte geschützt. Vor Begehen oder Belasten wird die erforderliche Erhärtung abgewartet.",
      ["lf06-034", "lf06-036", "lf06-038", "lf06-092"], "Warum darf schwimmender Estrich keine starre Verbindung zur Wand haben?", "Er soll auf der Dämmschicht getrennt beweglich bleiben. Starre Verbindungen können insbesondere den Trittschallschutz beeinträchtigen.",
      zuordnen("Estrichbauarten erkennen", [["Verbundestrich", "Fest mit dem Untergrund verbunden"], ["Trennschichtestrich", "Durch eine Zwischenlage vom Untergrund getrennt"], ["Schwimmender Estrich", "Auf Dämmung und von Rändern entkoppelt"], ["CT", "Zementestrich"]], "Bauart, Bindemittel und Festigkeitsangaben beschreiben unterschiedliche Eigenschaften.")),
    einheit("lf06-l08", "Platten nach Material und Beanspruchung wählen", "Du kannst keramische und andere Platten unterscheiden und Maße mit Fugen berücksichtigen.",
      "Beläge werden nach technischen und gestalterischen Anforderungen ausgewählt. Zu Naturstein kommen künstliche keramische und nichtkeramische Platten. Keramik wird geformt und gebrannt, etwa stranggepresst oder trocken gepresst. Poröses Steingut nimmt mehr Wasser auf und bleibt im vorgesehenen Innenbereich; dichtes Steinzeug und geeigneter Klinker werden auch für frostbeanspruchte Anwendungen gewählt. Zusätzlich zählen Abrieb und Rutschsicherheit. Spaltplatten entstehen aus nach dem Brennen getrennten Doppelplatten. Betonwerkstein und zweischichtige Terrazzoplatten sind andere Produktgruppen; bitumengebundene Platten besitzen wiederum eigene Einsatzgrenzen. Beim Einteilen unterscheiden sich Werkmaß, Handelsnennmaß und Koordinierungsmaß. Das Koordinierungsmaß berücksichtigt die Fuge: C gleich W plus J. Kleine Mosaike und längliche Riemchen beeinflussen die Gestaltung, ersetzen aber keine technische Eignungsprüfung.",
      ["lf06-049", "lf06-051", "lf06-088", "lf06-098"], "Was kommt beim Koordinierungsmaß zum tatsächlichen Werkmaß einer Fliese hinzu?", "Die zugehörige Fugenbreite: C = W + J. Für die Auswahl zählen außerdem beispielsweise Frost-, Abrieb- und Rutscheigenschaften.",
      fall("Steingut für den Balkon", "Für einen frostbeanspruchten Balkon werden Wandfliesen aus porösem Steingut allein wegen ihrer Farbe ausgewählt.", [["Die technische Eignung für Frost muss geprüft werden.", true], ["Gestaltung ersetzt keine Prüfung der Wasseraufnahme und Produktfreigabe.", true], ["Jede glasierte Oberfläche macht eine Fliese automatisch frostbeständig.", false]], "Die Eignung des ganzen Produkts zählt, nicht nur das Aussehen seiner Oberfläche.")),
    einheit("lf06-l11", "Verlegeverfahren beginnt am Untergrund", "Du kannst Dickbett, Dünnbett und die drei Kleberauftragsarten unterscheiden.",
      "Vor Fliesenarbeiten wird der Belaggrund auf Tragfähigkeit, Sauberkeit, Ebenheit, Lage und Saugverhalten geprüft. Ein dickeres Mörtelbett kann bei dafür geeigneter Ausführung Unebenheiten aufnehmen. Dünnbett braucht dagegen bereits einen ebenen Untergrund. Beim Dickbett unterstützt das Anklopfen die mechanische Verzahnung des Mörtels mit geeigneten Fliesen. Die Auswahl des Klebers richtet sich nach Untergrund, Belag und Beanspruchung. Beim Floating wird er auf den Untergrund aufgetragen, beim Buttering auf die Plattenrückseite; die Kombination nutzt beide Seiten. Fugen und Bewegungsanschlüsse gehören zur geplanten Fläche. Bei Ziegelböden werden zusätzlich flach und hochkant verlegte Ausführungen sowie verschiedene Verbände unterschieden. Der Ablauf bleibt: Eignung prüfen, vorbereiten, verlegen und Anschlüsse ausführen.",
      ["lf06-060", "lf06-063", "lf06-065", "lf06-083"], "Worin unterscheiden sich Floating und Buttering und wann beginnt die Verlegearbeit fachlich?", "Floating trägt den Kleber auf den Untergrund auf, Buttering auf die Plattenrückseite. Fachlich beginnt die Arbeit mit der Prüfung und Vorbereitung des Belaggrunds.",
      zuordnen("Auftrag und Verfahren", [["Floating", "Kleber auf den Untergrund"], ["Buttering", "Kleber auf die Plattenrückseite"], ["Buttering-Floating", "Kleberauftrag auf beide Seiten"], ["Dünnbett", "Benötigt einen ausreichend ebenen Untergrund"]], "Ein geeigneter Kleber kann lose, verschmutzte oder falsch vorbereitete Untergründe nicht beliebig ausgleichen.")),
    einheit("lf06-l09", "Fläche, Zuschlag und Gebinde verbinden", "Du kannst Fliesen- und Mörtelbedarf mit passenden Einheiten berechnen.",
      "Materialbedarf wird in nachvollziehbaren Schritten gerechnet. Für Fliesen multiplizierst du Fläche und Stückbedarf je Quadratmeter. Auf den Grundbedarf kommt der vorgegebene Verschnittzuschlag; erst danach wird auf lieferbare Stückzahlen oder Pakete aufgerundet. Bei einer Mörtelschicht kannst du das Volumen bestimmen: Ein Quadratmeter mit einem Millimeter Dicke entspricht einem Liter. Für 7,5 m² und beispielhaft 25 mm entstehen damit 187,5 Liter. Die Sackzahl folgt aus Volumen geteilt durch Ergiebigkeit je Sack. Wird ein Verbrauch in kg je Quadratmeter angegeben, rechnest du zuerst die Masse und teilst dann durch den Sackinhalt in kg. Vermische diese beiden Wege nicht. Gebinde werden für die Bestellung passend aufgerundet.",
      ["lf06-069", "lf06-071", "lf06-089", "lf06-090"], "Warum darfst du 187,5 Liter Mörtel nicht direkt durch einen Sackinhalt von 25 kg teilen?", "Liter beschreiben Volumen, kg Masse. Benötigt wird die passende Ergiebigkeit in Litern je Sack oder ein vollständig massenbezogener Rechenweg.",
      ordnen("Fliesenbedarf bestellen", ["Zu belegende Fläche ermitteln", "Mit dem Stückbedarf je Quadratmeter multiplizieren", "Vorgegebenen Verschnittzuschlag auf den Grundbedarf rechnen", "Auf ganze Fliesen beziehungsweise lieferbare Pakete aufrunden"], "Der Zuschlag kommt vor der Anpassung an die lieferbare Verpackungseinheit.")),
  ] },
];

